import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface User {
  id: string;
  name: string;
  Number: string;
  password?: string;
  photo: string;
  anoFrequencia: number;
}

export interface Message {
  authorId: string;
  text: string;
  time: number;
  to: string;
}

export interface Publication {
  id: number;
  title: string;
  category: string;
  content: string;
  date: string;
}

export interface Artwork {
  userId: string;
  userName: string;
  userPhoto: string;
  description: string;
  media: string;
  mediaType: string;
  isImage: boolean;
  likes: number;
  likedBy: string[];
  comments: string[];
  timestamp: string;
}

export enum Theme {
  LIGHT = 'light',
  DARK = 'dark'
}

import { User, Message, Publication, Artwork, Theme } from '../types';

const USERS_KEY = 'ev_ul_users';
const CURRENT_USER_ID_KEY = 'ev_ul_current_id';
const MESSAGES_KEY = 'ev_ul_messages';
const PUBLICATIONS_KEY = 'ev_ul_publications';
const ARTWORKS_KEY = 'ev_ul_artworks';
const THEME_KEY = 'ev_ul_theme';

export const storage = {
  getUsers: (): User[] => JSON.parse(localStorage.getItem(USERS_KEY) || '[]'),
  setUsers: (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users)),

  getCurrentUserId: (): string | null => localStorage.getItem(CURRENT_USER_ID_KEY),
  setCurrentUserId: (id: string | null) => {
    if (id) localStorage.setItem(CURRENT_USER_ID_KEY, id);
    else localStorage.removeItem(CURRENT_USER_ID_KEY);
  },

  getMessages: (): Message[] => JSON.parse(localStorage.getItem(MESSAGES_KEY) || '[]'),
  setMessages: (messages: Message[]) => localStorage.setItem(MESSAGES_KEY, JSON.stringify(messages)),

  getPublications: (): Publication[] => JSON.parse(localStorage.getItem(PUBLICATIONS_KEY) || '[]'),
  setPublications: (pubs: Publication[]) => localStorage.setItem(PUBLICATIONS_KEY, JSON.stringify(pubs)),

  getArtworks: (): Artwork[] => JSON.parse(localStorage.getItem(ARTWORKS_KEY) || '[]'),
  setArtworks: (art: Artwork[]) => localStorage.setItem(ARTWORKS_KEY, JSON.stringify(art)),

  getTheme: (): Theme => (localStorage.getItem(THEME_KEY) as Theme) || Theme.LIGHT,
  setTheme: (theme: Theme) => localStorage.setItem(THEME_KEY, theme),

  getCurrentUser: (): User | null => {
    const id = storage.getCurrentUserId();
    if (!id) return null;
    return storage.getUsers().find(u => u.id === id) || null;
  },

  logout: () => {
    storage.setCurrentUserId(null);
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Home from './views/Home';
import About from './views/About';
import Chat from './views/Chat';
import Communities from './views/Communities';
import ArtGallery from './views/ArtGallery';
import Settings from './views/Settings';
import Login from './views/Login';
import { storage } from './services/storage';
import { Theme } from './types';

const AppContent: React.FC = () => {
  const [theme, setTheme] = useState<Theme>(storage.getTheme());
  const location = useLocation();
  const [isAuth, setIsAuth] = useState<boolean>(!!storage.getCurrentUserId());

  useEffect(() => {
    if (theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    storage.setTheme(theme);
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme(prev => (prev === Theme.LIGHT ? Theme.DARK : Theme.LIGHT));
  }, []);

  const checkAuth = useCallback(() => {
    setIsAuth(!!storage.getCurrentUserId());
  }, []);

  const requiresAuth = (component: React.ReactNode) => {
    return isAuth ? component : <Navigate to="/login" replace />;
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
      <Routes>
        <Route path="/" element={<Home toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />} />
        <Route path="/about" element={<About />} />
        <Route path="/chat" element={requiresAuth(<Chat />)} />
        <Route path="/communities" element={<Communities />} />
        <Route path="/gallery" element={<ArtGallery />} />
        <Route path="/settings" element={requiresAuth(<Settings onLogout={checkAuth} />)} />
        <Route path="/login" element={<Login onLogin={checkAuth} />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </div>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

import React from 'react';
import { useNavigate } from 'react-router-dom';

interface LayoutProps {
  title: string;
  children: React.ReactNode;
  showBackButton?: boolean;
  backTo?: string;
  actions?: React.ReactNode;
}

const Layout: React.FC<LayoutProps> = ({ title, children, showBackButton = true, backTo, actions }) => {
  const navigate = useNavigate();

  const handleBack = () => {
    if (backTo) navigate(backTo);
    else navigate(-1);
  };

  return (
    <div className="flex flex-col min-h-screen">
      <header className="bg-ev-blue sticky top-0 z-50 shadow-md">
        <div className="max-w-4xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            {showBackButton && (
              <button 
                onClick={handleBack}
                className="bg-white/20 hover:bg-white/30 text-white p-2 rounded-lg transition-colors"
              >
                <i className="fas fa-arrow-left"></i>
              </button>
            )}
            <h1 className="text-white font-bold text-lg">{title}</h1>
          </div>
          <div className="flex items-center gap-2">
            {actions}
          </div>
        </div>
      </header>
      <main className="flex-1 w-full max-w-4xl mx-auto p-4">
        {children}
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setUsers(storage.getUsers());
    setMessages(storage.getMessages());
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  const handleSend = () => {
    if (!inputText.trim() || !selectedUser || !currentUser) return;

    const newMessage: Message = {
      authorId: currentUser.id,
      text: inputText,
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
    setInputText('');
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) ||
           (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => {
    if (authorId === currentUser?.id) return 'Você';
    return users.find(u => u.id === authorId)?.name || 'Usuário';
  };

  const getAuthorPhoto = (authorId: string) => {
    return users.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';
  };

  if (selectedUser) {
    const chatTitle = selectedUser === 'general' ? 'Chat Geral' : selectedUser.name;
    const chatStatus = selectedUser === 'general' ? 'Todos os usuários' : 'Estudante';
    const chatPhoto = selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo;

    return (
      <Layout title={chatTitle} showBackButton={true} backTo="/chat" actions={
        <button onClick={() => setSelectedUser(null)} className="text-white text-sm bg-white/20 px-3 py-1 rounded-full">
          Contatos
        </button>
      }>
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-3xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <img src={chatPhoto} className="w-10 h-10 rounded-full object-cover" alt="" />
            <div>
              <h3 className="font-bold text-gray-800 dark:text-gray-100 leading-tight">{chatTitle}</h3>
              <p className="text-xs text-gray-500">{chatStatus}</p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40">
                <i className="fas fa-comments text-6xl mb-4"></i>
                <p>Nenhuma mensagem ainda.</p>
              </div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[80%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && (
                        <img src={getAuthorPhoto(msg.authorId)} className="w-8 h-8 rounded-full flex-shrink-0 mt-1" alt="" />
                      )}
                      <div>
                        {selectedUser === 'general' && !isMine && (
                          <p className="text-[10px] font-bold text-ev-blue ml-2 mb-0.5">{getAuthorName(msg.authorId)}</p>
                        )}
                        <div className={`p-3 rounded-2xl text-sm shadow-sm ${
                          isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-gray-100 dark:bg-gray-800 dark:text-gray-200 rounded-tl-none'
                        }`}>
                          <p>{msg.text}</p>
                          <p className={`text-[10px] mt-1 ${isMine ? 'text-white/60' : 'text-gray-400'}`}>
                            {new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-t border-gray-100 dark:border-gray-800 flex gap-2">
            <input
              type="text"
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Digite uma mensagem..."
              className="flex-1 bg-white dark:bg-gray-800 border-none rounded-full px-5 py-3 text-sm focus:ring-2 focus:ring-ev-blue shadow-inner dark:text-white"
            />
            <button 
              onClick={handleSend}
              className="w-12 h-12 bg-ev-blue text-white rounded-full flex items-center justify-center shadow-md hover:bg-blue-600 transition-colors"
            >
              <i className="fas fa-paper-plane"></i>
            </button>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Chat" backTo="/">
      <div className="space-y-3">
        <div 
          onClick={() => setSelectedUser('general')}
          className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-colors"
        >
          <div className="w-12 h-12 bg-ev-blue rounded-full flex items-center justify-center text-white">
            <i className="fas fa-users text-xl"></i>
          </div>
          <div className="flex-1">
            <h3 className="font-bold dark:text-white">Chat Geral</h3>
            <p className="text-xs text-gray-500">Mande um alô para todo mundo</p>
          </div>
        </div>

        <div className="mt-6 mb-2 ml-2">
          <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Contatos</h4>
        </div>

        {users.filter(u => u.id !== currentUser?.id).length === 0 ? (
          <div className="text-center py-10 opacity-40">
            <p>Nenhum outro usuário encontrado.</p>
          </div>
        ) : (
          users.filter(u => u.id !== currentUser?.id).map(user => (
            <div 
              key={user.id}
              onClick={() => setSelectedUser(user)}
              className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
            >
              <img src={user.photo} className="w-12 h-12 rounded-full object-cover border-2 border-ev-blue/20" alt="" />
              <div className="flex-1">
                <h3 className="font-bold dark:text-white">{user.name}</h3>
                <p className="text-xs text-gray-500">Estudante de Educação Visual</p>
              </div>
              <i className="fas fa-chevron-right text-gray-300"></i>
            </div>
          ))
        )}
      </div>
    </Layout>
  );
};

export default Chat;

import React, { useState, useEffect } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { Publication } from '../types';

const ACCESS_KEY = 'EVUL26';

const Communities: React.FC = () => {
  const [activeTab, setActiveTab] = useState<string>('geral');
  const [publications, setPublications] = useState<Publication[]>([]);
  const [isAuth, setIsAuth] = useState(false);
  const [accessKeyInput, setAccessKeyInput] = useState('');
  const [loginError, setLoginError] = useState('');
  const [form, setForm] = useState({ title: '', category: 'geral', content: '' });
  const [successMsg, setSuccessMsg] = useState('');

  useEffect(() => {
    setPublications(storage.getPublications());
  }, []);

  const handleLogin = () => {
    if (accessKeyInput === ACCESS_KEY) {
      setIsAuth(true);
      setLoginError('');
    } else {
      setLoginError('Chave de acesso incorreta!');
    }
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    const newPub: Publication = {
      id: Date.now(),
      title: form.title,
      category: form.category,
      content: form.content,
      date: new Date().toISOString()
    };

    const updated = [newPub, ...publications];
    setPublications(updated);
    storage.setPublications(updated);
    setForm({ title: '', category: 'geral', content: '' });
    setSuccessMsg('Publicado com sucesso!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const tabs = [
    { id: 'geral', label: 'Geral', icon: 'fa-info-circle' },
    { id: 'ano1', label: '1º Ano', icon: 'fa-user-graduate' },
    { id: 'ano2', label: '2º Ano', icon: 'fa-user-graduate' },
    { id: 'ano3', label: '3º Ano', icon: 'fa-user-graduate' },
    { id: 'ano4', label: '4º Ano', icon: 'fa-user-graduate' },
    { id: 'publicar', label: 'Publicar', icon: 'fa-plus-circle' },
  ];

  const filtered = publications.filter(pub => {
    if (activeTab === 'geral') return pub.category === 'geral';
    if (activeTab === 'publicar') return false;
    return pub.category === activeTab || pub.category === 'geral';
  });

  return (
    <Layout title="Comunidades" backTo="/">
      <div className="flex bg-ev-blue overflow-x-auto no-scrollbar rounded-2xl mb-6 shadow-md">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex-shrink-0 flex flex-col items-center justify-center py-4 px-5 transition-colors ${
              activeTab === tab.id ? 'bg-ev-brown text-white' : 'text-white/70 hover:bg-white/10'
            }`}
          >
            <i className={`fas ${tab.icon} mb-1`}></i>
            <span className="text-[10px] font-bold uppercase tracking-tighter whitespace-nowrap">{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="space-y-4">
        {activeTab === 'publicar' ? (
          <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700">
            <h2 className="text-xl font-bold text-ev-blue dark:text-white mb-6">Publicar Informação</h2>

            {!isAuth ? (
              <div className="space-y-4 max-w-sm mx-auto text-center">
                <p className="text-gray-600 dark:text-gray-400 text-sm">Autenticação necessária para publicar.</p>
                {loginError && <p className="text-red-500 text-xs bg-red-50 p-2 rounded">{loginError}</p>}
                <input
                  type="password"
                  placeholder="Chave de Acesso"
                  className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:text-white dark:border-gray-600"
                  value={accessKeyInput}
                  onChange={(e) => setAccessKeyInput(e.target.value)}
                />
                <button 
                  onClick={handleLogin}
                  className="w-full bg-ev-blue text-white py-3 rounded-xl font-bold hover:bg-blue-600"
                >
                  Entrar
                </button>
              </div>
            ) : (
              <form onSubmit={handlePublish} className="space-y-4">
                {successMsg && <p className="bg-green-100 text-green-700 p-3 rounded-xl text-center">{successMsg}</p>}
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Título</label>
                  <input
                    type="text"
                    required
                    className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:text-white dark:border-gray-600"
                    value={form.title}
                    onChange={(e) => setForm({ ...form, title: e.target.value })}
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Categoria</label>
                  <select
                    className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:text-white dark:border-gray-600"
                    value={form.category}
                    onChange={(e) => setForm({ ...form, category: e.target.value })}
                  >
                    <option value="geral">Geral</option>
                    <option value="ano1">1º Ano</option>
                    <option value="ano2">2º Ano</option>
                    <option value="ano3">3º Ano</option>
                    <option value="ano4">4º Ano</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Conteúdo</label>
                  <textarea
                    required
                    rows={5}
                    className="w-full p-3 rounded-xl border dark:bg-gray-700 dark:text-white dark:border-gray-600"
                    value={form.content}
                    onChange={(e) => setForm({ ...form, content: e.target.value })}
                  ></textarea>
                </div>
                <button type="submit" className="w-full bg-ev-blue text-white py-4 rounded-xl font-bold shadow-lg">
                  Publicar Agora
                </button>
                <button 
                  type="button"
                  onClick={() => setIsAuth(false)}
                  className="w-full text-gray-400 text-sm py-2"
                >
                  Sair
                </button>
              </form>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            {filtered.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-10 rounded-3xl shadow-sm text-center text-gray-400 border border-dashed border-gray-200 dark:border-gray-700">
                <i className="fas fa-inbox text-4xl mb-2"></i>
                <p>Nenhuma publicação encontrada.</p>
              </div>
            ) : (
              filtered.map(pub => (
                <div key={pub.id} className="bg-white dark:bg-gray-800 p-5 rounded-2xl shadow-sm border-l-4 border-ev-blue dark:border-ev-brown">
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="font-bold text-gray-800 dark:text-gray-100">{pub.title}</h3>
                    <span className="text-[10px] text-gray-400 bg-gray-50 dark:bg-gray-700 px-2 py-1 rounded">
                      {new Date(pub.date).toLocaleDateString()}
                    </span>
                  </div>
                  <p className="text-sm text-gray-600 dark:text-gray-300 whitespace-pre-wrap">{pub.content}</p>
                  <div className="mt-3 flex items-center gap-2">
                    <span className="text-[10px] font-bold text-ev-blue dark:text-ev-text-light uppercase tracking-widest bg-blue-50 dark:bg-blue-900/20 px-2 py-0.5 rounded">
                      {pub.category === 'geral' ? 'Geral' : `${pub.category.charAt(3)}º Ano`}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default Communities;

import React, { useState, useEffect } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { Artwork, User } from '../types';

const ArtGallery: React.FC = () => {
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [artworks, setArtworks] = useState<Artwork[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [description, setDescription] = useState('');
  const [mediaFile, setMediaFile] = useState<File | null>(null);

  useEffect(() => {
    setArtworks(storage.getArtworks());
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;
    if (!mediaFile) {
      alert('Selecione uma imagem ou vídeo');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const isImage = mediaFile.type.startsWith('image');
      const newArt: Artwork = {
        userId: currentUser.id,
        userName: currentUser.name,
        userPhoto: currentUser.photo,
        description: description,
        media: event.target?.result as string,
        mediaType: mediaFile.type,
        isImage: isImage,
        likes: 0,
        likedBy: [],
        comments: [],
        timestamp: new Date().toISOString()
      };

      const updated = [newArt, ...artworks];
      setArtworks(updated);
      storage.setArtworks(updated);
      setDescription('');
      setMediaFile(null);
      setView('feed');
    };
    reader.readAsDataURL(mediaFile);
  };

  const handleLike = (index: number) => {
    if (!currentUser) {
      alert('Faça login para curtir');
      return;
    }
    const updated = [...artworks];
    const art = updated[index];
    if (art.likedBy.includes(currentUser.id)) return;

    art.likes += 1;
    art.likedBy.push(currentUser.id);
    setArtworks(updated);
    storage.setArtworks(updated);
  };

  const addComment = (index: number, comment: string) => {
    if (!comment.trim()) return;
    const updated = [...artworks];
    updated[index].comments.push(`${currentUser?.name || 'Visitante'}: ${comment}`);
    setArtworks(updated);
    storage.setArtworks(updated);
  };

  return (
    <Layout title="Galeria de Arte" backTo="/" actions={
      <button 
        onClick={() => setView(view === 'feed' ? 'publish' : 'feed')}
        className="bg-white text-ev-blue px-3 py-1 rounded-full text-sm font-bold shadow-sm"
      >
        {view === 'feed' ? 'Publicar' : 'Ver Feed'}
      </button>
    }>
      <div className="space-y-6">
        {view === 'publish' ? (
          <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-lg border border-gray-100 dark:border-gray-700 max-w-lg mx-auto">
            <h2 className="text-xl font-bold mb-4 text-ev-blue dark:text-white">Compartilhe sua Arte</h2>
            {!currentUser ? (
              <div className="text-center p-6 bg-orange-50 dark:bg-orange-900/20 rounded-2xl">
                <i className="fas fa-lock text-3xl text-ev-brown mb-2"></i>
                <p className="text-sm text-gray-700 dark:text-gray-300">Você precisa estar logado para publicar conteúdo.</p>
                <a href="#/login" className="inline-block mt-4 bg-ev-blue text-white px-6 py-2 rounded-xl text-sm font-bold">Login</a>
              </div>
            ) : (
              <form onSubmit={handlePublish} className="space-y-4">
                <textarea
                  placeholder="Descrição da obra..."
                  className="w-full p-4 rounded-xl border dark:bg-gray-700 dark:border-gray-600 dark:text-white"
                  rows={4}
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
                <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-xl p-8 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
                  <input
                    type="file"
                    accept="image/*,video/*"
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    onChange={(e) => setMediaFile(e.target.files?.[0] || null)}
                  />
                  <div className="text-gray-400">
                    <i className="fas fa-cloud-upload-alt text-4xl mb-2"></i>
                    <p>{mediaFile ? mediaFile.name : 'Selecione uma Imagem ou Vídeo'}</p>
                  </div>
                </div>
                <button type="submit" className="w-full bg-ev-blue text-white py-4 rounded-xl font-bold shadow-md hover:bg-blue-600">
                  Publicar Obra
                </button>
              </form>
            )}
          </div>
        ) : (
          <div className="space-y-8">
            {artworks.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-12 rounded-3xl shadow-sm text-center text-gray-400">
                <i className="fas fa-palette text-5xl mb-4"></i>
                <p className="text-lg">Nenhuma obra publicada ainda.</p>
                <button onClick={() => setView('publish')} className="mt-4 text-ev-blue font-bold">Seja o primeiro!</button>
              </div>
            ) : (
              artworks.map((art, idx) => (
                <div key={idx} className="bg-white dark:bg-gray-800 rounded-3xl overflow-hidden shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
                  <div className="p-4 flex items-center gap-3">
                    <img src={art.userPhoto} className="w-10 h-10 rounded-full object-cover ring-2 ring-ev-blue/10" alt="" />
                    <div>
                      <h4 className="font-bold text-gray-800 dark:text-gray-100 leading-tight">{art.userName}</h4>
                      <p className="text-[10px] text-gray-400 uppercase tracking-widest">{new Date(art.timestamp).toLocaleDateString()}</p>
                    </div>
                  </div>

                  <div className="px-4 pb-3">
                    <p className="text-sm text-gray-700 dark:text-gray-300">{art.description}</p>
                  </div>

                  <div className="bg-black aspect-video flex items-center justify-center">
                    {art.isImage ? (
                      <img src={art.media} className="w-full h-full object-contain" alt="" />
                    ) : (
                      <video controls src={art.media} className="w-full h-full" />
                    )}
                  </div>

                  <div className="p-4 border-t border-gray-50 dark:border-gray-700">
                    <div className="flex items-center gap-6 mb-4">
                      <button 
                        onClick={() => handleLike(idx)}
                        disabled={currentUser ? art.likedBy.includes(currentUser.id) : false}
                        className={`flex items-center gap-2 transition-all ${
                          currentUser && art.likedBy.includes(currentUser.id) ? 'text-red-500' : 'text-gray-500 hover:text-red-500'
                        }`}
                      >
                        <i className={`fas fa-heart ${currentUser && art.likedBy.includes(currentUser.id) ? '' : 'fa-regular'}`}></i>
                        <span className="text-sm font-bold">{art.likes}</span>
                      </button>
                      <button className="flex items-center gap-2 text-gray-500 hover:text-ev-blue transition-all">
                        <i className="fa-regular fa-comment"></i>
                        <span className="text-sm font-bold">{art.comments.length}</span>
                      </button>
                    </div>

                    <div className="space-y-2 mb-4">
                      {art.comments.slice(-3).map((comment, cidx) => (
                        <p key={cidx} className="text-xs text-gray-600 dark:text-gray-400">
                          {comment}
                        </p>
                      ))}
                    </div>

                    {currentUser && (
                      <div className="flex gap-2">
                        <input
                          type="text"
                          placeholder="Adicionar comentário..."
                          className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-4 py-2 text-xs dark:text-white"
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              addComment(idx, (e.target as HTMLInputElement).value);
                              (e.target as HTMLInputElement).value = '';
                            }
                          }}
                        />
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

