import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import Footer from '../components/Footer';
import { storage } from '../services/storage';
import { Publication, Language } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const ACCESS_KEY = '000000';

const Communities: React.FC = () => {
  const [activeTab, setActiveTab] = useState<string>('geral');
  const [publications, setPublications] = useState<Publication[]>([]);
  const [isAuth, setIsAuth] = useState(false);
  const [accessKeyInput, setAccessKeyInput] = useState('');
  const [loginError, setLoginError] = useState('');
  const [form, setForm] = useState({ title: '', category: 'geral', content: '' });
  const [successMsg, setSuccessMsg] = useState('');
  const { language } = useContext(LanguageContext);

  useEffect(() => {
    setPublications(storage.getPublications());
  }, []);

  const handleLogin = () => {
    if (accessKeyInput === ACCESS_KEY) {
      setIsAuth(true);
      setLoginError('');
    } else {
      setLoginError(language === Language.PT ? 'Chave de acesso incorreta!' : language === Language.EN ? 'Incorrect access key!' : 'Clé d\'accès incorrecte!');
    }
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    const newPub: Publication = {
      id: Date.now(),
      title: form.title,
      category: form.category,
      content: form.content,
      date: new Date().toISOString()
    };

    const updated = [newPub, ...publications];
    setPublications(updated);
    storage.setPublications(updated);
    setForm({ title: '', category: 'geral', content: '' });
    setSuccessMsg(language === Language.PT ? 'Informação publicada com sucesso!' : 'Information published successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const tabs = [
    { id: 'geral', label: 'Geral', icon: 'fa-info-circle' },
    { id: 'ano1', label: '1º Ano', icon: 'fa-user-graduate' },
    { id: 'ano2', label: '2º Ano', icon: 'fa-user-graduate' },
    { id: 'ano3', label: '3º Ano', icon: 'fa-user-graduate' },
    { id: 'ano4', label: '4º Ano', icon: 'fa-user-graduate' },
    { id: 'publicar', label: t('publish', language), icon: 'fa-plus-circle' },
  ];

  const filtered = publications.filter(pub => {
    if (activeTab === 'geral') return pub.category === 'geral';
    if (activeTab === 'publicar') return false;
    return pub.category === activeTab || pub.category === 'geral';
  });

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-ev-dark">
      <header className="bg-ev-blue text-white px-4 py-3 flex items-center justify-between shadow-md z-50">
        <div className="flex items-center gap-4">
          <Link to="/" className="hover:scale-110 transition-transform">
            <i className="fas fa-arrow-left text-xl"></i>
          </Link>
          <h1 className="text-xl font-bold tracking-tight">{t('communities', language)}</h1>
        </div>
      </header>

      <div className="bg-ev-blue shadow-lg border-t border-white/10 z-40 sticky top-[52px]">
        <div className="max-w-6xl mx-auto flex overflow-x-auto no-scrollbar">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-shrink-0 flex flex-col items-center justify-center py-4 px-8 transition-all min-w-[100px] border-b-4 ${
                activeTab === tab.id ? 'bg-ev-brown border-white text-white' : 'text-white/60 border-transparent hover:bg-white/10'
              }`}
            >
              <i className={`fas ${tab.icon} mb-1 text-sm`}></i>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-4xl mx-auto w-full p-6 flex-1 py-10">
        <div className="space-y-6">
          {activeTab === 'publicar' ? (
            <div className="bg-white dark:bg-gray-800 p-10 rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h2 className="text-3xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8">{t('publish', language)}</h2>

              {!isAuth ? (
                <div className="max-w-sm mx-auto space-y-6 text-center py-10">
                  <div className="w-20 h-20 bg-ev-blue/10 rounded-full flex items-center justify-center text-ev-blue mx-auto mb-4">
                    <i className="fas fa-lock text-3xl"></i>
                  </div>
                  <p className="text-gray-500 text-sm">Apenas delegados e docentes podem publicar informações nestes canais.</p>
                  {loginError && <p className="text-red-500 text-xs font-bold bg-red-50 p-3 rounded-xl">{loginError}</p>}
                  <input
                    type="password"
                    placeholder="000000"
                    className="w-full p-4 rounded-2xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-center text-lg font-bold tracking-widest shadow-inner focus:ring-2 focus:ring-ev-blue"
                    value={accessKeyInput}
                    onChange={(e) => setAccessKeyInput(e.target.value)}
                  />
                  <button 
                    onClick={handleLogin}
                    className="w-full bg-ev-blue text-white py-4 rounded-2xl font-bold shadow-lg hover:bg-blue-600 transition-all uppercase tracking-widest"
                  >
                    Verificar Chave
                  </button>
                </div>
              ) : (
                <form onSubmit={handlePublish} className="space-y-6">
                  {successMsg && <div className="bg-green-100 text-green-700 p-4 rounded-2xl font-bold text-center animate-bounce">{successMsg}</div>}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-2">Título</label>
                      <input
                        type="text"
                        required
                        className="w-full p-4 rounded-2xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue"
                        value={form.title}
                        onChange={(e) => setForm({ ...form, title: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-2">Destinatários</label>
                      <select
                        className="w-full p-4 rounded-2xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue appearance-none cursor-pointer"
                        value={form.category}
                        onChange={(e) => setForm({ ...form, category: e.target.value })}
                      >
                        <option value="geral">Todos os Anos</option>
                        <option value="ano1">Estudantes 1º Ano</option>
                        <option value="ano2">Estudantes 2º Ano</option>
                        <option value="ano3">Estudantes 3º Ano</option>
                        <option value="ano4">Estudantes 4º Ano</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-2">Descrição</label>
                    <textarea
                      required
                      rows={6}
                      className="w-full p-5 rounded-2xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none"
                      value={form.content}
                      onChange={(e) => setForm({ ...form, content: e.target.value })}
                    ></textarea>
                  </div>
                  <div className="flex gap-4">
                    <button type="submit" className="flex-1 bg-ev-blue text-white py-4 rounded-2xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-widest">
                      Emitir Agora
                    </button>
                    <button 
                      type="button"
                      onClick={() => setIsAuth(false)}
                      className="px-6 bg-gray-100 dark:bg-gray-700 text-gray-400 rounded-2xl hover:text-red-500 transition-colors"
                    >
                      Sair
                    </button>
                  </div>
                </form>
              )}
            </div>
          ) : (
            <div className="space-y-6">
              {filtered.length === 0 ? (
                <div className="bg-white dark:bg-gray-800 p-20 rounded-[3rem] shadow-sm text-center text-gray-300 border border-dashed border-gray-200 dark:border-gray-700">
                  <i className="fas fa-bullhorn text-6xl mb-6 opacity-20"></i>
                  <p className="text-xl font-bold uppercase tracking-widest">Sem comunicados recentes</p>
                  <p className="text-sm mt-2">Esta comunidade está silenciosa por agora.</p>
                </div>
              ) : (
                filtered.map(pub => (
                  <div key={pub.id} className="bg-white dark:bg-gray-800 p-8 rounded-3xl shadow-sm border-l-[6px] border-ev-blue hover:shadow-lg transition-all border-gray-100 dark:border-gray-700">
                    <div className="flex justify-between items-start mb-4">
                      <h3 className="text-xl font-black text-gray-800 dark:text-white leading-tight uppercase tracking-tight">{pub.title}</h3>
                      <span className="text-[10px] font-bold text-gray-400 bg-gray-50 dark:bg-gray-700 px-3 py-1.5 rounded-full uppercase tracking-widest">
                        {new Date(pub.date).toLocaleDateString()}
                      </span>
                    </div>
                    <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-sm whitespace-pre-wrap">{pub.content}</p>
                    <div className="mt-6 flex items-center gap-2">
                      <div className="w-6 h-6 bg-ev-blue/10 rounded-full flex items-center justify-center text-[10px] text-ev-blue">
                        <i className="fas fa-tag"></i>
                      </div>
                      <span className="text-[10px] font-black text-ev-blue dark:text-ev-text-light uppercase tracking-[0.2em]">
                        {pub.category === 'geral' ? 'Informação Geral' : `Canal: ${pub.category.charAt(3)}º Ano`}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Communities;

