  onLogout: () => void;
  toggleTheme: () => void;
  isDark: boolean;
}

const Settings: React.FC<SettingsProps> = ({ onLogout, toggleTheme, isDark }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<string | null>('prefs');
  const navigate = useNavigate();
  const { language, setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    setUser(storage.getCurrentUser());
  }, []);

  const handleLogout = () => {
    storage.logout();
    onLogout();
    navigate('/login');
  };

  const sections = [
    { id: 'profile', title: t('profile', language), icon: 'fa-user' },
    { id: 'security', title: t('security', language), icon: 'fa-lock' },
    { id: 'notifications', title: t('notifications', language), icon: 'fa-bell' },
    { id: 'prefs', title: t('preferences', language), icon: 'fa-cog' },
  ];

  if (!user) return null;

  return (
    <Layout title={t('settings', language)} backTo="/">
      <div className="space-y-6">
        <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4">
          <img src={user.photo} className="w-16 h-16 rounded-full object-cover ring-4 ring-ev-blue/10" alt="" />
          <div>
            <h2 className="text-xl font-bold dark:text-white">{user.name}</h2>
            <p className="text-sm text-gray-500">#{user.Number} • {user.anoFrequencia}º Ano</p>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {sections.map(s => (
            <button
              key={s.id}
              onClick={() => setActiveSection(s.id)}
              className={`flex flex-col items-center justify-center p-4 rounded-2xl transition-all shadow-sm ${
                activeSection === s.id ? 'bg-ev-blue text-white scale-95' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'
              }`}
            >
              <i className={`fas ${s.icon} text-xl mb-1`}></i>
              <span className="text-[10px] font-bold uppercase tracking-widest">{s.title}</span>
            </button>
          ))}
        </div>

        <div className="space-y-4">
          {activeSection === 'profile' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h3 className="font-bold text-gray-800 dark:text-white mb-4">{t('profile', language)}</h3>
              <div className="space-y-3">
                <button 
                  onClick={handleLogout}
                  className="w-full text-left p-4 rounded-xl hover:bg-red-50 text-red-500 border border-red-100 flex items-center justify-between"
                >
                  <div className="flex items-center gap-3">
                    <i className="fas fa-sign-out-alt"></i>
                    <span className="text-sm font-bold">{t('logout', language)}</span>
                  </div>
                </button>
              </div>
            </div>
          )}

          {activeSection === 'prefs' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h3 className="font-bold text-gray-800 dark:text-white mb-4">{t('preferences', language)}</h3>
              <div className="space-y-4">
                {/* Language Picker */}
                <div className="flex flex-col gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('language', language)}</span>
                  <select 
                    className="bg-transparent text-sm font-bold outline-none dark:text-white"
                    value={language}
                    onChange={(e) => setLanguage(e.target.value as Language)}
                  >
                    <option value={Language.PT}>Português</option>
                    <option value={Language.EN}>English</option>
                    <option value={Language.FR}>Français</option>
                  </select>
                </div>

                {/* Theme Toggle */}
                <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                  <div className="flex flex-col">
                    <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('theme', language)}</span>
                    <span className="text-sm font-bold dark:text-white">{isDark ? 'Modo Escuro' : 'Modo Claro'}</span>
                  </div>
                  <button 
                    onClick={toggleTheme}
                    className={`w-14 h-8 flex items-center rounded-full p-1 transition-colors duration-300 ${isDark ? 'bg-ev-blue' : 'bg-gray-300'}`}
                  >
                    <div className={`bg-white w-6 h-6 rounded-full shadow-md transform transition-transform duration-300 ${isDark ? 'translate-x-6' : 'translate-x-0'} flex items-center justify-center`}>
                      <i className={`fas ${isDark ? 'fa-moon text-ev-blue' : 'fa-sun text-orange-400'} text-[10px]`}></i>
                    </div>
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

export default Settings;

import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Theme, Language } from '../types';
import { useNavigate } from 'react-router-dom';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

interface SettingsProps {
  onLogout: () => void;
  toggleTheme: () => void;
  isDark: boolean;
}

const Settings: React.FC<SettingsProps> = ({ onLogout, toggleTheme, isDark }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<string | null>('prefs');
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    number: '',
    anoFrequencia: 1,
    photo: ''
  });
  const [successMsg, setSuccessMsg] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const navigate = useNavigate();
  const { language, setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    const currentUser = storage.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
      setFormData({
        name: currentUser.name,
        number: currentUser.Number,
        anoFrequencia: currentUser.anoFrequencia,
        photo: currentUser.photo
      });
    }
  }, []);

  const handleLogout = () => {
    storage.logout();
    onLogout();
    navigate('/login');
  };

  const handleSaveProfile = () => {
    if (!user) return;

    const users = storage.getUsers();
    const updatedUsers = users.map(u => {
      if (u.id === user.id) {
        return {
          ...u,
          name: formData.name,
          Number: formData.number,
          anoFrequencia: formData.anoFrequencia,
          photo: formData.photo
        };
      }
      return u;
    });

    storage.setUsers(updatedUsers);
    const updatedUser = updatedUsers.find(u => u.id === user.id) || null;
    setUser(updatedUser);
    setIsEditing(false);
    setSuccessMsg(t('success_update', language));
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData({ ...formData, photo: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const sections = [
    { id: 'profile', title: t('profile', language), icon: 'fa-user' },
    { id: 'security', title: t('security', language), icon: 'fa-lock' },
    { id: 'notifications', title: t('notifications', language), icon: 'fa-bell' },
    { id: 'prefs', title: t('preferences', language), icon: 'fa-cog' },
  ];

  if (!user) return null;

  return (
    <Layout title={t('settings', language)} backTo="/">
      <div className="space-y-6">
        {successMsg && (
          <div className="bg-green-100 text-green-700 p-4 rounded-2xl font-bold text-center animate-bounce shadow-sm">
            {successMsg}
          </div>
        )}

        <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4">
          <div className="relative group">
            <img src={isEditing ? formData.photo : user.photo} className="w-16 h-16 rounded-full object-cover ring-4 ring-ev-blue/10" alt="" />
            {isEditing && (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <i className="fas fa-camera text-xs"></i>
              </button>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handlePhotoChange} 
            />
          </div>
          <div>
            <h2 className="text-xl font-bold dark:text-white">{user.name}</h2>
            <p className="text-sm text-gray-500">#{user.Number} • {user.anoFrequencia}º Ano</p>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {sections.map(s => (
            <button
              key={s.id}
              onClick={() => {
                setActiveSection(s.id);
                setIsEditing(false);
              }}
              className={`flex flex-col items-center justify-center p-4 rounded-2xl transition-all shadow-sm ${
                activeSection === s.id ? 'bg-ev-blue text-white scale-95' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'
              }`}
            >
              <i className={`fas ${s.icon} text-xl mb-1`}></i>
              <span className="text-[10px] font-bold uppercase tracking-widest">{s.title}</span>
            </button>
          ))}
        </div>

        <div className="space-y-4">
          {activeSection === 'profile' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <div className="flex items-center justify-between mb-6">
                <h3 className="font-bold text-gray-800 dark:text-white">{t('profile', language)}</h3>
                {!isEditing && (
                  <button 
                    onClick={() => setIsEditing(true)}
                    className="text-ev-blue text-xs font-bold uppercase tracking-widest hover:underline"
                  >
                    {t('edit_profile', language)}
                  </button>
                )}
              </div>

              {isEditing ? (
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">{t('full_name', language)}</label>
                    <input
                      type="text"
                      className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">{t('student_number', language)}</label>
                    <input
                      type="text"
                      className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                      value={formData.number}
                      onChange={(e) => setFormData({ ...formData, number: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">{t('year', language)}</label>
                    <select
                      className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner appearance-none"
                      value={formData.anoFrequencia}
                      onChange={(e) => setFormData({ ...formData, anoFrequencia: parseInt(e.target.value) })}
                    >
                      <option value={1}>1º Ano</option>
                      <option value={2}>2º Ano</option>
                      <option value={3}>3º Ano</option>
                      <option value={4}>4º Ano</option>
                    </select>
                  </div>
                  <div className="flex gap-3 pt-4">
                    <button 
                      onClick={handleSaveProfile}
                      className="flex-1 bg-ev-blue text-white py-3 rounded-xl font-bold shadow-md hover:bg-blue-600 transition-colors uppercase text-xs"
                    >
                      {t('save', language)}
                    </button>
                    <button 
                      onClick={() => setIsEditing(false)}
                      className="px-6 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 rounded-xl text-xs font-bold uppercase"
                    >
                      {t('cancel', language)}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                    <span className="text-[10px] font-bold text-gray-400 uppercase block mb-1">{t('full_name', language)}</span>
                    <span className="text-sm font-medium dark:text-white">{user.name}</span>
                  </div>
                  <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                    <span className="text-[10px] font-bold text-gray-400 uppercase block mb-1">{t('student_number', language)}</span>
                    <span className="text-sm font-medium dark:text-white">{user.Number}</span>
                  </div>
                  <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                    <span className="text-[10px] font-bold text-gray-400 uppercase block mb-1">{t('year', language)}</span>
                    <span className="text-sm font-medium dark:text-white">{user.anoFrequencia}º Ano</span>
                  </div>

                  <div className="pt-4">
                    <button 
                      onClick={handleLogout}
                      className="w-full text-left p-4 rounded-xl hover:bg-red-50 dark:hover:bg-red-900/10 text-red-500 border border-red-100 dark:border-red-900/30 flex items-center justify-between transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <i className="fas fa-sign-out-alt"></i>
                        <span className="text-sm font-bold">{t('logout', language)}</span>
                      </div>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeSection === 'prefs' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h3 className="font-bold text-gray-800 dark:text-white mb-4">{t('preferences', language)}</h3>
              <div className="space-y-4">
                {/* Language Picker */}
                <div className="flex flex-col gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('language', language)}</span>
                  <select 
                    className="bg-transparent text-sm font-bold outline-none dark:text-white cursor-pointer"
                    value={language}
                    onChange={(e) => setLanguage(e.target.value as Language)}
                  >
                    <option value={Language.PT}>Português</option>
                    <option value={Language.EN}>English</option>
                    <option value={Language.FR}>Français</option>
                  </select>
                </div>

                {/* Theme Toggle */}
                <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                  <div className="flex flex-col">
                    <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('theme', language)}</span>
                    <span className="text-sm font-bold dark:text-white">{isDark ? 'Modo Escuro' : 'Modo Claro'}</span>
                  </div>
                  <button 
                    onClick={toggleTheme}
                    className={`w-14 h-8 flex items-center rounded-full p-1 transition-colors duration-300 ${isDark ? 'bg-ev-blue' : 'bg-gray-300'}`}
                  >
                    <div className={`bg-white w-6 h-6 rounded-full shadow-md transform transition-transform duration-300 ${isDark ? 'translate-x-6' : 'translate-x-0'} flex items-center justify-center`}>
                      <i className={`fas ${isDark ? 'fa-moon text-ev-blue' : 'fa-sun text-orange-400'} text-[10px]`}></i>
                    </div>
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

export default Settings;

