                    <span className="text-[10px] font-bold text-gray-400 uppercase block mb-1">{t('student_number', language)}</span>
                    <span className="text-sm font-medium dark:text-white">{user.Number}</span>
                  </div>
                  <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                    <span className="text-[10px] font-bold text-gray-400 uppercase block mb-1">{t('year', language)}</span>
                    <span className="text-sm font-medium dark:text-white">{user.anoFrequencia}º Ano</span>
                  </div>

                  <div className="pt-4">
                    <button 
                      onClick={handleLogout}
                      className="w-full text-left p-4 rounded-xl hover:bg-red-50 dark:hover:bg-red-900/10 text-red-500 border border-red-100 dark:border-red-900/30 flex items-center justify-between transition-colors"
                    >
                      <div className="flex items-center gap-3">
                        <i className="fas fa-sign-out-alt"></i>
                        <span className="text-sm font-bold">{t('logout', language)}</span>
                      </div>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeSection === 'prefs' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h3 className="font-bold text-gray-800 dark:text-white mb-4">{t('preferences', language)}</h3>
              <div className="space-y-4">
                {/* Language Picker */}
                <div className="flex flex-col gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('language', language)}</span>
                  <select 
                    className="bg-transparent text-sm font-bold outline-none dark:text-white cursor-pointer"
                    value={language}
                    onChange={(e) => setLanguage(e.target.value as Language)}
                  >
                    <option value={Language.PT}>Português</option>
                    <option value={Language.EN}>English</option>
                    <option value={Language.FR}>Français</option>
                  </select>
                </div>

                {/* Theme Toggle */}
                <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-700 rounded-xl">
                  <div className="flex flex-col">
                    <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('theme', language)}</span>
                    <span className="text-sm font-bold dark:text-white">{isDark ? 'Modo Escuro' : 'Modo Claro'}</span>
                  </div>
                  <button 
                    onClick={toggleTheme}
                    className={`w-14 h-8 flex items-center rounded-full p-1 transition-colors duration-300 ${isDark ? 'bg-ev-blue' : 'bg-gray-300'}`}
                  >
                    <div className={`bg-white w-6 h-6 rounded-full shadow-md transform transition-transform duration-300 ${isDark ? 'translate-x-6' : 'translate-x-0'} flex items-center justify-center`}>
                      <i className={`fas ${isDark ? 'fa-moon text-ev-blue' : 'fa-sun text-orange-400'} text-[10px]`}></i>
                    </div>
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

