const Chat: React.FC = () => {
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const currentUser = storage.getCurrentUser();
  const endRef = useRef<HTMLDivElement>(null);
  useEffect(() => { setUsers(storage.getUsers()); setMessages(storage.getMessages()); }, []);
  useEffect(() => endRef.current?.scrollIntoView({ behavior: 'smooth' }), [messages, selectedUser]);
  const handleSend = () => {
    if (!inputText.trim() || !selectedUser || !currentUser) return;
    const msg: Message = { authorId: currentUser.id, text: inputText, time: Date.now(), to: typeof selectedUser === 'string' ? 'general' : selectedUser.id };
    const updated = [...messages, msg]; setMessages(updated); storage.setMessages(updated); setInputText('');
  };
  const filtered = messages.filter(m => {
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser?.id && m.to === (selectedUser as User).id) || (m.authorId === (selectedUser as User).id && m.to === currentUser?.id);
  });
  if (selectedUser) return (
    <Layout title={selectedUser === 'general' ? 'Chat Geral' : selectedUser.name} backTo="/chat" actions={<button onClick={() => setSelectedUser(null)} className="text-white text-xs bg-white/20 px-3 py-1 rounded-full uppercase">Voltar</button>}>
      <div className="flex flex-col h-[70vh] bg-white dark:bg-gray-900 rounded-3xl shadow-lg border border-gray-100 dark:border-gray-800">
        <div className="flex-1 overflow-y-auto p-4 space-y-3 no-scrollbar">
          {filtered.map((m, i) => {
            const isMine = m.authorId === currentUser?.id;
            return (
              <div key={i} className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}>
                <div className={`p-3 rounded-2xl text-sm max-w-[80%] ${isMine ? 'bg-ev-blue text-white' : 'bg-gray-100 dark:bg-gray-800 dark:text-gray-200'}`}>
                  {m.text}
                </div>
              </div>
            );
          })}
          <div ref={endRef} />
        </div>
        <div className="p-4 bg-gray-50 dark:bg-gray-800 flex gap-2">
          <input value={inputText} onChange={e => setInputText(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSend()} className="flex-1 p-3 rounded-full text-sm dark:bg-gray-700 dark:text-white" placeholder="Mensagem..." />
          <button onClick={handleSend} className="w-10 h-10 bg-ev-blue text-white rounded-full"><i className="fas fa-paper-plane"></i></button>
        </div>
      </div>
    </Layout>
  );
  return (
    <Layout title="Mensagens" backTo="/">
      <div className="space-y-3">
        <div onClick={() => setSelectedUser('general')} className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm flex items-center gap-4 cursor-pointer">
          <div className="w-12 h-12 bg-ev-blue rounded-full flex items-center justify-center text-white"><i className="fas fa-users"></i></div>
          <div><h3 className="font-bold dark:text-white">Chat Geral</h3><p className="text-xs text-gray-500">Mural Público</p></div>
        </div>
        {users.filter(u => u.id !== currentUser?.id).map(u => (
          <div key={u.id} onClick={() => setSelectedUser(u)} className="bg-white dark:bg-gray-800 p-4 rounded-2xl shadow-sm flex items-center gap-4 cursor-pointer">
            <img src={u.photo} className="w-12 h-12 rounded-full object-cover" />
            <div><h3 className="font-bold dark:text-white">{u.name}</h3><p className="text-xs text-gray-500">{u.anoFrequencia}º Ano</p></div>
          </div>
        ))}
      </div>
    </Layout>
  );
};

