const Login: React.FC<{onLogin: () => void}> = ({ onLogin }) => {
  const [isReg, setIsReg] = useState(false);
  const [form, setForm] = useState({ name: '', number: '', password: '' });
  const navigate = useNavigate();
  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    const users = storage.getUsers();
    if (isReg) {
      const newUser: User = { id: 'u_'+Date.now(), name: form.name, Number: form.number, password: form.password, photo: 'https://picsum.photos/seed/u/200', anoFrequencia: 1 };
      storage.setUsers([...users, newUser]); storage.setCurrentUserId(newUser.id);
    } else {
      const u = users.find(u => u.Number === form.number && u.password === form.password);
      if (!u) { alert('Erro!'); return; } storage.setCurrentUserId(u.id);
    }
    onLogin(); navigate('/');
  };
  return (
    <div className="min-h-screen bg-ev-blue flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-[2.5rem] shadow-2xl overflow-hidden p-8">
        <div className="text-center mb-8"><h1 className="text-2xl font-black text-ev-blue uppercase tracking-widest">{isReg ? 'Criar Conta' : 'Entrar'}</h1></div>
        <form onSubmit={submit} className="space-y-4">
          {isReg && <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className="w-full p-4 rounded-2xl bg-gray-50 border-none" placeholder="Nome Completo" required />}
          <input value={form.number} onChange={e => setForm({...form, number: e.target.value})} className="w-full p-4 rounded-2xl bg-gray-50 border-none" placeholder="Número de Estudante" required />
          <input type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} className="w-full p-4 rounded-2xl bg-gray-50 border-none" placeholder="Senha" required />
          <button className="w-full bg-ev-blue text-white py-4 rounded-2xl font-bold shadow-lg uppercase tracking-widest">{isReg ? 'Cadastrar' : 'Entrar'}</button>
        </form>
        <button onClick={() => setIsReg(!isReg)} className="w-full mt-6 text-ev-blue text-sm font-bold">{isReg ? 'Já tem conta? Login' : 'Não tem conta? Registe-se'}</button>
      </div>
    </div>
  );
};

