    if (theme === Theme.DARK) root.classList.add('dark'); else root.classList.remove('dark');
    storage.setTheme(theme);
  }, [theme]);
  const toggleTheme = useCallback(() => setTheme(prev => prev === Theme.LIGHT ? Theme.DARK : Theme.LIGHT), []);
  const checkAuth = useCallback(() => setIsAuth(!!storage.getCurrentUserId()), []);
  const reqAuth = (comp: React.ReactNode) => isAuth ? comp : <Navigate to="/login" replace />;
  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      <div className="min-h-screen bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
        <Routes>
          <Route path="/" element={<Home toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />} />
