];

const Library: React.FC = () => {
  const { category } = useParams<{ category: string }>();
  const { language } = useContext(LanguageContext);
  const navigate = useNavigate();
  const [items, setItems] = useState<LibraryItem[]>([]);
  const [view, setView] = useState<'list' | 'add'>('list');
  const [searchTerm, setSearchTerm] = useState('');
  const [form, setForm] = useState({ title: '', author: '', description: '', file: '' });
  const [isUploading, setIsUploading] = useState(false);

  const currentUser = storage.getCurrentUserId();

  // Categories that allow adding files
  const categoryAllowsAdd = category === 'trabalhos' || category === 'materiais' || category === 'mono';

  useEffect(() => {
    const stored = storage.getLibraryItems();
    const combined = [...githubRawData, ...stored];
    setItems(combined.filter(item => item.category === category));
  }, [category]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setForm({ ...form, file: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleToggleView = () => {
    if (view === 'list') {
      if (!currentUser) {
        navigate('/login');
        return;
      }
      setView('add');
    } else {
      setView('list');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.file) {
      alert(t('select_file', language));
      return;
    }

    setIsUploading(true);

    const newItem: LibraryItem = {
      id: 'l_' + Date.now(),
      title: form.title,
      author: form.author,
      category: category as any,
      date: new Date().toISOString().split('T')[0],
      description: form.description,
      downloadUrl: form.file // In a real app, this would be a URL from a server
    };

    const stored = storage.getLibraryItems();
    const updated = [newItem, ...stored];
    storage.setLibraryItems(updated);

    setTimeout(() => {
      setItems(updated.filter(item => item.category === category));
      setForm({ title: '', author: '', description: '', file: '' });
      setIsUploading(false);
      setView('list');
    }, 1500);
  };

