import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Theme, Language } from '../types';
import { useNavigate } from 'react-router-dom';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

interface SettingsProps {
  onLogout: () => void;
  toggleTheme: () => void;
  isDark: boolean;
}

const Settings: React.FC<SettingsProps> = ({ onLogout, toggleTheme, isDark }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<string | null>('profile');
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    photo: ''
  });
  const [successMsg, setSuccessMsg] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const navigate = useNavigate();
  const { language, setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    const currentUser = storage.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
      setFormData({
        name: currentUser.name,
        photo: currentUser.photo
      });
    }
  }, []);

  const handleLogout = () => {
    storage.logout();
    onLogout();
    navigate('/login');
  };

  const handleSaveProfile = () => {
    if (!user) return;

    const users = storage.getUsers();
    const updatedUsers = users.map(u => {
      if (u.id === user.id) {
        return {
          ...u,
          name: formData.name,
          photo: formData.photo
        };
      }
      return u;
    });

    storage.setUsers(updatedUsers);
    const updatedUser = updatedUsers.find(u => u.id === user.id) || null;
    setUser(updatedUser);
    setIsEditing(false);
    setSuccessMsg(t('success_update', language));
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData({ ...formData, photo: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const sections = [
    { id: 'profile', title: t('profile', language), icon: 'fa-user' },
    { id: 'security', title: t('security', language), icon: 'fa-lock' },
    { id: 'notifications', title: t('notifications', language), icon: 'fa-bell' },
    { id: 'prefs', title: t('preferences', language), icon: 'fa-cog' },
  ];

  if (!user) return null;

  return (
    <Layout title={t('settings', language)} backTo="/">
      <div className="space-y-6">
        {successMsg && (
          <div className="bg-green-100 text-green-700 p-4 rounded-2xl font-bold text-center animate-bounce shadow-sm">
            {successMsg}
          </div>
        )}

        {/* Profile Summary Card */}
        <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4">
          <div className="relative group">
            <img 
              src={isEditing ? formData.photo : user.photo} 
              className="w-20 h-20 rounded-full object-cover ring-4 ring-ev-blue/10 shadow-lg" 
              alt="Avatar" 
            />
            {isEditing && (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/50 rounded-full flex flex-col items-center justify-center text-white transition-opacity hover:bg-black/60"
              >
                <i className="fas fa-camera text-xl"></i>
                <span className="text-[8px] font-bold uppercase mt-1">{t('change_photo', language)}</span>
              </button>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handlePhotoChange} 
            />
          </div>
          <div>
            <h2 className="text-xl font-black text-gray-800 dark:text-white leading-tight">
              {isEditing ? formData.name || '...' : user.name}
            </h2>
            <p className="text-sm text-gray-500 font-medium">#{user.Number} • {user.anoFrequencia}º Ano</p>
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {sections.map(s => (
            <button
              key={s.id}
              onClick={() => {
                setActiveSection(s.id);
                setIsEditing(false);
              }}
              className={`flex flex-col items-center justify-center p-4 rounded-2xl transition-all shadow-sm ${
                activeSection === s.id ? 'bg-ev-blue text-white scale-95 shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'
              }`}
            >
              <i className={`fas ${s.icon} text-xl mb-1`}></i>
              <span className="text-[10px] font-bold uppercase tracking-widest">{s.title}</span>
            </button>
          ))}
        </div>

        {/* Section Content */}
        <div className="space-y-4">
          {activeSection === 'profile' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <div className="flex items-center justify-between mb-6">
                <h3 className="font-black text-ev-blue dark:text-white uppercase tracking-tighter">{t('profile', language)}</h3>
                {!isEditing && (
                  <button 
                    onClick={() => setIsEditing(true)}
                    className="bg-ev-blue/10 text-ev-blue px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-ev-blue hover:text-white transition-all"
                  >
                    {t('edit_profile', language)}
                  </button>
                )}
              </div>

              {isEditing ? (
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('full_name', language)}</label>
                    <input
                      type="text"
                      className="w-full p-4 rounded-2xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner transition-all"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      placeholder="Introduza o seu nome"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('student_number', language)}</label>
                      <div className="w-full p-4 rounded-2xl bg-gray-100 dark:bg-gray-900 dark:text-gray-500 text-sm italic font-medium">
                        {user.Number}
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('year', language)}</label>
                      <div className="w-full p-4 rounded-2xl bg-gray-100 dark:bg-gray-900 dark:text-gray-500 text-sm italic font-medium">
                        {user.anoFrequencia}º Ano
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-3 pt-4">
                    <button 
                      onClick={handleSaveProfile}
                      className="flex-1 bg-ev-blue text-white py-4 rounded-2xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase text-xs tracking-widest"
                    >
                      {t('save', language)}
                    </button>
                    <button 
                      onClick={() => {
                        setIsEditing(false);
                        setFormData({
                          name: user.name,
                          photo: user.photo
                        });
                      }}
                      className="px-6 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 rounded-2xl text-xs font-black uppercase tracking-widest"
                    >
                      {t('cancel', language)}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-3">
                  <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-2xl border border-gray-100 dark:border-gray-700">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('full_name', language)}</span>
                    <span className="text-base font-bold text-gray-800 dark:text-white">{user.name}</span>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-2xl border border-gray-100 dark:border-gray-700">
                      <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('student_number', language)}</span>
                      <span className="text-base font-bold text-gray-800 dark:text-white">{user.Number}</span>
                    </div>
                    <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-2xl border border-gray-100 dark:border-gray-700">
                      <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('year', language)}</span>
                      <span className="text-base font-bold text-gray-800 dark:text-white">{user.anoFrequencia}º Ano</span>
                    </div>
                  </div>

                  <div className="pt-6">
                    <button 
                      onClick={handleLogout}
                      className="w-full text-left p-5 rounded-2xl hover:bg-red-50 dark:hover:bg-red-900/10 text-red-500 border border-red-100 dark:border-red-900/30 flex items-center justify-between transition-all group"
                    >
                      <div className="flex items-center gap-3">
                        <i className="fas fa-sign-out-alt group-hover:rotate-12 transition-transform"></i>
                        <span className="text-sm font-black uppercase tracking-widest">{t('logout', language)}</span>
                      </div>
                      <i className="fas fa-chevron-right text-[10px] opacity-30"></i>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeSection === 'prefs' && (
            <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h3 className="font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-6">{t('preferences', language)}</h3>
              <div className="space-y-4">
                <div className="flex flex-col gap-2 p-5 bg-gray-50 dark:bg-gray-700 rounded-2xl border border-gray-100 dark:border-gray-700">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{t('language', language)}</span>
                  <select 
                    className="bg-transparent text-sm font-bold outline-none dark:text-white cursor-pointer appearance-none"
                    value={language}
                    onChange={(e) => setLanguage(e.target.value as Language)}
                  >
                    <option value={Language.PT}>Português (Moçambique)</option>
                    <option value={Language.EN}>English (International)</option>
                    <option value={Language.FR}>Français (Francophonie)</option>
                  </select>
                </div>

                <div className="flex items-center justify-between p-5 bg-gray-50 dark:bg-gray-700 rounded-2xl border border-gray-100 dark:border-gray-700">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{t('theme', language)}</span>
                    <span className="text-sm font-bold dark:text-white">{isDark ? 'Modo Escuro' : 'Modo Claro'}</span>
                  </div>
                  <button 
                    onClick={toggleTheme}
                    className={`w-14 h-8 flex items-center rounded-full p-1 transition-colors duration-500 shadow-inner ${isDark ? 'bg-ev-blue' : 'bg-gray-300'}`}
                  >
                    <div className={`bg-white w-6 h-6 rounded-full shadow-lg transform transition-transform duration-300 ${isDark ? 'translate-x-6' : 'translate-x-0'}`}></div>
                  </button>
                </div>
              </div>
            </div>
          )}

          {(activeSection === 'security' || activeSection === 'notifications') && (
            <div className="bg-white dark:bg-gray-800 p-12 rounded-3xl shadow-md border border-gray-100 dark:border-gray-700 text-center space-y-4 animate-fadeIn">
              <i className="fas fa-tools text-4xl text-gray-200"></i>
              <p className="text-gray-400 text-sm font-medium italic">Esta funcionalidade estará disponível em breve.</p>
            </div>
          )}
        </div>
      </div>
    </Layout>
  );
};

export default Settings;

import React, { useState, useEffect, useCallback, createContext } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Home from './views/Home';
import About from './views/About';
import Chat from './views/Chat';
import Communities from './views/Communities';
import ArtGallery from './views/ArtGallery';
import Settings from './views/Settings';
import Login from './views/Login';
import Library from './views/Library';
import { storage } from './services/storage';
import { Theme, Language } from './types';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
}

export const LanguageContext = createContext<LanguageContextType>({
  language: Language.PT,
  setLanguage: () => {},
});

const AppContent: React.FC = () => {
  const [theme, setTheme] = useState<Theme>(storage.getTheme());
  const [language, setLanguageState] = useState<Language>(storage.getLanguage());
  const [isAuth, setIsAuth] = useState<boolean>(!!storage.getCurrentUserId());

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    storage.setLanguage(lang);
  };

  useEffect(() => {
    if (theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    storage.setTheme(theme);
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme(prev => (prev === Theme.LIGHT ? Theme.DARK : Theme.LIGHT));
  }, []);

  const checkAuth = useCallback(() => {
    setIsAuth(!!storage.getCurrentUserId());
  }, []);

  const requiresAuth = (component: React.ReactNode) => {
    return isAuth ? component : <Navigate to="/login" replace />;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      <div className="min-h-screen bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
        <Routes>
          <Route path="/" element={<Home toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />} />
          <Route path="/about" element={<About />} />
          <Route path="/chat" element={requiresAuth(<Chat />)} />
          <Route path="/communities" element={requiresAuth(<Communities />)} />
          <Route path="/communities/:tab" element={requiresAuth(<Communities />)} />
          <Route path="/gallery" element={<ArtGallery />} />
          <Route path="/library/:category" element={<Library />} />
          <Route path="/settings" element={requiresAuth(<Settings onLogout={checkAuth} toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />)} />
          <Route path="/login" element={<Login onLogin={checkAuth} />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </LanguageContext.Provider>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

