import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { UserPost, User, Language } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const UserPosts: React.FC = () => {
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [posts, setPosts] = useState<UserPost[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [caption, setCaption] = useState('');
  const [mediaData, setMediaData] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<string>('');
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState('');

  const { language } = useContext(LanguageContext);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    setPosts(storage.getPosts());
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');
    if (file) {
      // Check for video duration if it's a video
      if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
          window.URL.revokeObjectURL(video.src);
          if (video.duration > 30) {
            setError(language === Language.PT ? 'O vídeo não pode ter mais de 30 segundos.' : 'Video cannot be longer than 30 seconds.');
            setMediaData(null);
            return;
          }
          readFile(file);
        };
        video.src = URL.createObjectURL(file);
      } else {
        readFile(file);
      }
    }
  };

  const readFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setMediaData(event.target?.result as string);
      setMediaType(file.type);
    };
    reader.readAsDataURL(file);
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser || !mediaData) return;

    setIsUploading(true);
    const newPost: UserPost = {
      id: 'post_' + Date.now(),
      userId: currentUser.id,
      userName: currentUser.name,
      userPhoto: currentUser.photo,
      caption: caption,
      media: mediaData,
      mediaType: mediaType,
      isImage: mediaType.startsWith('image/'),
      timestamp: new Date().toISOString()
    };

    const updated = [newPost, ...posts];
    setPosts(updated);
    storage.setPosts(updated);

    setTimeout(() => {
      setCaption('');
      setMediaData(null);
      setIsUploading(false);
      setView('feed');
    }, 1000);
  };

  return (
    <Layout 
      title={t('posts', language)} 
      backTo="/" 
      actions={
        <button 
          onClick={() => {
            setView(view === 'feed' ? 'publish' : 'feed');
            setError('');
          }}
          className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm"
        >
          {view === 'feed' ? t('publish', language) : t('view', language)}
        </button>
      }
    >
      <div className="max-w-2xl mx-auto pb-10">
        {view === 'publish' ? (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8">{t('publish', language)}</h2>

            <form onSubmit={handlePublish} className="space-y-6">
              {error && (
                <div className="bg-red-50 text-red-500 p-4 rounded-2xl text-xs font-bold text-center border border-red-100">
                  <i className="fas fa-exclamation-triangle mr-2"></i> {error}
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Legenda / Descrição</label>
                <textarea
                  className="w-full p-4 rounded-2xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none"
                  rows={3}
                  placeholder="Diga algo sobre esta publicação..."
                  value={caption}
                  onChange={(e) => setCaption(e.target.value)}
                />
              </div>

              <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-3xl p-10 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                <input
                  type="file"
                  accept="image/*,video/*"
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  onChange={handleFileChange}
                />

                {mediaData ? (
                  <div className="space-y-4">
                    {mediaType.startsWith('image/') ? (
                      <img src={mediaData} className="max-h-64 mx-auto rounded-2xl shadow-lg" alt="Preview" />
                    ) : (
                      <div className="relative inline-block">
                        <video src={mediaData} className="max-h-64 mx-auto rounded-2xl shadow-lg" />
                        <div className="absolute top-2 right-2 bg-black/60 text-white text-[10px] font-bold px-2 py-1 rounded-full">
                          VÍDEO (MAX 30s)
                        </div>
                      </div>
                    )}
                    <p className="text-[10px] font-bold text-ev-blue uppercase tracking-widest">Clique para alterar</p>
                  </div>
                ) : (
                  <div className="text-gray-400">
                    <div className="w-16 h-16 bg-gray-100 dark:bg-gray-600 rounded-2xl flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                      <i className="fas fa-photo-video text-2xl text-ev-blue"></i>
                    </div>
                    <p className="font-bold uppercase tracking-widest text-xs">Selecione Mídia</p>
                    <p className="text-[10px] mt-2 italic">Imagem ou Vídeo (máx. 30 segundos)</p>
                  </div>
                )}
              </div>

              <button 
                type="submit" 
                disabled={!mediaData || isUploading}
                className={`w-full py-4 rounded-2xl font-black shadow-xl transition-all uppercase tracking-widest flex items-center justify-center gap-3 ${
                  !mediaData ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-ev-blue text-white hover:bg-blue-600'
                }`}
              >
                {isUploading ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                  <>
                    <i className="fas fa-paper-plane"></i>
                    {t('publish', language)}
                  </>
                )}
              </button>
            </form>
          </div>
        ) : (
          <div className="space-y-10">
            {posts.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-20 rounded-[3rem] shadow-sm text-center border border-dashed border-gray-200 dark:border-gray-700">
                <div className="w-20 h-20 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center mx-auto mb-6">
                  <i className="fas fa-images text-3xl text-gray-300"></i>
                </div>
                <h3 className="text-xl font-black text-gray-400 uppercase tracking-widest">Feed Vazio</h3>
                <p className="text-sm text-gray-400 mt-2 italic">Seja o primeiro a partilhar um momento!</p>
                <button onClick={() => setView('publish')} className="mt-6 text-ev-blue font-bold underline">Publicar Agora</button>
              </div>
            ) : (
              posts.map((post) => (
                <div key={post.id} className="bg-white dark:bg-gray-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden animate-fadeIn transition-transform hover:scale-[1.01]">
                  <div className="p-6 flex items-center gap-4">
                    <img src={post.userPhoto} className="w-12 h-12 rounded-full object-cover ring-2 ring-ev-blue/10" alt="" />
                    <div>
                      <h4 className="font-black text-gray-800 dark:text-white leading-tight">{post.userName}</h4>
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                        {new Date(post.timestamp).toLocaleDateString()} • {new Date(post.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                      </p>
                    </div>
                  </div>

                  {post.caption && (
                    <div className="px-6 pb-4">
                      <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium">
                        {post.caption}
                      </p>
                    </div>
                  )}

                  <div className="bg-black/5 dark:bg-black/20 aspect-video flex items-center justify-center relative group">
                    {post.isImage ? (
                      <img src={post.media} className="w-full h-full object-contain" alt="" />
                    ) : (
                      <video controls src={post.media} className="w-full h-full" />
                    )}
                    {!post.isImage && (
                      <div className="absolute top-4 right-4 bg-white/20 backdrop-blur-md px-3 py-1 rounded-full text-[9px] font-black text-white uppercase tracking-widest pointer-events-none">
                        Video
                      </div>
                    )}
                  </div>

                  <div className="p-6 flex items-center justify-between border-t border-gray-50 dark:border-gray-700">
                     <div className="flex gap-4">
                        <button className="text-gray-400 hover:text-red-500 transition-colors">
                           <i className="far fa-heart text-xl"></i>
                        </button>
                        <button className="text-gray-400 hover:text-ev-blue transition-colors">
                           <i className="far fa-comment text-xl"></i>
                        </button>
                     </div>
                     <button className="text-gray-300 hover:text-gray-500">
                        <i className="far fa-bookmark text-xl"></i>
                     </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

