import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { storage } from '../services/storage';
import { User } from '../types';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    number: '',
    password: '',
    confirmPassword: '',
    photo: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const formatStudentNumber = (value: string) => {
    // Remove all non-digits
    const digits = value.replace(/\D/g, '');

    // Apply masking XX.XXXX.XXXX
    let formatted = digits;
    if (digits.length > 2) {
      formatted = `${digits.substring(0, 2)}.${digits.substring(2)}`;
    }
    if (digits.length > 6) {
      formatted = `${digits.substring(0, 2)}.${digits.substring(2, 6)}.${digits.substring(6, 10)}`;
    }

    return formatted.substring(0, 12); // Limit length
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const formatted = formatStudentNumber(e.target.value);
    setFormData({ ...formData, number: formatted });
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData({ ...formData, photo: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const users = storage.getUsers();

    if (isRegister) {
      if (formData.password !== formData.confirmPassword) {
        setError('Senhas não coincidem');
        setLoading(false);
        return;
      }
      if (users.some(u => u.Number === formData.number)) {
        setError('Este número já está registrado');
        setLoading(false);
        return;
      }

      const newUser: User = {
        id: 'u_' + Math.random().toString(36).substr(2, 9),
        name: formData.name,
        Number: formData.number,
        password: formData.password,
        photo: formData.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=',
        anoFrequencia: 1
      };

      storage.setUsers([...users, newUser]);
      storage.setCurrentUserId(newUser.id);
    } else {
      const user = users.find(u => u.Number === formData.number && u.password === formData.password);
      if (!user) {
        setError('Credenciais incorretas');
        setLoading(false);
        return;
      }
      storage.setCurrentUserId(user.id);
    }

    setTimeout(() => {
      onLogin();
      navigate('/');
    }, 1000);
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-ev-dark flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-3xl shadow-xl overflow-hidden animate-fadeIn">
        <div className="p-8 text-center bg-ev-blue">
          <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 text-ev-blue shadow-lg">
            <i className="fas fa-building text-2xl"></i>
          </div>
          <h1 className="text-2xl font-bold text-white uppercase tracking-widest">
            {isRegister ? 'Cadastro' : 'Entrar'}
          </h1>
          <p className="text-white/70 text-sm mt-1">Plataforma EV-UL</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-4">
            {error && (
              <div className="bg-red-50 text-red-500 p-3 rounded-xl text-xs font-bold text-center animate-shake">
                {error}
              </div>
            )}

            {isRegister && (
              <div className="flex flex-col items-center gap-3 mb-4">
                <div className="relative group">
                  <div className="w-24 h-24 rounded-full overflow-hidden border-4 border-gray-100 bg-gray-50 flex items-center justify-center">
                    {formData.photo ? (
                      <img src={formData.photo} className="w-full h-full object-cover" alt="" />
                    ) : (
                      <i className="fas fa-camera text-gray-300 text-3xl"></i>
                    )}
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoChange}
                    className="absolute inset-0 opacity-0 cursor-pointer"
                  />
                </div>
                <span className="text-[10px] text-gray-400 font-bold uppercase">Foto de Perfil</span>
              </div>
            )}

            {isRegister && (
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Nome Completo</label>
                <input
                  type="text"
                  required
                  placeholder="Seu nome"
                  className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>
            )}

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Número de Estudante (XX.XXXX.XXXX)</label>
              <input
                type="text"
                required
                placeholder="00.0000.0000"
                className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                value={formData.number}
                onChange={handleNumberChange}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Senha</label>
              <input
                type="password"
                required
                placeholder="••••••••"
                className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              />
            </div>

            {isRegister && (
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Confirmar Senha</label>
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  className="w-full p-4 rounded-xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                  value={formData.confirmPassword}
                  onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
                />
              </div>
            )}

            <button 
              type="submit"
              disabled={loading}
              className="w-full bg-ev-blue text-white py-4 rounded-xl font-bold shadow-lg hover:bg-blue-600 transition-all flex items-center justify-center gap-2"
            >
              {loading ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              ) : (
                isRegister ? 'Criar Conta' : 'Entrar'
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <button 
              onClick={() => {
                setIsRegister(!isRegister);
                setError('');
              }}
              className="text-ev-blue text-sm font-bold hover:underline"
            >
              {isRegister ? 'Já tem uma conta? Entre aqui' : 'Não tem conta? Cadastre-se'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { UserPost, User, Language, Comment } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const UserPosts: React.FC = () => {
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [posts, setPosts] = useState<UserPost[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [caption, setCaption] = useState('');
  const [mediaData, setMediaData] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<string>('');
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState('');
  const [activeCommentId, setActiveCommentId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');

  const { language } = useContext(LanguageContext);

  useEffect(() => {
    const storedPosts = storage.getPosts();
    // Initialize potential missing fields in old data
    const migrations = storedPosts.map(p => ({
      ...p,
      likes: p.likes || 0,
      likedBy: p.likedBy || [],
      comments: p.comments || []
    }));
    setPosts(migrations);
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');
    if (file) {
      if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
          window.URL.revokeObjectURL(video.src);
          if (video.duration > 30) {
            setError(language === Language.PT ? 'O vídeo não pode ter mais de 30 segundos.' : 'Video cannot be longer than 30 seconds.');
            setMediaData(null);
            return;
          }
          readFile(file);
        };
        video.src = URL.createObjectURL(file);
      } else {
        readFile(file);
      }
    }
  };

  const readFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setMediaData(event.target?.result as string);
      setMediaType(file.type);
    };
    reader.readAsDataURL(file);
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser || !mediaData) return;

    setIsUploading(true);
    const newPost: UserPost = {
      id: 'post_' + Date.now(),
      userId: currentUser.id,
      userName: currentUser.name,
      userPhoto: currentUser.photo,
      caption: caption,
      media: mediaData,
      mediaType: mediaType,
      isImage: mediaType.startsWith('image/'),
      timestamp: new Date().toISOString(),
      likes: 0,
      likedBy: [],
      comments: []
    };

    const updated = [newPost, ...posts];
    setPosts(updated);
    storage.setPosts(updated);

    setTimeout(() => {
      setCaption('');
      setMediaData(null);
      setIsUploading(false);
      setView('feed');
    }, 1000);
  };

  const handleLike = (postId: string) => {
    if (!currentUser) return;

    const updated = posts.map(post => {
      if (post.id === postId) {
        const hasLiked = post.likedBy.includes(currentUser.id);
        const newLikedBy = hasLiked 
          ? post.likedBy.filter(id => id !== currentUser.id)
          : [...post.likedBy, currentUser.id];

        return {
          ...post,
          likedBy: newLikedBy,
          likes: newLikedBy.length
        };
      }
      return post;
    });

    setPosts(updated);
    storage.setPosts(updated);
  };

  const handleAddComment = (postId: string) => {
    if (!currentUser || !commentText.trim()) return;

    const newComment: Comment = {
      authorName: currentUser.name,
      authorPhoto: currentUser.photo,
      text: commentText,
      timestamp: new Date().toISOString()
    };

    const updated = posts.map(post => {
      if (post.id === postId) {
        return {
          ...post,
          comments: [...(post.comments || []), newComment]
        };
      }
      return post;
    });

    setPosts(updated);
    storage.setPosts(updated);
    setCommentText('');
    setActiveCommentId(null);
  };

  return (
    <Layout 
      title={t('posts', language)} 
      backTo="/" 
      actions={
        <button 
          onClick={() => {
            setView(view === 'feed' ? 'publish' : 'feed');
            setError('');
          }}
          className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm"
        >
          {view === 'feed' ? t('publish', language) : t('view', language)}
        </button>
      }
    >
      <div className="max-w-2xl mx-auto pb-10">
        {view === 'publish' ? (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8">{t('publish', language)}</h2>

