export default Home;

import React, { useState, useEffect, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    setUsers(storage.getUsers());
    setMessages(storage.getMessages());
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;

    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else {
      processFile(file);
    }
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({
        media: event.target?.result as string,
        mediaType: file.type,
        fileName: file.name
      });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => {
          saveMessage({
            media: e.target?.result as string,
            mediaType: 'audio/webm',
            fileName: `audio_record_${Date.now()}.webm`
          });
        };
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      alert('Não foi possível acessar o microfone.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) ||
           (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => {
    if (authorId === currentUser?.id) return 'Você';
    return users.find(u => u.id === authorId)?.name || 'Usuário';
  };

  const getAuthorPhoto = (authorId: string) => {
    return users.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';
  };

  if (selectedUser) {
    const chatTitle = selectedUser === 'general' ? 'Chat Geral' : selectedUser.name;
    const chatStatus = selectedUser === 'general' ? 'Todos os usuários' : 'Estudante';
    const chatPhoto = selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo;

    return (
      <Layout title={chatTitle} showBackButton={true} backTo="/chat" actions={
        <button onClick={() => setSelectedUser(null)} className="text-white text-xs bg-white/20 px-3 py-1 rounded-full font-bold uppercase">
          Contatos
        </button>
      }>
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-4xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800 relative">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <img src={chatPhoto} className="w-10 h-10 rounded-full object-cover" alt="" />
            <div>
              <h3 className="font-bold text-gray-800 dark:text-gray-100 leading-tight">{chatTitle}</h3>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{chatStatus}</p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40">
                <i className="fas fa-comments text-6xl mb-4 text-gray-200"></i>
                <p className="font-bold uppercase tracking-widest text-xs">Nenhuma mensagem ainda</p>
              </div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[85%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && (
                        <img src={getAuthorPhoto(msg.authorId)} className="w-8 h-8 rounded-full flex-shrink-0 mt-1" alt="" />
                      )}
                      <div className="flex flex-col">
                        {selectedUser === 'general' && !isMine && (
                          <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>
                        )}
                        <div className={`p-3 rounded-3xl text-sm shadow-sm relative group ${
                          isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-gray-100 dark:bg-gray-800 dark:text-gray-200 rounded-tl-none'
                        }`}>
                          {msg.text && <p className="mb-2 leading-relaxed">{msg.text}</p>}

                          {msg.media && (
                            <div className="mt-1 space-y-2">
                              {msg.mediaType?.startsWith('image/') ? (
                                <img src={msg.media} className="max-w-full rounded-2xl shadow-sm" alt="Chat attachment" />
                              ) : msg.mediaType?.startsWith('video/') ? (
                                <video src={msg.media} controls className="max-w-full rounded-2xl shadow-sm" />
                              ) : msg.mediaType?.startsWith('audio/') ? (
                                <audio src={msg.media} controls className="max-w-full h-10" />
                              ) : null}

                              <button 
                                onClick={() => downloadMedia(msg.media!, msg.fileName || 'attachment')}
                                className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-colors ${
                                  isMine ? 'bg-white/20 hover:bg-white/30 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'
                                }`}
                              >
                                <i className="fas fa-download"></i> Baixar
                              </button>
                            </div>
                          )}

                          <p className={`text-[10px] mt-1 text-right font-bold opacity-60`}>
                            {new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Media Menu */}
          {showMediaMenu && (
            <div className="absolute bottom-20 left-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-2xl border border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-3 animate-slideUp">
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-colors">
                <i className="fas fa-image text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Imagem</span>
                <input type="file" accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, 'image')} />
              </label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-colors">
                <i className="fas fa-video text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Vídeo</span>
                <input type="file" accept="video/*" className="hidden" onChange={(e) => handleFileUpload(e, 'video')} />
              </label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-colors">
                <i className="fas fa-file-audio text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Áudio</span>
                <input type="file" accept="audio/*" className="hidden" onChange={(e) => handleFileUpload(e, 'audio')} />
              </label>
              <button 
                onClick={startRecording}
                className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl hover:bg-red-500 hover:text-white transition-colors"
              >
                <i className="fas fa-microphone text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Gravar</span>
              </button>
            </div>
          )}

          <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-t border-gray-100 dark:border-gray-800">
            {isRecording ? (
              <div className="flex items-center justify-between gap-4 bg-red-50 dark:bg-red-900/20 p-3 rounded-3xl animate-pulse">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 bg-red-500 rounded-full animate-ping"></div>
                  <span className="text-sm font-bold text-red-600 dark:text-red-400">Gravando: {formatTime(recordingTime)}</span>
                </div>
                <button 
                  onClick={stopRecording}
                  className="bg-red-500 text-white px-6 py-2 rounded-full font-black uppercase text-xs tracking-widest shadow-lg"
                >
                  Parar e Enviar
                </button>
              </div>
            ) : (
              <div className="flex gap-2">
                <button 
                  onClick={() => setShowMediaMenu(!showMediaMenu)}
                  className={`w-12 h-12 flex items-center justify-center rounded-full transition-all shadow-md ${showMediaMenu ? 'bg-ev-brown text-white rotate-45' : 'bg-gray-200 text-gray-500 hover:bg-ev-blue hover:text-white'}`}
                >
                  <i className="fas fa-plus"></i>
                </button>
                <input
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Digite uma mensagem..."
                  className="flex-1 bg-white dark:bg-gray-800 border-none rounded-full px-5 py-3 text-sm focus:ring-2 focus:ring-ev-blue shadow-inner dark:text-white"
                />
                <button 
                  onClick={handleSend}
                  disabled={!inputText.trim()}
                  className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-all ${
                    !inputText.trim() ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-ev-blue text-white hover:bg-blue-600'
                  }`}
                >
                  <i className="fas fa-paper-plane"></i>
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout title="Chat" backTo="/">
      <div className="space-y-4">
        <div 
          onClick={() => setSelectedUser('general')}
          className="flex items-center gap-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all hover:scale-[1.02] animate-fadeIn"
        >
          <div className="w-14 h-14 bg-ev-blue rounded-full flex items-center justify-center text-white shadow-inner">
            <i className="fas fa-users text-2xl"></i>
          </div>
          <div className="flex-1">
            <h3 className="font-black dark:text-white uppercase tracking-tight">Chat Geral</h3>
            <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-0.5">Mande um alô para todo mundo</p>
          </div>
        </div>

        <div className="mt-10 mb-4 ml-4">
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Meus Contatos</h4>
        </div>

        {users.filter(u => u.id !== currentUser?.id).length === 0 ? (
          <div className="text-center py-20 opacity-30">
            <i className="fas fa-user-friends text-5xl mb-4"></i>
            <p className="font-bold uppercase tracking-widest text-xs">Nenhum outro usuário ainda</p>
          </div>
        ) : (
          <div className="space-y-3">
            {users.filter(u => u.id !== currentUser?.id).map((user, idx) => (
              <div 
                key={user.id}
                onClick={() => setSelectedUser(user)}
                className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-all hover:scale-[1.01] animate-fadeIn"
                style={{ animationDelay: `${idx * 0.05}s` }}
              >
                <img src={user.photo} className="w-14 h-14 rounded-full object-cover border-4 border-ev-blue/10 shadow-sm" alt="" />
                <div className="flex-1">
                  <h3 className="font-black dark:text-white uppercase tracking-tight leading-tight">{user.name}</h3>
                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-0.5">Estudante de Educação Visual</p>
                </div>
                <div className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-700 flex items-center justify-center text-gray-300">
                  <i className="fas fa-chevron-right text-xs"></i>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default Chat;

import React, { useState, useEffect, useContext } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';
import { storage } from '../services/storage';
import { Publication, Language } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const ACCESS_KEY = '000000';

const Communities: React.FC = () => {
  const { tab } = useParams<{ tab: string }>();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<string>(tab || 'geral');
  const [publications, setPublications] = useState<Publication[]>([]);
  const [isAuth, setIsAuth] = useState(false);
  const [accessKeyInput, setAccessKeyInput] = useState('');
  const [loginError, setLoginError] = useState('');
  const [form, setForm] = useState({ title: '', category: 'geral', content: '' });
  const [successMsg, setSuccessMsg] = useState('');
  const { language } = useContext(LanguageContext);

  useEffect(() => {
    setPublications(storage.getPublications());
  }, []);

  useEffect(() => {
    if (tab && tab !== activeTab) {
      setActiveTab(tab);
    }
  }, [tab]);

  const handleTabChange = (tabId: string) => {
    setActiveTab(tabId);
    navigate(`/communities/${tabId}`, { replace: true });
  };

  const handleLogin = () => {
    if (accessKeyInput === ACCESS_KEY) {
      setIsAuth(true);
      setLoginError('');
    } else {
      setLoginError(language === Language.PT ? 'Chave de acesso incorreta!' : language === Language.EN ? 'Incorrect access key!' : 'Clé d\'accès incorrecte!');
    }
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    const newPub: Publication = {
      id: Date.now(),
      title: form.title,
      category: form.category,
      content: form.content,
      date: new Date().toISOString()
    };

    const updated = [newPub, ...publications];
    setPublications(updated);
    storage.setPublications(updated);
    setForm({ title: '', category: 'geral', content: '' });
    setSuccessMsg(language === Language.PT ? 'Informação publicada com sucesso!' : 'Information published successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const tabs = [
    { id: 'geral', label: 'Geral', icon: 'fa-info-circle' },
    { id: 'ano1', label: '1º Ano', icon: 'fa-user-graduate' },
    { id: 'ano2', label: '2º Ano', icon: 'fa-user-graduate' },
    { id: 'ano3', label: '3º Ano', icon: 'fa-user-graduate' },
    { id: 'ano4', label: '4º Ano', icon: 'fa-user-graduate' },
    { id: 'publicar', label: t('publish', language), icon: 'fa-plus-circle' },
  ];

  const filtered = publications.filter(pub => {
    if (activeTab === 'geral') return pub.category === 'geral';
    if (activeTab === 'publicar') return false;
    return pub.category === activeTab || pub.category === 'geral';
  });

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-ev-dark">
      <header className="bg-ev-blue text-white px-4 py-3 flex items-center justify-between shadow-md z-50">
        <div className="flex items-center gap-4">
          <Link to="/" className="hover:scale-110 transition-transform">
            <i className="fas fa-arrow-left text-xl"></i>
          </Link>
          <h1 className="text-xl font-bold tracking-tight">{t('communities', language)}</h1>
        </div>
      </header>

      <div className="bg-ev-blue shadow-lg border-t border-white/10 z-40 sticky top-[52px]">
        <div className="max-w-6xl mx-auto flex overflow-x-auto no-scrollbar">
          {tabs.map(tabItem => (
            <button
              key={tabItem.id}
              onClick={() => handleTabChange(tabItem.id)}
              className={`flex-shrink-0 flex flex-col items-center justify-center py-4 px-8 transition-all min-w-[100px] border-b-4 ${
                activeTab === tabItem.id ? 'bg-ev-brown border-white text-white' : 'text-white/60 border-transparent hover:bg-white/10'
              }`}
            >
              <i className={`fas ${tabItem.icon} mb-1 text-sm`}></i>
              <span className="text-[10px] font-black uppercase tracking-widest">{tabItem.label}</span>
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-4xl mx-auto w-full p-6 flex-1 py-10">
        <div className="space-y-6">
          {activeTab === 'publicar' ? (
            <div className="bg-white dark:bg-gray-800 p-10 rounded-4xl shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <h2 className="text-3xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8">{t('publish', language)}</h2>

              {!isAuth ? (
                <div className="max-w-sm mx-auto space-y-6 text-center py-10">
                  <div className="w-20 h-20 bg-ev-blue/10 rounded-full flex items-center justify-center text-ev-blue mx-auto mb-4">
                    <i className="fas fa-lock text-3xl"></i>
                  </div>
                  <p className="text-gray-500 text-sm">Apenas delegados e docentes podem publicar informações nestes canais.</p>
                  {loginError && <p className="text-red-500 text-xs font-bold bg-red-50 p-3 rounded-2xl">{loginError}</p>}
                  <input
                    type="password"
                    placeholder="000000"
                    className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-center text-lg font-bold tracking-widest shadow-inner focus:ring-2 focus:ring-ev-blue"
                    value={accessKeyInput}
                    onChange={(e) => setAccessKeyInput(e.target.value)}
                  />
                  <button 
                    onClick={handleLogin}
                    className="w-full bg-ev-blue text-white py-4 rounded-3xl font-bold shadow-lg hover:bg-blue-600 transition-all uppercase tracking-widest"
                  >
                    Verificar Chave
                  </button>
                </div>
              ) : (
                <form onSubmit={handlePublish} className="space-y-6">
                  {successMsg && <div className="bg-green-100 text-green-700 p-4 rounded-3xl font-bold text-center animate-bounce">{successMsg}</div>}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-2">Título</label>
                      <input
                        type="text"
                        required
                        className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue"
                        value={form.title}
                        onChange={(e) => setForm({ ...form, title: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-2">Destinatários</label>
                      <select
                        className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue appearance-none cursor-pointer"
                        value={form.category}
                        onChange={(e) => setForm({ ...form, category: e.target.value })}
                      >
                        <option value="geral">Todos os Anos</option>
                        <option value="ano1">Estudantes 1º Ano</option>
                        <option value="ano2">Estudantes 2º Ano</option>
                        <option value="ano3">Estudantes 3º Ano</option>
                        <option value="ano4">Estudantes 4º Ano</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-2">Descrição</label>
                    <textarea
                      required
                      rows={6}
                      className="w-full p-5 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none"
                      value={form.content}
                      onChange={(e) => setForm({ ...form, content: e.target.value })}
                    ></textarea>
                  </div>
                  <div className="flex gap-4">
                    <button type="submit" className="flex-1 bg-ev-blue text-white py-4 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-widest">
                      Emitir Agora
                    </button>
                    <button 
                      type="button"
                      onClick={() => setIsAuth(false)}
                      className="px-6 bg-gray-100 dark:bg-gray-700 text-gray-400 rounded-3xl hover:text-red-500 transition-colors"
                    >
                      Sair
                    </button>
                  </div>
                </form>
              )}
            </div>
          ) : (
            <div className="space-y-6">
              {filtered.length === 0 ? (
                <div className="bg-white dark:bg-gray-800 p-20 rounded-5xl shadow-sm text-center text-gray-300 border border-dashed border-gray-200 dark:border-gray-700 animate-fadeIn">
                  <i className="fas fa-bullhorn text-6xl mb-6 opacity-20"></i>
                  <p className="text-xl font-bold uppercase tracking-widest">Sem comunicados recentes</p>
                  <p className="text-sm mt-2">Esta comunidade está silenciosa por agora.</p>
                </div>
              ) : (
                filtered.map((pub, idx) => (
                  <div key={pub.id} className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-sm border-l-[6px] border-ev-blue hover:shadow-lg transition-all border-gray-100 dark:border-gray-700 animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                    <div className="flex justify-between items-start mb-4">
                      <h3 className="text-xl font-black text-gray-800 dark:text-white leading-tight uppercase tracking-tight">{pub.title}</h3>
                      <span className="text-[10px] font-bold text-gray-400 bg-gray-50 dark:bg-gray-700 px-3 py-1.5 rounded-full uppercase tracking-widest">
                        {new Date(pub.date).toLocaleDateString()}
                      </span>
                    </div>
                    <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-sm whitespace-pre-wrap">{pub.content}</p>
                    <div className="mt-6 flex items-center gap-2">
                      <div className="w-6 h-6 bg-ev-blue/10 rounded-full flex items-center justify-center text-[10px] text-ev-blue">
                        <i className="fas fa-tag"></i>
                      </div>
                      <span className="text-[10px] font-black text-ev-blue dark:text-ev-text-light uppercase tracking-[0.2em]">
                        {pub.category === 'geral' ? 'Informação Geral' : `Canal: ${pub.category.charAt(3)}º Ano`}
                      </span>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Communities;

import React, { useState, useEffect } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { Artwork, User } from '../types';

const ArtGallery: React.FC = () => {
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [artworks, setArtworks] = useState<Artwork[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [description, setDescription] = useState('');
  const [mediaFile, setMediaFile] = useState<File | null>(null);

  useEffect(() => {
    setArtworks(storage.getArtworks());
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;
    if (!mediaFile) {
      alert('Selecione uma imagem ou vídeo');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const isImage = mediaFile.type.startsWith('image');
      const newArt: Artwork = {
        userId: currentUser.id,
        userName: currentUser.name,
        userPhoto: currentUser.photo,
        description: description,
        media: event.target?.result as string,
        mediaType: mediaFile.type,
        isImage: isImage,
        likes: 0,
        likedBy: [],
        comments: [],
        timestamp: new Date().toISOString()
      };

      const updated = [newArt, ...artworks];
      setArtworks(updated);
      storage.setArtworks(updated);
      setDescription('');
      setMediaFile(null);
      setView('feed');
    };
    reader.readAsDataURL(mediaFile);
  };

  const handleLike = (index: number) => {
    if (!currentUser) {
      alert('Faça login para curtir');
      return;
    }
    const updated = [...artworks];
    const art = updated[index];
    if (art.likedBy.includes(currentUser.id)) return;

    art.likes += 1;
    art.likedBy.push(currentUser.id);
    setArtworks(updated);
    storage.setArtworks(updated);
  };

  const addComment = (index: number, comment: string) => {
    if (!comment.trim()) return;
    const updated = [...artworks];
    updated[index].comments.push(`${currentUser?.name || 'Visitante'}: ${comment}`);
    setArtworks(updated);
    storage.setArtworks(updated);
  };

  return (
    <Layout title="Galeria de Arte" backTo="/" actions={
      <button 
        onClick={() => setView(view === 'feed' ? 'publish' : 'feed')}
        className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm"
      >
        {view === 'feed' ? 'Publicar' : 'Ver Feed'}
      </button>
    }>
      <div className="space-y-6">
        {view === 'publish' ? (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-lg border border-gray-100 dark:border-gray-700 max-w-lg mx-auto animate-fadeIn">
            <h2 className="text-xl font-black mb-6 text-ev-blue dark:text-white uppercase tracking-tighter">Compartilhe sua Arte</h2>
            {!currentUser ? (
              <div className="text-center p-6 bg-orange-50 dark:bg-orange-900/20 rounded-3xl">
                <i className="fas fa-lock text-3xl text-ev-brown mb-2"></i>
                <p className="text-sm text-gray-700 dark:text-gray-300">Você precisa estar logado para publicar conteúdo.</p>
                <a href="#/login" className="inline-block mt-4 bg-ev-blue text-white px-6 py-2 rounded-2xl text-sm font-bold">Login</a>
              </div>
            ) : (
              <form onSubmit={handlePublish} className="space-y-4">
                <textarea
                  placeholder="Descrição da obra..."
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none"
                  rows={4}
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
                <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-3xl p-8 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                  <input
                    type="file"
                    accept="image/*,video/*"
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    onChange={(e) => setMediaFile(e.target.files?.[0] || null)}
                  />
                  <div className="text-gray-400">
                    <i className="fas fa-cloud-upload-alt text-4xl mb-2 group-hover:scale-110 transition-transform"></i>
                    <p className="text-xs font-bold uppercase tracking-widest">{mediaFile ? mediaFile.name : 'Selecione uma Imagem ou Vídeo'}</p>
                  </div>
                </div>
                <button type="submit" className="w-full bg-ev-blue text-white py-4 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-widest">
                  Publicar Obra
                </button>
              </form>
            )}
          </div>
        ) : (
          <div className="space-y-10">
            {artworks.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-12 rounded-4xl shadow-sm text-center text-gray-400 animate-fadeIn">
                <i className="fas fa-palette text-5xl mb-4 opacity-20"></i>
                <p className="text-lg font-bold uppercase tracking-widest">Nenhuma obra publicada ainda.</p>
                <button onClick={() => setView('publish')} className="mt-4 text-ev-blue font-bold underline">Seja o primeiro!</button>
              </div>
            ) : (
              artworks.map((art, idx) => (
                <div key={idx} className="bg-white dark:bg-gray-800 rounded-4xl overflow-hidden shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                  <div className="p-5 flex items-center gap-3">
                    <img src={art.userPhoto} className="w-10 h-10 rounded-full object-cover ring-2 ring-ev-blue/10" alt="" />
                    <div>
                      <h4 className="font-bold text-gray-800 dark:text-gray-100 leading-tight">{art.userName}</h4>
                      <p className="text-[10px] text-gray-400 uppercase tracking-widest">{new Date(art.timestamp).toLocaleDateString()}</p>
                    </div>
                  </div>

                  <div className="px-5 pb-4">
                    <p className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed">{art.description}</p>
                  </div>

                  <div className="bg-black/5 dark:bg-black/20 aspect-video flex items-center justify-center">
                    {art.isImage ? (
                      <img src={art.media} className="w-full h-full object-contain" alt="" />
                    ) : (
                      <video controls src={art.media} className="w-full h-full" />
                    )}
                  </div>

                  <div className="p-5 border-t border-gray-50 dark:border-gray-700">
                    <div className="flex items-center gap-6 mb-4">
                      <button 
                        onClick={() => handleLike(idx)}
                        disabled={currentUser ? art.likedBy.includes(currentUser.id) : false}
                        className={`flex items-center gap-2 transition-all ${
                          currentUser && art.likedBy.includes(currentUser.id) ? 'text-red-500' : 'text-gray-400 hover:text-red-500'
                        }`}
                      >
                        <i className={`${currentUser && art.likedBy.includes(currentUser.id) ? 'fas' : 'far'} fa-heart text-xl`}></i>
                        <span className="text-xs font-black">{art.likes} Adoros</span>
                      </button>
                      <button className="flex items-center gap-2 text-gray-400 hover:text-ev-blue transition-all">
                        <i className="far fa-comment text-xl"></i>
                        <span className="text-xs font-black">{art.comments.length} Comentários</span>
                      </button>
                    </div>

                    <div className="space-y-2 mb-4">
                      {art.comments.slice(-3).map((comment, cidx) => (
                        <p key={cidx} className="text-xs text-gray-600 dark:text-gray-400">
                          {comment}
                        </p>
                      ))}
                    </div>

                    {currentUser && (
                      <div className="flex gap-2">
                        <input
                          type="text"
                          placeholder="Adicionar comentário..."
                          className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-5 py-2.5 text-xs dark:text-white shadow-inner"
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              addComment(idx, (e.target as HTMLInputElement).value);
                              (e.target as HTMLInputElement).value = '';
                            }
                          }}
                        />
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default ArtGallery;

import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Theme, Language } from '../types';
import { useNavigate } from 'react-router-dom';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

interface SettingsProps {
  onLogout: () => void;
  toggleTheme: () => void;
  isDark: boolean;
}

const Settings: React.FC<SettingsProps> = ({ onLogout, toggleTheme, isDark }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<string | null>('profile');
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    photo: ''
  });
  const [successMsg, setSuccessMsg] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const navigate = useNavigate();
  const { language, setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    const currentUser = storage.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
      setFormData({
        name: currentUser.name,
        photo: currentUser.photo
      });
    }
  }, []);

  const handleLogout = () => {
    storage.logout();
    onLogout();
    navigate('/login');
  };

  const handleSaveProfile = () => {
    if (!user) return;

    const users = storage.getUsers();
    const updatedUsers = users.map(u => {
      if (u.id === user.id) {
        return {
          ...u,
          name: formData.name,
          photo: formData.photo
        };
      }
      return u;
    });

    storage.setUsers(updatedUsers);
    const updatedUser = updatedUsers.find(u => u.id === user.id) || null;
    setUser(updatedUser);
    setIsEditing(false);
    setSuccessMsg(t('success_update', language));
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData({ ...formData, photo: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const sections = [
    { id: 'profile', title: t('profile', language), icon: 'fa-user' },
    { id: 'security', title: t('security', language), icon: 'fa-lock' },
    { id: 'notifications', title: t('notifications', language), icon: 'fa-bell' },
    { id: 'prefs', title: t('preferences', language), icon: 'fa-cog' },
  ];

  if (!user) return null;

  return (
    <Layout title={t('settings', language)} backTo="/">
      <div className="space-y-6">
        {successMsg && (
          <div className="bg-green-100 text-green-700 p-4 rounded-3xl font-bold text-center animate-bounce shadow-sm">
            {successMsg}
          </div>
        )}

        <div className="bg-white dark:bg-gray-800 p-6 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4 animate-fadeIn">
          <div className="relative group">
            <img 
              src={isEditing ? formData.photo : user.photo} 
              className="w-20 h-20 rounded-full object-cover ring-4 ring-ev-blue/10 shadow-lg" 
              alt="Avatar" 
            />
            {isEditing && (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/50 rounded-full flex flex-col items-center justify-center text-white transition-opacity hover:bg-black/60"
              >
                <i className="fas fa-camera text-xl"></i>
                <span className="text-[8px] font-bold uppercase mt-1">{t('change_photo', language)}</span>
              </button>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handlePhotoChange} 
            />
          </div>
          <div>
            <h2 className="text-xl font-black text-gray-800 dark:text-white leading-tight">
              {isEditing ? formData.name || '...' : user.name}
            </h2>
            <p className="text-sm text-gray-500 font-medium">#{user.Number} • {user.anoFrequencia}º Ano</p>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 animate-fadeIn">
          {sections.map(s => (
            <button
              key={s.id}
