import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { storage } from '../services/storage';
import { User } from '../types';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    number: '',
    password: '',
    confirmPassword: '',
    photo: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const baseUrl = "https://raw.githubusercontent.com/Diua-maker/evul/main/";

  const formatStudentNumber = (value: string) => {
    const digits = value.replace(/\D/g, '');
    let formatted = digits;
    if (digits.length > 2) {
      formatted = `${digits.substring(0, 2)}.${digits.substring(2)}`;
    }
    if (digits.length > 6) {
      formatted = `${digits.substring(0, 2)}.${digits.substring(2, 6)}.${digits.substring(6, 10)}`;
    }
    return formatted.substring(0, 12);
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const formatted = formatStudentNumber(e.target.value);
    setFormData({ ...formData, number: formatted });
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData({ ...formData, photo: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const calculateYearFromNumber = (number: string): number => {
    const parts = number.split('.');
    if (parts.length < 3) return 1;
    const yearSuffix = parseInt(parts[2]);
    if (isNaN(yearSuffix)) return 1;
    const calculated = 2027 - yearSuffix;
    return Math.max(1, calculated);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const users = storage.getUsers();

    if (isRegister) {
      if (formData.password !== formData.confirmPassword) {
        setError('Senhas não coincidem');
        setLoading(false);
        return;
      }
      if (users.some(u => u.Number === formData.number)) {
        setError('Este número já está registrado');
        setLoading(false);
        return;
      }

      const autoAno = calculateYearFromNumber(formData.number);
      const newUser: User = {
        id: 'u_' + Math.random().toString(36).substr(2, 9),
        name: formData.name,
        Number: formData.number,
        password: formData.password,
        photo: formData.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=',
        anoFrequencia: autoAno
      };

      storage.setUsers([...users, newUser]);
      storage.setCurrentUserId(newUser.id);
    } else {
      const user = users.find(u => u.Number === formData.number && u.password === formData.password);
      if (!user) {
        setError('Credenciais incorretas');
        setLoading(false);
        return;
      }
      storage.setCurrentUserId(user.id);
    }

    setTimeout(() => {
      onLogin();
      navigate('/');
    }, 1000);
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-ev-dark flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-5xl shadow-2xl overflow-hidden animate-fadeIn">
        <div className="p-10 text-center bg-ev-blue relative">
          <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto mb-4 overflow-hidden shadow-xl border-4 border-white">
            <img src={`${baseUrl}up.png`} alt="EV-UL Logo" className="w-full h-full object-contain" />
          </div>
          <h1 className="text-2xl font-black text-white uppercase tracking-widest">
            {isRegister ? 'Cadastro' : 'Entrar'}
          </h1>
          <p className="text-white/70 text-xs mt-1 font-bold uppercase tracking-widest">Plataforma EV-UL</p>
        </div>

        <div className="p-10">
          <form onSubmit={handleSubmit} className="space-y-5">
            {error && (
              <div className="bg-red-50 text-red-500 p-4 rounded-3xl text-xs font-bold text-center border border-red-100">
                {error}
              </div>
            )}

            {isRegister && (
              <div className="flex flex-col items-center gap-3 mb-6">
                <div className="relative group">
                  <div className="w-24 h-24 rounded-full overflow-hidden border-4 border-gray-100 bg-gray-50 flex items-center justify-center shadow-inner">
                    {formData.photo ? (
                      <img src={formData.photo} className="w-full h-full object-cover" alt="" />
                    ) : (
                      <i className="fas fa-camera text-gray-300 text-3xl"></i>
                    )}
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoChange}
                    className="absolute inset-0 opacity-0 cursor-pointer"
                  />
                </div>
                <span className="text-[10px] text-gray-400 font-black uppercase tracking-widest">Foto de Perfil</span>
              </div>
            )}

            {isRegister && (
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Nome Completo</label>
                <input
                  type="text"
                  required
                  placeholder="Seu nome completo"
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>
            )}

            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Número de Estudante</label>
              <input
                type="text"
                required
                placeholder="00.0000.0000"
                className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                value={formData.number}
                onChange={handleNumberChange}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Senha</label>
              <input
                type="password"
                required
                placeholder="••••••••"
                className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                value={formData.password}
                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
              />
            </div>

            {isRegister && (
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Confirmar Senha</label>
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner"
                  value={formData.confirmPassword}
                  onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
                />
              </div>
            )}

            <button 
              type="submit"
              disabled={loading}
              className="w-full bg-ev-blue text-white py-4 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-widest flex items-center justify-center gap-3 mt-4"
            >
              {loading ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              ) : (
                <>
                  <i className={`fas ${isRegister ? 'fa-user-plus' : 'fa-sign-in-alt'}`}></i>
                  {isRegister ? 'Criar Conta' : 'Entrar'}
                </>
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <button 
              onClick={() => {
                setIsRegister(!isRegister);
                setError('');
              }}
              className="text-ev-blue text-sm font-black uppercase tracking-widest hover:underline"
            >
              {isRegister ? 'Já tem uma conta? Entre aqui' : 'Não tem conta? Cadastre-se'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

