import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    // Simulate online/offline status for other users
    const allUsers = storage.getUsers().map(u => ({
      ...u,
      isOnline: u.id === currentUser?.id ? true : Math.random() > 0.4,
      lastSeen: u.id === currentUser?.id ? 'Agora' : 'Há ' + Math.floor(Math.random() * 59) + ' min'
    }));
    setUsers(allUsers);
    setMessages(storage.getMessages());
  }, [currentUser?.id]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  // Handle Hardware Back Button
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (selectedUser) {
        // If chat is open, prevent default navigation and close it
        setSelectedUser(null);
        // We push state again so the next back actually navigates away
        window.history.pushState(null, '', window.location.href);
      }
    };

    if (selectedUser) {
      window.history.pushState(null, '', window.location.href);
      window.addEventListener('popstate', handlePopState);
    }

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;

    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else {
      processFile(file);
    }
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({
        media: event.target?.result as string,
        mediaType: file.type,
        fileName: file.name
      });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => {
          saveMessage({
            media: e.target?.result as string,
            mediaType: 'audio/webm',
            fileName: `audio_record_${Date.now()}.webm`
          });
        };
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      alert('Não foi possível acessar o microfone.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) ||
           (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => {
    if (authorId === currentUser?.id) return 'Você';
    return users.find(u => u.id === authorId)?.name || 'Usuário';
  };

  const getAuthorPhoto = (authorId: string) => {
    return users.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';
  };

  const handleBackAction = () => {
    if (selectedUser) {
      setSelectedUser(null);
    } else {
      navigate('/');
    }
  };

  if (selectedUser) {
    const chatTitle = selectedUser === 'general' ? 'Chat Geral' : selectedUser.name;
    const isOnline = selectedUser === 'general' ? true : selectedUser.isOnline;
    const chatStatus = selectedUser === 'general' ? 'Online' : (isOnline ? 'Online' : 'Visto ' + selectedUser.lastSeen);
    const chatPhoto = selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo;

    return (
      <Layout 
        title={chatTitle} 
        showBackButton={true} 
        backTo={undefined} 
        actions={
          <button onClick={() => setSelectedUser(null)} className="text-white text-xs bg-white/20 px-3 py-1 rounded-full font-bold uppercase">
            Contatos
          </button>
        }
      >
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-4xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800 relative">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <button onClick={handleBackAction} className="md:hidden mr-2 text-gray-400">
               <i className="fas fa-chevron-left"></i>
            </button>
            <div className="relative">
              <img src={chatPhoto} className="w-10 h-10 rounded-full object-cover" alt="" />
              {isOnline && (
                <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full"></div>
              )}
            </div>
            <div>
              <h3 className="font-bold text-gray-800 dark:text-gray-100 leading-tight">{chatTitle}</h3>
              <p className={`text-[10px] font-bold uppercase tracking-widest ${isOnline ? 'text-green-500' : 'text-gray-500'}`}>
                {chatStatus}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40">
                <i className="fas fa-comments text-6xl mb-4 text-gray-200"></i>
                <p className="font-bold uppercase tracking-widest text-xs">Nenhuma mensagem ainda</p>
              </div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[85%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && (
                        <img src={getAuthorPhoto(msg.authorId)} className="w-8 h-8 rounded-full flex-shrink-0 mt-1" alt="" />
                      )}
                      <div className="flex flex-col">
                        {selectedUser === 'general' && !isMine && (
                          <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>
                        )}
                        <div className={`p-3 rounded-3xl text-sm shadow-sm relative group ${
                          isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-gray-100 dark:bg-gray-800 dark:text-gray-200 rounded-tl-none'
                        }`}>
                          {msg.text && <p className="mb-2 leading-relaxed">{msg.text}</p>}

                          {msg.media && (
                            <div className="mt-1 space-y-2">
                              {msg.mediaType?.startsWith('image/') ? (
                                <img src={msg.media} className="max-w-full rounded-2xl shadow-sm" alt="Chat attachment" />
                              ) : msg.mediaType?.startsWith('video/') ? (
                                <video src={msg.media} controls className="max-w-full rounded-2xl shadow-sm" />
                              ) : msg.mediaType?.startsWith('audio/') ? (
                                <audio src={msg.media} controls className="max-w-full h-10" />
                              ) : null}

                              <button 
                                onClick={() => downloadMedia(msg.media!, msg.fileName || 'attachment')}
                                className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-colors ${
                                  isMine ? 'bg-white/20 hover:bg-white/30 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'
                                }`}
                              >
                                <i className="fas fa-download"></i> Baixar
                              </button>
                            </div>
                          )}

                          <p className={`text-[10px] mt-1 text-right font-bold opacity-60`}>
                            {new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Media Menu */}
          {showMediaMenu && (
            <div className="absolute bottom-20 left-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-2xl border border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-3 animate-slideUp">
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-colors">
                <i className="fas fa-image text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Imagem</span>
                <input type="file" accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, 'image')} />
              </label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-colors">
                <i className="fas fa-video text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Vídeo</span>
                <input type="file" accept="video/*" className="hidden" onChange={(e) => handleFileUpload(e, 'video')} />
              </label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-colors">
                <i className="fas fa-file-audio text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Áudio</span>
                <input type="file" accept="audio/*" className="hidden" onChange={(e) => handleFileUpload(e, 'audio')} />
              </label>
              <button 
                onClick={startRecording}
                className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl hover:bg-red-500 hover:text-white transition-colors"
              >
                <i className="fas fa-microphone text-xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Gravar</span>
              </button>
            </div>
          )}

          <div className="p-4 bg-gray-50 dark:bg-gray-800/50 border-t border-gray-100 dark:border-gray-800">
            {isRecording ? (
              <div className="flex items-center justify-between gap-4 bg-red-50 dark:bg-red-900/20 p-3 rounded-3xl animate-pulse">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 bg-red-500 rounded-full animate-ping"></div>
                  <span className="text-sm font-bold text-red-600 dark:text-red-400">Gravando: {formatTime(recordingTime)}</span>
                </div>
                <button 
                  onClick={stopRecording}
                  className="bg-red-500 text-white px-6 py-2 rounded-full font-black uppercase text-xs tracking-widest shadow-lg"
                >
                  Parar e Enviar
                </button>
              </div>
            ) : (
              <div className="flex gap-2">
                <button 
                  onClick={() => setShowMediaMenu(!showMediaMenu)}
                  className={`w-12 h-12 flex items-center justify-center rounded-full transition-all shadow-md ${showMediaMenu ? 'bg-ev-brown text-white rotate-45' : 'bg-gray-200 text-gray-500 hover:bg-ev-blue hover:text-white'}`}
                >
                  <i className="fas fa-plus"></i>
                </button>
                <input
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Digite uma mensagem..."
                  className="flex-1 bg-white dark:bg-gray-800 border-none rounded-full px-5 py-3 text-sm focus:ring-2 focus:ring-ev-blue shadow-inner dark:text-white"
                />
                <button 
                  onClick={handleSend}
                  disabled={!inputText.trim()}
                  className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-all ${
                    !inputText.trim() ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-ev-blue text-white hover:bg-blue-600'
                  }`}
                >
                  <i className="fas fa-paper-plane"></i>
                </button>
              </div>
            )}
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Chat" backTo="/" showBackButton={true}>
      <div className="space-y-4">
        <div 
          onClick={() => setSelectedUser('general')}
          className="flex items-center gap-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all hover:scale-[1.02] animate-fadeIn"
        >
          <div className="relative">
            <div className="w-14 h-14 bg-ev-blue rounded-full flex items-center justify-center text-white shadow-inner">
              <i className="fas fa-users text-2xl"></i>
            </div>
            <div className="absolute bottom-0 right-0 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full"></div>
          </div>
          <div className="flex-1">
            <h3 className="font-black dark:text-white uppercase tracking-tight">Chat Geral</h3>
            <p className="text-[10px] text-green-500 font-bold uppercase tracking-widest mt-0.5">Online Agora</p>
          </div>
        </div>

        <div className="mt-10 mb-4 ml-4">
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Meus Contatos</h4>
        </div>

        {users.filter(u => u.id !== currentUser?.id).length === 0 ? (
          <div className="text-center py-20 opacity-30">
            <i className="fas fa-user-friends text-5xl mb-4"></i>
            <p className="font-bold uppercase tracking-widest text-xs">Nenhum outro usuário ainda</p>
          </div>
        ) : (
          <div className="space-y-3">
            {users.filter(u => u.id !== currentUser?.id).map((user, idx) => (
              <div 
                key={user.id}
                onClick={() => setSelectedUser(user)}
                className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-all hover:scale-[1.01] animate-fadeIn"
                style={{ animationDelay: `${idx * 0.05}s` }}
              >
                <div className="relative">
                  <img src={user.photo} className="w-14 h-14 rounded-full object-cover border-4 border-ev-blue/10 shadow-sm" alt="" />
                  {user.isOnline && (
                    <div className="absolute bottom-0 right-0 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full"></div>
                  )}
                </div>
                <div className="flex-1">
                  <h3 className="font-black dark:text-white uppercase tracking-tight leading-tight">{user.name}</h3>
                  <p className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${user.isOnline ? 'text-green-500' : 'text-gray-400'}`}>
                    {user.isOnline ? 'Online' : 'Visto ' + user.lastSeen}
                  </p>
                </div>
                <div className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-700 flex items-center justify-center text-gray-300">
                  <i className="fas fa-chevron-right text-xs"></i>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default Chat;

import React, { useState, useEffect, useCallback, createContext } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Home from './views/Home';
import About from './views/About';
import Chat from './views/Chat';
import Communities from './views/Communities';
import ArtGallery from './views/ArtGallery';
import UserPosts from './views/UserPosts';
import Settings from './views/Settings';
import Login from './views/Login';
import Library from './views/Library';
import { storage } from './services/storage';
import { Theme, Language } from './types';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
}

export const LanguageContext = createContext<LanguageContextType>({
  language: Language.PT,
  setLanguage: () => {},
});

const AppContent: React.FC = () => {
  const [theme, setTheme] = useState<Theme>(storage.getTheme());
  const [language, setLanguageState] = useState<Language>(storage.getLanguage());
  const [isAuth, setIsAuth] = useState<boolean>(!!storage.getCurrentUserId());

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    storage.setLanguage(lang);
  };

  useEffect(() => {
    if (theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    storage.setTheme(theme);
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme(prev => (prev === Theme.LIGHT ? Theme.DARK : Theme.LIGHT));
  }, []);

  const checkAuth = useCallback(() => {
    setIsAuth(!!storage.getCurrentUserId());
  }, []);

  const requiresAuth = (component: React.ReactNode) => {
    return isAuth ? component : <Navigate to="/login" replace />;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      <div className="min-h-screen bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
        <Routes>
          <Route path="/" element={<Home toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />} />
          <Route path="/about" element={<About />} />
          <Route path="/chat" element={requiresAuth(<Chat />)} />
          <Route path="/communities" element={<Communities />} />
          <Route path="/communities/:tab" element={<Communities />} />
          <Route path="/gallery" element={<ArtGallery />} />
          <Route path="/posts" element={<UserPosts />} />
          <Route path="/library/:category" element={<Library />} />
          <Route path="/settings" element={requiresAuth(<Settings onLogout={checkAuth} toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />)} />
          <Route path="/login" element={<Login onLogin={checkAuth} />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </LanguageContext.Provider>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { UserPost, User, Language, Comment } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const UserPosts: React.FC = () => {
  const navigate = useNavigate();
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [posts, setPosts] = useState<UserPost[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [caption, setCaption] = useState('');
  const [mediaData, setMediaData] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<string>('');
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState('');
  const [activeCommentId, setActiveCommentId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');

  const { language } = useContext(LanguageContext);

  useEffect(() => {
    const storedPosts = storage.getPosts();
    const migrations = storedPosts.map(p => ({
      ...p,
      likes: p.likes || 0,
      likedBy: p.likedBy || [],
      comments: p.comments || []
    }));
    setPosts(migrations);
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');
    if (file) {
      if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
          window.URL.revokeObjectURL(video.src);
          if (video.duration > 30) {
            setError(language === Language.PT ? 'O vídeo não pode ter mais de 30 segundos.' : 'Video cannot be longer than 30 seconds.');
            setMediaData(null);
            return;
          }
          readFile(file);
        };
        video.src = URL.createObjectURL(file);
      } else {
        readFile(file);
      }
    }
  };

  const readFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setMediaData(event.target?.result as string);
      setMediaType(file.type);
    };
    reader.readAsDataURL(file);
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) {
      navigate('/login');
      return;
    }
    if (!mediaData) return;

    setIsUploading(true);
    const newPost: UserPost = {
      id: 'post_' + Date.now(),
      userId: currentUser.id,
      userName: currentUser.name,
      userPhoto: currentUser.photo,
      caption: caption,
      media: mediaData,
      mediaType: mediaType,
      isImage: mediaType.startsWith('image/'),
      timestamp: new Date().toISOString(),
      likes: 0,
      likedBy: [],
      comments: []
    };

    const updated = [newPost, ...posts];
    setPosts(updated);
    storage.setPosts(updated);

    setTimeout(() => {
      setCaption('');
      setMediaData(null);
      setIsUploading(false);
      setView('feed');
    }, 1000);
  };

  const handleLike = (postId: string) => {
    if (!currentUser) {
      alert(language === Language.PT ? 'Por favor, faça login para curtir.' : 'Please login to like.');
      navigate('/login');
      return;
    }
    const updated = posts.map(post => {
      if (post.id === postId) {
        const hasLiked = post.likedBy.includes(currentUser.id);
        const newLikedBy = hasLiked 
          ? post.likedBy.filter(id => id !== currentUser.id)
          : [...post.likedBy, currentUser.id];
        return {
          ...post,
          likedBy: newLikedBy,
          likes: newLikedBy.length
        };
      }
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
  };

  const handleAddComment = (postId: string) => {
    if (!currentUser) {
      alert(language === Language.PT ? 'Por favor, faça login para comentar.' : 'Please login to comment.');
      navigate('/login');
      return;
    }
    if (!commentText.trim()) return;
    const newComment: Comment = {
      authorName: currentUser.name,
      authorPhoto: currentUser.photo,
      text: commentText,
      timestamp: new Date().toISOString()
    };
    const updated = posts.map(post => {
      if (post.id === postId) {
        return {
          ...post,
          comments: [...(post.comments || []), newComment]
        };
      }
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
    setCommentText('');
    setActiveCommentId(null);
  };

  const handleViewToggle = () => {
    if (view === 'feed' && !currentUser) {
      navigate('/login');
    } else {
      setView(view === 'feed' ? 'publish' : 'feed');
      setError('');
    }
  };

  return (
    <Layout 
      title={t('posts', language)} 
      backTo="/" 
      actions={
        currentUser && (
          <button 
            onClick={handleViewToggle}
            className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm"
          >
            {view === 'feed' ? t('publish', language) : t('view', language)}
          </button>
        )
      }
    >
      <div className="max-w-2xl mx-auto pb-10">
        {view === 'publish' && currentUser ? (
          <div className="bg-white dark:bg-gray-800 p-10 rounded-5xl shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-10">{t('publish', language)}</h2>

            <form onSubmit={handlePublish} className="space-y-6">
              {error && (
                <div className="bg-red-50 text-red-500 p-4 rounded-3xl text-xs font-bold text-center border border-red-100">
                  <i className="fas fa-exclamation-triangle mr-2"></i> {error}
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Legenda / Descrição</label>
                <textarea
                  className="w-full p-5 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none"
                  rows={3}
                  placeholder="Diga algo sobre esta publicação..."
                  value={caption}
                  onChange={(e) => setCaption(e.target.value)}
                />
              </div>

              <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-5xl p-12 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                <input
                  type="file"
                  accept="image/*,video/*"
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  onChange={handleFileChange}
                />

                {mediaData ? (
                  <div className="space-y-4">
                    {mediaType.startsWith('image/') ? (
                      <img src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-2xl" alt="Preview" />
                    ) : (
                      <div className="relative inline-block">
                        <video src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-2xl" />
                        <div className="absolute top-4 right-4 bg-black/60 text-white text-[10px] font-black px-3 py-1.5 rounded-full uppercase tracking-widest">
                          VÍDEO (MAX 30s)
                        </div>
                      </div>
                    )}
                    <p className="text-[10px] font-black text-ev-blue uppercase tracking-widest">Clique para alterar</p>
                  </div>
                ) : (
                  <div className="text-gray-400">
                    <div className="w-20 h-20 bg-gray-100 dark:bg-gray-600 rounded-3xl flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                      <i className="fas fa-photo-video text-3xl text-ev-blue"></i>
                    </div>
                    <p className="font-black uppercase tracking-widest text-xs">Selecione Mídia</p>
                    <p className="text-[10px] mt-2 italic font-bold">Imagem ou Vídeo (máx. 30 segundos)</p>
                  </div>
                )}
              </div>

              <button 
                type="submit" 
                disabled={!mediaData || isUploading}
                className={`w-full py-5 rounded-3xl font-black shadow-xl transition-all uppercase tracking-widest flex items-center justify-center gap-3 mt-6 ${
                  !mediaData ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-ev-blue text-white hover:bg-blue-600'
                }`}
              >
                {isUploading ? (
                  <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                  <>
                    <i className="fas fa-paper-plane"></i>
                    {t('publish', language)}
                  </>
                )}
              </button>
            </form>
          </div>
        ) : (
          <div className="space-y-12">
            {posts.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-20 rounded-5xl shadow-sm text-center border border-dashed border-gray-200 dark:border-gray-700 animate-fadeIn">
                <div className="w-24 h-24 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center mx-auto mb-6">
                  <i className="fas fa-images text-4xl text-gray-200"></i>
                </div>
                <h3 className="text-xl font-black text-gray-400 uppercase tracking-widest">Feed Vazio</h3>
                <p className="text-sm text-gray-400 mt-2 italic">Seja o primeiro a partilhar um momento!</p>
                {currentUser && <button onClick={() => setView('publish')} className="mt-6 text-ev-blue font-bold underline">Publicar Agora</button>}
              </div>
            ) : (
              posts.map((post, idx) => (
                <div key={post.id} className="bg-white dark:bg-gray-800 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                  <div className="p-6 flex items-center gap-4">
                    <img src={post.userPhoto} className="w-12 h-12 rounded-full object-cover ring-2 ring-ev-blue/10 shadow-sm" alt="" />
                    <div>
                      <h4 className="font-black text-gray-800 dark:text-white leading-tight uppercase tracking-tight">{post.userName}</h4>
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                        {new Date(post.timestamp).toLocaleDateString()}
                      </p>
                    </div>
                  </div>

                  {post.caption && (
                    <div className="px-6 pb-4">
                      <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium">
                        {post.caption}
                      </p>
                    </div>
                  )}

                  <div className="bg-black/5 dark:bg-black/20 aspect-video flex items-center justify-center relative">
                    {post.isImage ? (
                      <img src={post.media} className="w-full h-full object-contain" alt="" />
                    ) : (
                      <video controls src={post.media} className="w-full h-full" />
                    )}
                  </div>

                  <div className="p-6 space-y-4">
                    <div className="flex items-center justify-between border-b border-gray-50 dark:border-gray-700 pb-5">
                       <div className="flex gap-8">
                          <button 
                            onClick={() => handleLike(post.id)}
                            className={`flex items-center gap-2.5 transition-colors ${currentUser && post.likedBy?.includes(currentUser.id) ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}
                          >
                             <i className={`${currentUser && post.likedBy?.includes(currentUser.id) ? 'fas' : 'far'} fa-heart text-2xl`}></i>
                             <span className="text-xs font-black uppercase tracking-widest">{post.likes || 0} Adoros</span>
                          </button>
                          <button 
                            onClick={() => setActiveCommentId(activeCommentId === post.id ? null : post.id)}
                            className="flex items-center gap-2.5 text-gray-400 hover:text-ev-blue transition-colors"
                          >
                             <i className="far fa-comment text-2xl"></i>
                             <span className="text-xs font-black uppercase tracking-widest">{post.comments?.length || 0} Comentários</span>
                          </button>
                       </div>
                    </div>

                    {post.comments && post.comments.length > 0 && (
                      <div className="space-y-4 pt-4 max-h-60 overflow-y-auto no-scrollbar">
                        {post.comments.map((comment, idx) => (
                          <div key={idx} className="flex gap-3 animate-fadeIn">
                            <img src={comment.authorPhoto} className="w-8 h-8 rounded-full object-cover flex-shrink-0" alt="" />
                            <div className="bg-gray-50 dark:bg-gray-700 p-3 rounded-2xl flex-1 shadow-inner">
                              <p className="text-[9px] font-black text-ev-blue uppercase tracking-widest mb-1">{comment.authorName}</p>
                              <p className="text-xs text-gray-600 dark:text-gray-200 leading-relaxed">{comment.text}</p>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                    {(activeCommentId === post.id || !post.comments?.length) && (
                      <div className="flex gap-3 pt-4">
                        <input 
                          type="text" 
                          placeholder={currentUser ? "Escreva um comentário..." : "Faça login para comentar"}
                          readOnly={!currentUser}
                          onClick={() => !currentUser && navigate('/login')}
                          className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-5 py-3 text-xs dark:text-white focus:ring-2 focus:ring-ev-blue shadow-inner"
                          value={activeCommentId === post.id ? commentText : ''}
                          onChange={(e) => {
                            if (currentUser) {
                              setActiveCommentId(post.id);
                              setCommentText(e.target.value);
                            }
                          }}
                          onKeyDown={(e) => e.key === 'Enter' && handleAddComment(post.id)}
                        />
                        <button 
                          onClick={() => handleAddComment(post.id)}
                          className="bg-ev-blue text-white w-10 h-10 rounded-full flex items-center justify-center hover:bg-blue-600 transition-all shadow-md active:scale-90"
                        >
                          <i className="fas fa-paper-plane text-xs"></i>
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default UserPosts;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  // Status estáveis gerados uma vez por sessão do componente
  const usersWithStatus = useMemo(() => {
    return storage.getUsers().map(u => ({
      ...u,
      isOnline: u.id === currentUser?.id ? true : Math.random() > 0.4,
      lastSeen: u.id === currentUser?.id ? 'Agora' : 'Há ' + Math.floor(Math.random() * 59) + ' min'
    }));
  }, [currentUser?.id]);

  useEffect(() => {
    setMessages(storage.getMessages());
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  // Lógica para o botão de voltar do hardware (celular/navegador)
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (selectedUser) {
        // Intercepta o voltar e apenas fecha o chat selecionado
        setSelectedUser(null);
        // Previne que a navegação continue para fora da página
        window.history.pushState(null, '', window.location.href);
      }
    };

    if (selectedUser) {
      // Quando um chat abre, adicionamos uma entrada no histórico para ser "voltável"
      window.history.pushState(null, '', window.location.href);
      window.addEventListener('popstate', handlePopState);
    }

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;

    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else {
      processFile(file);
    }
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({
        media: event.target?.result as string,
        mediaType: file.type,
        fileName: file.name
      });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => {
          saveMessage({
            media: e.target?.result as string,
            mediaType: 'audio/webm',
            fileName: `audio_record_${Date.now()}.webm`
          });
        };
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      alert('Não foi possível acessar o microfone.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) ||
           (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => {
    if (authorId === currentUser?.id) return 'Você';
    return usersWithStatus.find(u => u.id === authorId)?.name || 'Usuário';
  };

  const getAuthorPhoto = (authorId: string) => {
    return usersWithStatus.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';
  };

  const handleBackAction = () => {
    if (selectedUser) {
      setSelectedUser(null);
    } else {
      navigate('/');
    }
  };

  if (selectedUser) {
    const chatTitle = selectedUser === 'general' ? 'Chat Geral' : selectedUser.name;
    const isOnline = selectedUser === 'general' ? true : selectedUser.isOnline;
    const chatStatus = selectedUser === 'general' ? 'Online' : (isOnline ? 'Online' : 'Visto ' + selectedUser.lastSeen);
    const chatPhoto = selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo;

    return (
      <Layout 
        title={chatTitle} 
        showBackButton={true} 
        onBack={handleBackAction}
        actions={
          <div className="flex items-center gap-2">
            <span className={`w-2.5 h-2.5 rounded-full ${isOnline ? 'bg-green-400 animate-pulse shadow-[0_0_8px_rgba(74,222,128,0.6)]' : 'bg-gray-400'}`}></span>
            <span className="text-[10px] text-white/90 font-black uppercase tracking-widest hidden xs:inline">{chatStatus}</span>
          </div>
        }
      >
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-4xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800 relative">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <div className="relative">
              <img src={chatPhoto} className="w-10 h-10 rounded-full object-cover shadow-sm border border-gray-200 dark:border-gray-700" alt="" />
              {isOnline && (
                <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full shadow-sm"></div>
              )}
            </div>
            <div>
              <h3 className="font-black text-gray-800 dark:text-gray-100 leading-tight tracking-tight">{chatTitle}</h3>
              <p className={`text-[10px] font-black uppercase tracking-widest ${isOnline ? 'text-green-500' : 'text-gray-400'}`}>
                {chatStatus}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar bg-gray-50/30 dark:bg-gray-900/30">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40">
                <i className="fas fa-comments text-6xl mb-4 text-gray-200 dark:text-gray-700"></i>
                <p className="font-black uppercase tracking-widest text-[10px]">Inicie uma conversa</p>
              </div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[85%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && (
                        <img src={getAuthorPhoto(msg.authorId)} className="w-8 h-8 rounded-full flex-shrink-0 mt-1 shadow-sm" alt="" />
                      )}
                      <div className="flex flex-col">
                        {selectedUser === 'general' && !isMine && (
                          <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>
                        )}
                        <div className={`p-3.5 rounded-3xl text-sm shadow-sm relative group ${
                          isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-100 dark:border-gray-700'
                        }`}>
                          {msg.text && <p className="leading-relaxed font-medium">{msg.text}</p>}

                          {msg.media && (
                            <div className="mt-2 space-y-2">
                              {msg.mediaType?.startsWith('image/') ? (
                                <img src={msg.media} className="max-w-full rounded-2xl shadow-md" alt="Anexo" />
                              ) : msg.mediaType?.startsWith('video/') ? (
                                <video src={msg.media} controls className="max-w-full rounded-2xl shadow-md" />
                              ) : msg.mediaType?.startsWith('audio/') ? (
                                <audio src={msg.media} controls className="max-w-full h-10" />
                              ) : null}

                              <button 
                                onClick={() => downloadMedia(msg.media!, msg.fileName || 'anexo')}
                                className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-all shadow-sm ${
                                  isMine ? 'bg-white/20 hover:bg-white/40 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'
                                }`}
                              >
                                <i className="fas fa-download"></i> Baixar Mídia
                              </button>
                            </div>
                          )}

                          <p className={`text-[9px] mt-1.5 text-right font-black uppercase tracking-widest opacity-60`}>
                            {new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Menu de Mídia */}
          {showMediaMenu && (
            <div className="absolute bottom-20 left-4 right-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-2xl border border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-4 animate-slideUp z-50">
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm">
                <i className="fas fa-image text-2xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Galeria</span>
                <input type="file" accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, 'image')} />
              </label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm">
                <i className="fas fa-video text-2xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Vídeo 30s</span>
                <input type="file" accept="video/*" className="hidden" onChange={(e) => handleFileUpload(e, 'video')} />
              </label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm">
                <i className="fas fa-file-audio text-2xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Arquivo Áudio</span>
                <input type="file" accept="audio/*" className="hidden" onChange={(e) => handleFileUpload(e, 'audio')} />
              </label>
              <button 
                onClick={startRecording}
                className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl hover:bg-red-500 hover:text-white transition-all shadow-sm"
              >
                <i className="fas fa-microphone text-2xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Gravar Voz</span>
              </button>
            </div>
          )}

          <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-800">
            {isRecording ? (
              <div className="flex items-center justify-between gap-4 bg-red-50 dark:bg-red-900/20 p-3.5 rounded-3xl border border-red-100 dark:border-red-900/30">
                <div className="flex items-center gap-3">
                  <div className="w-3.5 h-3.5 bg-red-500 rounded-full animate-ping"></div>
                  <span className="text-xs font-black text-red-600 dark:text-red-400 uppercase tracking-widest">Gravando: {formatTime(recordingTime)}</span>
                </div>
                <button 
                  onClick={stopRecording}
                  className="bg-red-500 text-white px-6 py-2.5 rounded-full font-black uppercase text-[10px] tracking-[0.2em] shadow-lg active:scale-95 transition-transform"
                >
                  Finalizar
                </button>
              </div>
            ) : (
              <div className="flex gap-3">
                <button 
                  onClick={() => setShowMediaMenu(!showMediaMenu)}
                  className={`w-12 h-12 flex items-center justify-center rounded-full transition-all shadow-md active:scale-90 ${showMediaMenu ? 'bg-ev-brown text-white rotate-45' : 'bg-gray-100 text-gray-500 hover:bg-ev-blue hover:text-white dark:bg-gray-700'}`}
                >
                  <i className="fas fa-plus"></i>
                </button>
                <input
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Escreva sua mensagem..."
                  className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-6 py-3 text-sm focus:ring-2 focus:ring-ev-blue shadow-inner dark:text-white font-medium"
                />
                <button 
                  onClick={handleSend}
                  disabled={!inputText.trim()}
                  className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-all active:scale-90 ${
                    !inputText.trim() ? 'bg-gray-200 text-gray-400 cursor-not-allowed dark:bg-gray-800' : 'bg-ev-blue text-white hover:bg-blue-600'
                  }`}
                >
                  <i className="fas fa-paper-plane"></i>
                </button>
              </div>
            )}
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Mensagens" backTo="/" showBackButton={true}>
      <div className="space-y-4">
        <div 
          onClick={() => setSelectedUser('general')}
          className="flex items-center gap-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all hover:scale-[1.02] animate-fadeIn"
        >
          <div className="relative">
            <div className="w-14 h-14 bg-ev-blue rounded-full flex items-center justify-center text-white shadow-inner">
              <i className="fas fa-users text-2xl"></i>
            </div>
            <div className="absolute bottom-0.5 right-0.5 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full shadow-sm animate-pulse"></div>
          </div>
          <div className="flex-1">
            <h3 className="font-black dark:text-white uppercase tracking-tight">Chat Geral</h3>
            <p className="text-[10px] text-green-500 font-black uppercase tracking-[0.2em] mt-0.5">Disponível Agora</p>
          </div>
        </div>

        <div className="mt-10 mb-4 ml-4">
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Meus Contatos</h4>
        </div>

        {usersWithStatus.filter(u => u.id !== currentUser?.id).length === 0 ? (
          <div className="text-center py-20 opacity-30">
            <i className="fas fa-user-friends text-5xl mb-4"></i>
            <p className="font-black uppercase tracking-widest text-[10px]">Sem outros membros</p>
          </div>
        ) : (
          <div className="space-y-3">
            {usersWithStatus.filter(u => u.id !== currentUser?.id).map((user, idx) => (
              <div 
                key={user.id}
                onClick={() => setSelectedUser(user)}
                className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-all hover:scale-[1.01] animate-fadeIn"
                style={{ animationDelay: `${idx * 0.05}s` }}
              >
                <div className="relative">
                  <img src={user.photo} className="w-14 h-14 rounded-full object-cover border-4 border-ev-blue/10 shadow-sm" alt="" />
                  {user.isOnline && (
                    <div className="absolute bottom-0.5 right-0.5 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full shadow-sm"></div>
                  )}
                </div>
                <div className="flex-1">
                  <h3 className="font-black dark:text-white uppercase tracking-tight leading-tight">{user.name}</h3>
                  <p className={`text-[10px] font-black uppercase tracking-widest mt-0.5 ${user.isOnline ? 'text-green-500' : 'text-gray-400'}`}>
                    {user.isOnline ? 'Online agora' : 'Visto ' + user.lastSeen}
                  </p>
                </div>
                <div className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-700 flex items-center justify-center text-gray-300">
                  <i className="fas fa-chevron-right text-xs"></i>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </Layout>
  );
};

