import React, { useState, useEffect, useCallback, createContext } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Home from './views/Home';
import About from './views/About';
import Chat from './views/Chat';
import Communities from './views/Communities';
import ArtGallery from './views/ArtGallery';
import UserPosts from './views/UserPosts';
import Settings from './views/Settings';
import Login from './views/Login';
import Library from './views/Library';
import { storage } from './services/storage';
import { Theme, Language } from './types';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
}

export const LanguageContext = createContext<LanguageContextType>({
  language: Language.PT,
  setLanguage: () => {},
});

const AppContent: React.FC = () => {
  const [theme, setTheme] = useState<Theme>(storage.getTheme());
  const [language, setLanguageState] = useState<Language>(storage.getLanguage());
  const [isAuth, setIsAuth] = useState<boolean>(!!storage.getCurrentUserId());

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    storage.setLanguage(lang);
  };

  useEffect(() => {
    if (theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    storage.setTheme(theme);
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme(prev => (prev === Theme.LIGHT ? Theme.DARK : Theme.LIGHT));
  }, []);

  const checkAuth = useCallback(() => {
    setIsAuth(!!storage.getCurrentUserId());
  }, []);

  const requiresAuth = (component: React.ReactNode) => {
    return isAuth ? component : <Navigate to="/login" replace />;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      <div className="min-h-screen bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
        <Routes>
          <Route path="/" element={<Home toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />} />
          <Route path="/about" element={<About />} />
          <Route path="/chat" element={requiresAuth(<Chat />)} />
          <Route path="/communities" element={requiresAuth(<Communities />)} />
          <Route path="/communities/:tab" element={requiresAuth(<Communities />)} />
          <Route path="/gallery" element={<ArtGallery />} />
          <Route path="/posts" element={<UserPosts />} />
          <Route path="/library/:category" element={<Library />} />
          <Route path="/settings" element={requiresAuth(<Settings onLogout={checkAuth} toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />)} />
          <Route path="/login" element={<Login onLogin={checkAuth} />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </LanguageContext.Provider>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';
import { LibraryItem, Language } from '../types';
import { storage } from '../services/storage';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const githubRawData: LibraryItem[] = [
  { id: 'g1', title: 'Plano Analítico - Educação Visual 2025', author: 'Secretaria', category: 'planos', date: '2025-01-10', description: 'Plano curricular para o primeiro semestre de 2025.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/planos/plano_2025.pdf' },
  { id: 'g2', title: 'Horário Semestral - Todos os Anos', author: 'Registo Académico', category: 'horarios', date: '2025-01-15', description: 'Horário completo das aulas teóricas e práticas.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/horarios/horario_geral.pdf' },
  { id: 'g3', title: 'A Teoria das Cores - Johannes Itten', author: 'Johannes Itten', category: 'livros', date: '2024-05-20', description: 'Livro fundamental para o estudo da cor e composição.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/livros/teoria_das_cores.pdf' },
  { id: 'g4', title: 'História da Arte Moçambicana', author: 'Vasco de Castro', category: 'livros', date: '2023-11-12', description: 'Compilação histórica sobre a evolução das artes em Moçambique.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/livros/historia_arte_moz.pdf' },
];

const Library: React.FC = () => {
  const { category } = useParams<{ category: string }>();
  const { language } = useContext(LanguageContext);
  const navigate = useNavigate();
  const [items, setItems] = useState<LibraryItem[]>([]);
  const [view, setView] = useState<'list' | 'add'>('list');
  const [searchTerm, setSearchTerm] = useState('');
  const [form, setForm] = useState({ title: '', author: '', description: '', file: '' });
  const [isUploading, setIsUploading] = useState(false);

  const currentUser = storage.getCurrentUserId();
  const categoryAllowsAdd = category === 'trabalhos' || category === 'materiais' || category === 'mono';

  useEffect(() => {
    const stored = storage.getLibraryItems();
    const combined = [...githubRawData, ...stored];
    setItems(combined.filter(item => item.category === category));
  }, [category]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setForm({ ...form, file: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleToggleView = () => {
    if (view === 'list') {
      if (!currentUser) {
        navigate('/login');
        return;
      }
      setView('add');
    } else {
      setView('list');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.file) {
      alert(t('select_file', language));
      return;
    }

    setIsUploading(true);
    const newItem: LibraryItem = {
      id: 'l_' + Date.now(),
      title: form.title,
      author: form.author,
      category: category as any,
      date: new Date().toISOString().split('T')[0],
      description: form.description,
      downloadUrl: form.file
    };

    const stored = storage.getLibraryItems();
    const updated = [newItem, ...stored];
    storage.setLibraryItems(updated);

    setTimeout(() => {
      setItems(updated.filter(item => item.category === category));
      setForm({ title: '', author: '', description: '', file: '' });
      setIsUploading(false);
      setView('list');
    }, 1500);
  };

  const getTitle = () => {
    switch (category) {
      case 'trabalhos': return t('scientific_works', language);
      case 'mono': return t('monographs', language);
      case 'planos': return t('analytical_plans', language);
      case 'horarios': return t('schedules', language);
      case 'livros': return t('books', language);
      case 'materiais': return t('academic_materials', language);
      default: return t('library', language);
    }
  };

  const filteredItems = items.filter(item => 
    item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.author.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-ev-dark">
      <header className="bg-ev-blue text-white px-4 py-3 flex items-center justify-between shadow-md z-50">
        <div className="flex items-center gap-4">
          <Link to="/" className="hover:scale-110 transition-transform">
            <i className="fas fa-arrow-left text-xl"></i>
          </Link>
          <h1 className="text-xl font-bold tracking-tight">{getTitle()}</h1>
        </div>
        {categoryAllowsAdd && currentUser && (
          <button 
            onClick={handleToggleView}
            className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm hover:scale-105 transition-transform"
          >
            {view === 'list' ? t('add_file', language) : t('cancel', language)}
          </button>
        )}
      </header>

      <main className="max-w-6xl mx-auto w-full p-6 flex-1">
        {view === 'add' ? (
          <div className="max-w-2xl mx-auto bg-white dark:bg-gray-800 p-10 rounded-5xl shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8">{t('add_file', language)}</h2>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">{t('file_title', language)}</label>
                <input
                  type="text"
                  required
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue"
                  value={form.title}
                  onChange={(e) => setForm({ ...form, title: e.target.value })}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">{t('author_name', language)}</label>
                <input
                  type="text"
                  required
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue"
                  value={form.author}
                  onChange={(e) => setForm({ ...form, author: e.target.value })}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">{t('file_description', language)}</label>
                <textarea
                  required
                  rows={4}
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none"
                  value={form.description}
                  onChange={(e) => setForm({ ...form, description: e.target.value })}
                />
              </div>
              <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-4xl p-10 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                <input
                  type="file"
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  onChange={handleFileUpload}
                />
                <div className="text-gray-400">
                  <i className="fas fa-file-upload text-5xl mb-3 group-hover:scale-110 transition-transform"></i>
                  <p className="text-xs font-bold uppercase tracking-widest">{form.file ? 'Ficheiro Selecionado' : t('select_file', language)}</p>
                </div>
              </div>
              <button 
                type="submit" 
                disabled={isUploading}
                className="w-full bg-ev-blue text-white py-4 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-widest flex items-center justify-center gap-3"
              >
                {isUploading ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : t('upload', language)}
              </button>
            </form>
          </div>
        ) : (
          <>
            <div className="mb-10 bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 flex flex-col md:flex-row md:items-center justify-between gap-6 animate-fadeIn">
              <div>
                <h2 className="text-3xl font-black text-ev-blue dark:text-white uppercase tracking-tighter">{t('library', language)}</h2>
                <p className="text-sm font-bold text-gray-400 uppercase tracking-widest">Repositório Digital - {getTitle()}</p>
              </div>
              <div className="relative">
                <input 
                  type="text" 
                  placeholder={t('search', language)} 
                  className="w-full md:w-80 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-6 py-4 text-sm focus:ring-2 focus:ring-ev-blue transition-all dark:text-white shadow-inner"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
                <i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-gray-300"></i>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {filteredItems.length > 0 ? (
                filteredItems.map((item, idx) => (
                  <div key={item.id} className="group bg-white dark:bg-gray-800 rounded-4xl overflow-hidden shadow-sm border border-gray-100 dark:border-gray-700 hover:shadow-2xl hover:-translate-y-2 transition-all animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                    <div className="h-2.5 bg-ev-blue"></div>
                    <div className="p-8">
                      <div className="flex justify-between items-start mb-6">
                        <div className="w-12 h-12 bg-blue-50 dark:bg-blue-900/20 rounded-2xl flex items-center justify-center text-ev-blue">
                          <i className={`fas ${category === 'livros' ? 'fa-book' : category === 'horarios' ? 'fa-calendar-alt' : 'fa-file-alt'} text-2xl`}></i>
                        </div>
                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{item.date}</span>
                      </div>
                      <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 leading-snug group-hover:text-ev-blue transition-colors">
                        {item.title}
                      </h3>
                      <p className="text-xs text-ev-brown dark:text-ev-text-light font-black mb-4 uppercase tracking-tighter italic">Por: {item.author}</p>
                      <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 line-clamp-3 leading-relaxed">
                        {item.description}
                      </p>
                      <div className="flex items-center justify-between pt-6 border-t border-gray-100 dark:border-gray-700">
                        <a 
                          href={item.downloadUrl} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="flex items-center gap-2 text-ev-blue font-black text-xs uppercase tracking-widest hover:underline"
                        >
                          <i className="fas fa-eye"></i> {t('view', language)}
                        </a>
                        <a 
                          href={item.downloadUrl} 
                          download={`${item.title}.pdf`}
                          className="bg-ev-blue text-white px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 transition-colors shadow-lg"
                        >
                          <i className="fas fa-download mr-1"></i> {t('download', language)}
                        </a>
                      </div>
                    </div>
                  </div>
                ))
              ) : (
                <div className="col-span-full py-24 text-center space-y-4 opacity-40 animate-fadeIn">
                  <i className="fas fa-folder-open text-7xl mb-4"></i>
                  <p className="text-xl font-black uppercase tracking-widest">{t('no_files', language)}</p>
                  <Link to="/" className="text-ev-blue underline font-bold">Voltar para Início</Link>
                </div>
              )}
            </div>
          </>
        )}
      </main>
      <Footer />
    </div>
  );
};

