export default Home;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  // Status estáveis gerados uma vez por sessão do componente
  const usersWithStatus = useMemo(() => {
    return storage.getUsers().map(u => ({
      ...u,
      isOnline: u.id === currentUser?.id ? true : Math.random() > 0.4,
      lastSeen: u.id === currentUser?.id ? 'Agora' : 'Há ' + Math.floor(Math.random() * 59) + ' min'
    }));
  }, [currentUser?.id]);

  useEffect(() => {
    setMessages(storage.getMessages());
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  // Lógica para o botão de voltar do hardware (celular/navegador)
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (selectedUser) {
        // Intercepta o voltar e apenas fecha o chat selecionado
        setSelectedUser(null);
        // Previne que a navegação continue para fora da página
        window.history.pushState(null, '', window.location.href);
      }
    };

    if (selectedUser) {
      // Quando um chat abre, adicionamos uma entrada no histórico para ser "voltável"
      window.history.pushState(null, '', window.location.href);
      window.addEventListener('popstate', handlePopState);
    }

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;

    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else {
      processFile(file);
    }
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({
        media: event.target?.result as string,
        mediaType: file.type,
        fileName: file.name
      });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];

      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) audioChunksRef.current.push(e.data);
      };

      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => {
          saveMessage({
            media: e.target?.result as string,
            mediaType: 'audio/webm',
            fileName: `audio_record_${Date.now()}.webm`
          });
        };
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };

      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      alert('Não foi possível acessar o microfone.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) ||
           (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => {
    if (authorId === currentUser?.id) return 'Você';
    return usersWithStatus.find(u => u.id === authorId)?.name || 'Usuário';
  };

  const getAuthorPhoto = (authorId: string) => {
    return usersWithStatus.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';
  };

  const handleBackAction = () => {
    if (selectedUser) {
      setSelectedUser(null);
    } else {
      navigate('/');
    }
  };

  return (
    <Layout title={selectedUser ? (selectedUser === 'general' ? 'Chat Geral' : selectedUser.name) : "Mensagens"} backTo="/" showBackButton={true} onBack={handleBackAction}>
      {fullScreenImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-4 animate-fadeIn"
          onClick={() => setFullScreenImage(null)}
        >
          <button className="absolute top-6 right-6 text-white text-2xl hover:scale-110 transition-transform">
            <i className="fas fa-times"></i>
          </button>
          <img 
            src={fullScreenImage} 
            className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoomIn" 
            alt="Full screen"
            onClick={(e) => e.stopPropagation()} 
          />
        </div>
      )}

      {selectedUser ? (
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-4xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800 relative">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <div className="relative">
              <img 
                src={selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo} 
                onClick={() => setFullScreenImage(selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo)}
                className="w-10 h-10 rounded-full object-cover shadow-sm border border-gray-200 dark:border-gray-700 cursor-pointer hover:scale-105 transition-transform" 
                alt="" 
              />
              {selectedUser === 'general' || selectedUser.isOnline ? (
                <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full shadow-sm"></div>
              ) : null}
            </div>
            <div>
              <h3 className="font-black text-gray-800 dark:text-gray-100 leading-tight tracking-tight">
                {selectedUser === 'general' ? 'Chat Geral' : selectedUser.name}
              </h3>
              <p className={`text-[10px] font-black uppercase tracking-widest ${selectedUser === 'general' || selectedUser.isOnline ? 'text-green-500' : 'text-gray-400'}`}>
                {selectedUser === 'general' ? 'Online' : (selectedUser.isOnline ? 'Online' : 'Visto ' + selectedUser.lastSeen)}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar bg-gray-50/30 dark:bg-gray-900/30">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40">
                <i className="fas fa-comments text-6xl mb-4 text-gray-200 dark:text-gray-700"></i>
                <p className="font-black uppercase tracking-widest text-[10px]">Inicie uma conversa</p>
              </div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[85%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && (
                        <img 
                          src={getAuthorPhoto(msg.authorId)} 
                          onClick={() => setFullScreenImage(getAuthorPhoto(msg.authorId))}
                          className="w-8 h-8 rounded-full flex-shrink-0 mt-1 shadow-sm cursor-pointer hover:scale-110 transition-transform" 
                          alt="" 
                        />
                      )}
                      <div className="flex flex-col">
                        {selectedUser === 'general' && !isMine && (
                          <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>
                        )}
                        <div className={`p-3.5 rounded-3xl text-sm shadow-sm relative group ${
                          isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-100 dark:border-gray-700'
                        }`}>
                          {msg.text && <p className="leading-relaxed font-medium">{msg.text}</p>}

                          {msg.media && (
                            <div className="mt-2 space-y-2">
                              {msg.mediaType?.startsWith('image/') ? (
                                <img 
                                  src={msg.media} 
                                  onClick={() => setFullScreenImage(msg.media!)}
                                  className="max-w-full rounded-2xl shadow-md cursor-pointer hover:opacity-90" 
                                  alt="Anexo" 
                                />
                              ) : msg.mediaType?.startsWith('video/') ? (
                                <video src={msg.media} controls className="max-w-full rounded-2xl shadow-md" />
                              ) : msg.mediaType?.startsWith('audio/') ? (
                                <audio src={msg.media} controls className="max-w-full h-10" />
                              ) : null}

                              <button 
                                onClick={() => downloadMedia(msg.media!, msg.fileName || 'anexo')}
                                className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-all shadow-sm ${
                                  isMine ? 'bg-white/20 hover:bg-white/40 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'
                                }`}
                              >
                                <i className="fas fa-download"></i> Baixar Mídia
                              </button>
                            </div>
                          )}

                          <p className={`text-[9px] mt-1.5 text-right font-black uppercase tracking-widest opacity-60`}>
                            {new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Menu de Mídia */}
          {showMediaMenu && (
            <div className="absolute bottom-20 left-4 right-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-2xl border border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-4 animate-slideUp z-50">
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm">
                <i className="fas fa-image text-2xl"></i>
                <span className="text-[10px] font-black uppercase tracking-widest">Galeria</span>
                <input type="file" accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, 'image')} />
              </label>
