import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Theme, Language } from '../types';
import { useNavigate } from 'react-router-dom';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

interface SettingsProps {
  onLogout: () => void;
  toggleTheme: () => void;
  isDark: boolean;
}

const Settings: React.FC<SettingsProps> = ({ onLogout, toggleTheme, isDark }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<string | null>('profile');
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    photo: ''
  });
  const [successMsg, setSuccessMsg] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const navigate = useNavigate();
  const { language, setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    const currentUser = storage.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
      setFormData({
        name: currentUser.name,
        photo: currentUser.photo
      });
    }
  }, []);

  const handleLogout = () => {
    storage.logout();
    onLogout();
    navigate('/login');
  };

  const handleSaveProfile = () => {
    if (!user) return;

    const users = storage.getUsers();
    const updatedUsers = users.map(u => {
      if (u.id === user.id) {
        return {
          ...u,
          name: formData.name,
          photo: formData.photo
        };
      }
      return u;
    });

    storage.setUsers(updatedUsers);
    const updatedUser = updatedUsers.find(u => u.id === user.id) || null;
    setUser(updatedUser);
    setIsEditing(false);
    setSuccessMsg(t('success_update', language));
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setFormData({ ...formData, photo: event.target?.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const sections = [
    { id: 'profile', title: t('profile', language), icon: 'fa-user' },
    { id: 'security', title: t('security', language), icon: 'fa-lock' },
    { id: 'notifications', title: t('notifications', language), icon: 'fa-bell' },
    { id: 'prefs', title: t('preferences', language), icon: 'fa-cog' },
  ];

  if (!user) return null;

  return (
    <Layout title={t('settings', language)} backTo="/">
      {fullScreenImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-4 animate-fadeIn"
          onClick={() => setFullScreenImage(null)}
        >
          <button className="absolute top-6 right-6 text-white text-2xl hover:scale-110 transition-transform">
            <i className="fas fa-times"></i>
          </button>
          <img 
            src={fullScreenImage} 
            className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoomIn" 
            alt="Full screen"
            onClick={(e) => e.stopPropagation()} 
          />
        </div>
      )}

      <div className="space-y-6">
        {successMsg && (
          <div className="bg-green-100 text-green-700 p-4 rounded-3xl font-bold text-center animate-bounce shadow-sm">
            {successMsg}
          </div>
        )}

        <div className="bg-white dark:bg-gray-800 p-6 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4 animate-fadeIn">
          <div className="relative group">
            <img 
              src={isEditing ? formData.photo : user.photo} 
              onClick={() => !isEditing && setFullScreenImage(user.photo)}
              className={`w-20 h-20 rounded-full object-cover ring-4 ring-ev-blue/10 shadow-lg ${!isEditing ? 'cursor-pointer hover:scale-105 transition-transform' : ''}`} 
              alt="Avatar" 
            />
            {isEditing && (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/50 rounded-full flex flex-col items-center justify-center text-white transition-opacity hover:bg-black/60"
              >
                <i className="fas fa-camera text-xl"></i>
                <span className="text-[8px] font-bold uppercase mt-1">{t('change_photo', language)}</span>
              </button>
            )}
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handlePhotoChange} 
            />
          </div>
          <div>
            <h2 className="text-xl font-black text-gray-800 dark:text-white leading-tight">
              {isEditing ? formData.name || '...' : user.name}
            </h2>
            <p className="text-sm text-gray-500 font-medium">#{user.Number} • {user.anoFrequencia}º Ano</p>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 animate-fadeIn">
          {sections.map(s => (
            <button
              key={s.id}
              onClick={() => {
                setActiveSection(s.id);
                setIsEditing(false);
              }}
              className={`flex flex-col items-center justify-center p-4 rounded-3xl transition-all shadow-sm ${
                activeSection === s.id ? 'bg-ev-blue text-white scale-95 shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'
              }`}
            >
              <i className={`fas ${s.icon} text-xl mb-1`}></i>
              <span className="text-[10px] font-bold uppercase tracking-widest">{s.title}</span>
            </button>
          ))}
        </div>

        <div className="space-y-4">
          {activeSection === 'profile' && (
            <div className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
              <div className="flex items-center justify-between mb-8">
                <h3 className="font-black text-ev-blue dark:text-white uppercase tracking-tighter">{t('profile', language)}</h3>
                {!isEditing && (
                  <button 
                    onClick={() => setIsEditing(true)}
                    className="bg-ev-blue/10 text-ev-blue px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-ev-blue hover:text-white transition-all"
