                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('full_name', language)}</label>
                    <input
                      type="text"
                      className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner transition-all"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('student_number', language)}</label>
                      <div className="w-full p-4 rounded-3xl bg-gray-100 dark:bg-gray-900 dark:text-gray-500 text-sm italic font-medium">
                        {user.Number}
                      </div>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('year', language)}</label>
                      <div className="w-full p-4 rounded-3xl bg-gray-100 dark:bg-gray-900 dark:text-gray-500 text-sm italic font-medium">
                        {user.anoFrequencia}º Ano
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-3 pt-4">
                    <button 
                      onClick={handleSaveProfile}
                      className="flex-1 bg-ev-blue text-white py-4 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase text-xs tracking-widest"
                    >
                      {t('save', language)}
                    </button>
                    <button 
                      onClick={() => {
                        setIsEditing(false);
                        setFormData({
                          name: user.name,
                          photo: user.photo
                        });
                      }}
                      className="px-6 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 rounded-3xl text-xs font-black uppercase tracking-widest"
                    >
                      {t('cancel', language)}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-3xl border border-gray-100 dark:border-gray-700">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('full_name', language)}</span>
                    <span className="text-base font-bold text-gray-800 dark:text-white">{user.name}</span>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-3xl border border-gray-100 dark:border-gray-700">
                      <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('student_number', language)}</span>
                      <span className="text-base font-bold text-gray-800 dark:text-white">{user.Number}</span>
                    </div>
                    <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-3xl border border-gray-100 dark:border-gray-700">
                      <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('year', language)}</span>
                      <span className="text-base font-bold text-gray-800 dark:text-white">{user.anoFrequencia}º Ano</span>
                    </div>
