                      alt="" 
                    />
                    <div>
                      <h4 className="font-black text-gray-800 dark:text-white leading-tight uppercase tracking-tight">{post.userName}</h4>
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                        {new Date(post.timestamp).toLocaleDateString()}
                      </p>
                    </div>
                  </div>

                  {post.caption && (
                    <div className="px-6 pb-4">
                      <p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium">
                        {post.caption}
                      </p>
                    </div>
                  )}

                  <div className="bg-black/5 dark:bg-black/20 aspect-video flex items-center justify-center relative">
                    {post.isImage ? (
                      <img 
                        src={post.media} 
                        onClick={() => setFullScreenImage(post.media)}
                        className="w-full h-full object-contain cursor-pointer hover:opacity-95 transition-opacity" 
                        alt="" 
                      />
                    ) : (
                      <video controls src={post.media} className="w-full h-full" />
                    )}
                  </div>

                  <div className="p-6 space-y-4">
                    <div className="flex items-center justify-between border-b border-gray-50 dark:border-gray-700 pb-5">
                       <div className="flex gap-8">
                          <button 
                            onClick={() => handleLike(post.id)}
                            className={`flex items-center gap-2.5 transition-colors ${currentUser && post.likedBy?.includes(currentUser.id) ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}
                          >
                             <i className={`${currentUser && post.likedBy?.includes(currentUser.id) ? 'fas' : 'far'} fa-heart text-2xl`}></i>
                             <span className="text-xs font-black uppercase tracking-widest">{post.likes || 0} Adoros</span>
                          </button>
                          <button 
                            onClick={() => setActiveCommentId(activeCommentId === post.id ? null : post.id)}
                            className="flex items-center gap-2.5 text-gray-400 hover:text-ev-blue transition-colors"
                          >
                             <i className="far fa-comment text-2xl"></i>
                             <span className="text-xs font-black uppercase tracking-widest">{post.comments?.length || 0} Comentários</span>
                          </button>
                       </div>
                    </div>

                    {post.comments && post.comments.length > 0 && (
                      <div className="space-y-4 pt-4 max-h-60 overflow-y-auto no-scrollbar">
                        {post.comments.map((comment, idx) => (
                          <div key={idx} className="flex gap-3 animate-fadeIn">
                            <img 
                              src={comment.authorPhoto} 
                              onClick={() => setFullScreenImage(comment.authorPhoto)}
                              className="w-8 h-8 rounded-full object-cover flex-shrink-0 cursor-pointer hover:scale-110 transition-transform" 
                              alt="" 
                            />
                            <div className="bg-gray-50 dark:bg-gray-700 p-3 rounded-2xl flex-1 shadow-inner">
                              <p className="text-[9px] font-black text-ev-blue uppercase tracking-widest mb-1">{comment.authorName}</p>
                              <p className="text-xs text-gray-600 dark:text-gray-200 leading-relaxed">{comment.text}</p>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}

                    {(activeCommentId === post.id || !post.comments?.length) && (
                      <div className="flex gap-3 pt-4">
                        <input 
                          type="text" 
                          placeholder={currentUser ? "Escreva um comentário..." : "Faça login para comentar"}
                          readOnly={!currentUser}
                          onClick={() => !currentUser && navigate('/login')}
                          className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-5 py-3 text-xs dark:text-white focus:ring-2 focus:ring-ev-blue shadow-inner"
                          value={activeCommentId === post.id ? commentText : ''}
                          onChange={(e) => {
                            if (currentUser) {
                              setActiveCommentId(post.id);
                              setCommentText(e.target.value);
                            }
                          }}
                          onKeyDown={(e) => e.key === 'Enter' && handleAddComment(post.id)}
                        />
                        <button 
                          onClick={() => handleAddComment(post.id)}
                          className="bg-ev-blue text-white w-10 h-10 rounded-full flex items-center justify-center hover:bg-blue-600 transition-all shadow-md active:scale-90"
                        >
                          <i className="fas fa-paper-plane text-xs"></i>
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

