              <Link to="/library/mono" className="block px-4 py-3 text-white text-sm hover:bg-ev-brown border-b border-white/5">{t('monographs', language)}</Link>
              <Link to="/library/planos" className="block px-4 py-3 text-white text-sm hover:bg-ev-brown border-b border-white/5">{t('analytical_plans', language)}</Link>
              <Link to="/library/horarios" className="block px-4 py-3 text-white text-sm hover:bg-ev-brown border-b border-white/5">{t('schedules', language)}</Link>
              <Link to="/library/livros" className="block px-4 py-3 text-white text-sm hover:bg-ev-brown border-b border-white/5">{t('books', language)}</Link>
              <Link to="/library/materiais" className="block px-4 py-3 text-white text-sm hover:bg-ev-brown">{t('academic_materials', language)}</Link>
            </div>
          </div>

          <div className="flex-1 relative border-r border-white/5">
            <button 
              onClick={() => toggleDropdown('communities')}
              className="w-full flex flex-col items-center justify-center py-4 text-white hover:bg-ev-brown transition-colors"
            >
              <i className="fas fa-bullhorn text-lg mb-1"></i>
              <span className="text-[9px] font-black uppercase tracking-tighter">{t('communities', language)}</span>
            </button>
            <div className={`${openDropdown === 'communities' ? 'block' : 'hidden'} absolute top-full right-0 lg:left-0 w-64 bg-ev-blue shadow-2xl rounded-b-2xl overflow-hidden border-t border-white/10`}>
              <Link to="/communities/geral" className="flex items-center gap-3 px-4 py-3.5 text-white text-sm hover:bg-ev-brown border-b border-white/5"><i className="fas fa-info-circle opacity-70"></i> Geral</Link>
              <Link to="/communities/ano1" className="flex items-center gap-3 px-4 py-3.5 text-white text-sm hover:bg-ev-brown border-b border-white/5"><i className="fas fa-user-graduate opacity-70"></i> 1º Ano</Link>
              <Link to="/communities/ano2" className="flex items-center gap-3 px-4 py-3.5 text-white text-sm hover:bg-ev-brown border-b border-white/5"><i className="fas fa-user-graduate opacity-70"></i> 2º Ano</Link>
              <Link to="/communities/ano3" className="flex items-center gap-3 px-4 py-3.5 text-white text-sm hover:bg-ev-brown border-b border-white/5"><i className="fas fa-user-graduate opacity-70"></i> 3º Ano</Link>
              <Link to="/communities/ano4" className="flex items-center gap-3 px-4 py-3.5 text-white text-sm hover:bg-ev-brown border-b border-white/5"><i className="fas fa-user-graduate opacity-70"></i> 4º Ano</Link>
              <Link to="/communities/publicar" className="flex items-center gap-3 px-4 py-3.5 text-white text-sm hover:bg-ev-brown"><i className="fas fa-plus-circle opacity-70"></i> {t('publish', language)}</Link>
            </div>
          </div>

          <button 
            onClick={() => navigate('/chat')}
            className="flex-1 flex flex-col items-center justify-center py-4 text-white hover:bg-ev-brown transition-colors"
          >
            <i className="fas fa-comments text-lg mb-1"></i>
            <span className="text-[9px] font-black uppercase tracking-tighter">{t('chat', language)}</span>
          </button>
        </div>
      </nav>

      <section className="relative w-full h-[300px] md:h-[450px] overflow-hidden bg-black shadow-inner">
        <div 
          className="flex transition-transform duration-700 ease-in-out h-full"
          style={{ transform: `translateX(-${currentSlide * 100}%)` }}
        >
          {slides.map((slide, index) => (
            <div key={index} className="min-w-full h-full relative">
              <img src={slide.url} alt={slide.caption} className="w-full h-full object-cover opacity-75" />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-black/30"></div>
              <div className="absolute bottom-0 left-0 right-0 p-8 text-center">
                <h3 className="text-white text-lg md:text-2xl font-bold mb-2">{slide.caption}</h3>
                <div className="w-16 h-1 bg-ev-blue mx-auto rounded-full"></div>
              </div>
            </div>
          ))}
        </div>
      </section>

      <main className="max-w-6xl mx-auto w-full p-6 space-y-12">
        <section className="bg-white dark:bg-gray-800 rounded-4xl shadow-xl p-8 border border-gray-100 dark:border-gray-700 relative overflow-hidden animate-fadeIn">
          <h2 className="text-2xl font-bold text-ev-blue dark:text-ev-text-light mb-8 flex items-center gap-3">
            <i className="fas fa-chart-line"></i>
            {t('statistics', language)}
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6">
            {stats.map((stat, index) => (
              <div key={index} className="bg-gray-50 dark:bg-gray-700/50 p-6 rounded-3xl text-center border border-gray-100 dark:border-gray-600 transition-transform hover:scale-105">
                <div className="text-3xl font-black text-ev-blue dark:text-blue-400 mb-1">{stat.value}</div>
                <div className="text-[10px] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-widest">{stat.label}</div>
              </div>
            ))}
          </div>
        </section>

        <section className="bg-white dark:bg-gray-800 rounded-4xl shadow-xl p-8 border border-gray-100 dark:border-gray-700 animate-fadeIn" style={{ animationDelay: '0.2s' }}>
          <h2 className="text-2xl font-bold text-ev-blue dark:text-ev-text-light mb-8 flex items-center gap-3">
            <i className="fas fa-user-shield"></i>
            {t('leadership', language)}
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {staff.map((person, index) => (
              <div key={index} className="group bg-gray-50 dark:bg-gray-700/50 p-5 rounded-3xl border border-transparent hover:border-ev-blue/20 hover:bg-white dark:hover:bg-gray-700 transition-all shadow-sm">
                <div className="text-ev-blue dark:text-blue-400 font-bold">{person.name}</div>
                <div className="text-[10px] italic text-gray-500 dark:text-gray-400 uppercase tracking-tighter">{person.role}</div>
                <div className="mt-4 pt-3 border-t border-gray-200 dark:border-gray-600 text-xs text-gray-400">
                  <i className="fas fa-envelope opacity-50 mr-2"></i>
                  {person.email}
                </div>
              </div>
            ))}
          </div>
        </section>
      </main>
      <Footer />
    </div>
  );
};

export default Home;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  const usersWithStatus = useMemo(() => {
    return storage.getUsers().map(u => ({
      ...u,
      isOnline: u.id === currentUser?.id ? true : Math.random() > 0.4,
      lastSeen: u.id === currentUser?.id ? 'Agora' : 'Há ' + Math.floor(Math.random() * 59) + ' min'
    }));
  }, [currentUser?.id]);

  useEffect(() => {
    setMessages(storage.getMessages());
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  useEffect(() => {
    const handlePopState = () => {
      if (selectedUser) {
        setSelectedUser(null);
        window.history.pushState(null, '', window.location.href);
      }
    };
    if (selectedUser) {
      window.history.pushState(null, '', window.location.href);
      window.addEventListener('popstate', handlePopState);
    }
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;
    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };
    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else processFile(file);
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({ media: event.target?.result as string, mediaType: file.type, fileName: file.name });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => saveMessage({ media: e.target?.result as string, mediaType: 'audio/webm', fileName: `record_${Date.now()}.webm` });
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };
      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch { alert('Não foi possível acessar o microfone.'); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media; link.download = fileName;
    document.body.appendChild(link); link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) || (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => authorId === currentUser?.id ? 'Você' : usersWithStatus.find(u => u.id === authorId)?.name || 'Usuário';
  const getAuthorPhoto = (authorId: string) => usersWithStatus.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';

  return (
    <Layout title={selectedUser ? (selectedUser === 'general' ? 'Chat Geral' : selectedUser.name) : "Mensagens"} backTo="/" showBackButton={true} onBack={() => selectedUser ? setSelectedUser(null) : navigate('/')}>
      {fullScreenImage && (
        <div className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-4 animate-fadeIn" onClick={() => setFullScreenImage(null)}>
          <button className="absolute top-6 right-6 text-white text-2xl hover:scale-110 transition-transform"><i className="fas fa-times"></i></button>
          <img src={fullScreenImage} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoomIn" alt="Full screen" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {selectedUser ? (
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-4xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800 relative">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <div className="relative">
              <img 
                src={selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo} 
                onClick={() => setFullScreenImage(selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo)}
                className="w-10 h-10 rounded-full object-cover shadow-sm border-2 border-ev-brown cursor-pointer hover:scale-105 transition-transform" 
                alt="" 
              />
              {(selectedUser === 'general' || selectedUser.isOnline) && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full shadow-sm"></div>}
            </div>
            <div>
              <h3 className="font-black text-gray-800 dark:text-gray-100 leading-tight tracking-tight">{selectedUser === 'general' ? 'Chat Geral' : selectedUser.name}</h3>
              <p className={`text-[10px] font-black uppercase tracking-widest ${selectedUser === 'general' || selectedUser.isOnline ? 'text-green-500' : 'text-gray-400'}`}>
                {selectedUser === 'general' ? 'Online' : (selectedUser.isOnline ? 'Online' : 'Visto ' + selectedUser.lastSeen)}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar bg-gray-50/30 dark:bg-gray-900/30">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40"><i className="fas fa-comments text-6xl mb-4 text-gray-200"></i><p className="font-black uppercase tracking-widest text-[10px]">Inicie uma conversa</p></div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[85%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && <img src={getAuthorPhoto(msg.authorId)} onClick={() => setFullScreenImage(getAuthorPhoto(msg.authorId))} className="w-8 h-8 rounded-full flex-shrink-0 mt-1 shadow-sm cursor-pointer hover:scale-110 transition-transform border-2 border-ev-brown" alt="" />}
                      <div className="flex flex-col">
                        {selectedUser === 'general' && !isMine && <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>}
                        <div className={`p-3.5 rounded-3xl text-sm shadow-sm relative group ${isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-100 dark:border-gray-700'}`}>
                          {msg.text && <p className="leading-relaxed font-medium">{msg.text}</p>}
                          {msg.media && (
                            <div className="mt-2 space-y-2">
                              {msg.mediaType?.startsWith('image/') ? <img src={msg.media} onClick={() => setFullScreenImage(msg.media!)} className="max-w-full rounded-2xl shadow-md cursor-pointer hover:opacity-90" alt="" /> : msg.mediaType?.startsWith('video/') ? <video src={msg.media} controls className="max-w-full rounded-2xl shadow-md" /> : msg.mediaType?.startsWith('audio/') ? <audio src={msg.media} controls className="max-w-full h-10" /> : null}
                              <button onClick={() => downloadMedia(msg.media!, msg.fileName || 'anexo')} className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-all ${isMine ? 'bg-white/20 hover:bg-white/40 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'}`}><i className="fas fa-download"></i> Baixar Mídia</button>
                            </div>
                          )}
                          <p className="text-[9px] mt-1.5 text-right font-black uppercase tracking-widest opacity-60">{new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          {showMediaMenu && (
            <div className="absolute bottom-20 left-4 right-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-2xl border border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-4 animate-slideUp z-50">
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm"><i className="fas fa-image text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Galeria</span><input type="file" accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, 'image')} /></label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm"><i className="fas fa-video text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Vídeo 30s</span><input type="file" accept="video/*" className="hidden" onChange={(e) => handleFileUpload(e, 'video')} /></label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm"><i className="fas fa-file-audio text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Arquivo Áudio</span><input type="file" accept="audio/*" className="hidden" onChange={(e) => handleFileUpload(e, 'audio')} /></label>
              <button onClick={startRecording} className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl hover:bg-red-500 hover:text-white transition-all shadow-sm"><i className="fas fa-microphone text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Gravar Voz</span></button>
            </div>
          )}

          <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-800">
            {isRecording ? (
              <div className="flex items-center justify-between gap-4 bg-red-50 dark:bg-red-900/20 p-3.5 rounded-3xl border border-red-100"><div className="flex items-center gap-3"><div className="w-3.5 h-3.5 bg-red-500 rounded-full animate-ping"></div><span className="text-xs font-black text-red-600 uppercase tracking-widest">Gravando: {Math.floor(recordingTime / 60)}:{(recordingTime % 60).toString().padStart(2, '0')}</span></div><button onClick={stopRecording} className="bg-red-500 text-white px-6 py-2.5 rounded-full font-black uppercase text-[10px] tracking-[0.2em] shadow-lg">Finalizar</button></div>
            ) : (
              <div className="flex gap-3"><button onClick={() => setShowMediaMenu(!showMediaMenu)} className={`w-12 h-12 flex items-center justify-center rounded-full transition-all shadow-md ${showMediaMenu ? 'bg-ev-brown text-white rotate-45' : 'bg-gray-100 text-gray-500 dark:bg-gray-700'}`}><i className="fas fa-plus"></i></button><input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Escreva sua mensagem..." className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-6 py-3 text-sm focus:ring-2 focus:ring-ev-blue shadow-inner dark:text-white font-medium"/><button onClick={handleSend} disabled={!inputText.trim()} className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-all ${!inputText.trim() ? 'bg-gray-200 text-gray-400 cursor-not-allowed dark:bg-gray-800' : 'bg-ev-blue text-white hover:bg-blue-600'}`}><i className="fas fa-paper-plane"></i></button></div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div onClick={() => setSelectedUser('general')} className="flex items-center gap-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all hover:scale-[1.02] animate-fadeIn">
            <div className="relative"><div className="w-14 h-14 bg-ev-blue rounded-full flex items-center justify-center text-white shadow-inner cursor-pointer border-2 border-ev-brown" onClick={(e) => { e.stopPropagation(); setFullScreenImage('https://picsum.photos/seed/general/200'); }}><i className="fas fa-users text-2xl"></i></div><div className="absolute bottom-0.5 right-0.5 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full shadow-sm animate-pulse"></div></div>
            <div className="flex-1"><h3 className="font-black dark:text-white uppercase tracking-tight">Chat Geral</h3><p className="text-[10px] text-green-500 font-black uppercase tracking-[0.2em] mt-0.5">Disponível Agora</p></div>
          </div>
          <div className="mt-10 mb-4 ml-4"><h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Meus Contatos</h4></div>
          <div className="space-y-3">
            {usersWithStatus.filter(u => u.id !== currentUser?.id).map((user, idx) => (
              <div key={user.id} onClick={() => setSelectedUser(user)} className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-all hover:scale-[1.01] animate-fadeIn" style={{ animationDelay: `${idx * 0.05}s` }}>
                <div className="relative"><img src={user.photo} onClick={(e) => { e.stopPropagation(); setFullScreenImage(user.photo); }} className="w-14 h-14 rounded-full object-cover border-2 border-ev-brown shadow-sm cursor-pointer hover:scale-105 transition-transform" alt="" />{user.isOnline && <div className="absolute bottom-0.5 right-0.5 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full shadow-sm"></div>}</div>
                <div className="flex-1"><h3 className="font-black dark:text-white uppercase tracking-tight leading-tight">{user.name}</h3><p className={`text-[10px] font-black uppercase tracking-widest mt-0.5 ${user.isOnline ? 'text-green-500' : 'text-gray-400'}`}>{user.isOnline ? 'Online agora' : 'Visto ' + user.lastSeen}</p></div>
                <div className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-700 flex items-center justify-center text-gray-300"><i className="fas fa-chevron-right text-xs"></i></div>
              </div>
            ))}
          </div>
        </div>
      )}
    </Layout>
  );
};

export default Chat;

import React, { useState, useEffect, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { UserPost, User, Language, Comment } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const UserPosts: React.FC = () => {
  const navigate = useNavigate();
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [posts, setPosts] = useState<UserPost[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [caption, setCaption] = useState('');
  const [mediaData, setMediaData] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<string>('');
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState('');
  const [activeCommentId, setActiveCommentId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const { language } = useContext(LanguageContext);

  useEffect(() => {
    const storedPosts = storage.getPosts();
    setPosts(storedPosts);
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) { navigate('/login'); return; }
    if (!mediaData) return;
    setIsUploading(true);
    const newPost: UserPost = {
      id: 'post_' + Date.now(),
      userId: currentUser.id,
      userName: currentUser.name,
      userPhoto: currentUser.photo,
      caption: caption,
      media: mediaData,
      mediaType: mediaType,
      isImage: mediaType.startsWith('image/'),
      timestamp: new Date().toISOString(),
      likes: 0,
      likedBy: [],
      comments: []
    };
    const updated = [newPost, ...posts];
    setPosts(updated);
    storage.setPosts(updated);
    setTimeout(() => { setCaption(''); setMediaData(null); setIsUploading(false); setView('feed'); }, 1000);
  };

  const handleLike = (postId: string) => {
    if (!currentUser) { navigate('/login'); return; }
    const updated = posts.map(post => {
      if (post.id === postId) {
        const hasLiked = post.likedBy.includes(currentUser.id);
        const newLikedBy = hasLiked ? post.likedBy.filter(id => id !== currentUser.id) : [...post.likedBy, currentUser.id];
        return { ...post, likedBy: newLikedBy, likes: newLikedBy.length };
      }
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
  };

  const handleAddComment = (postId: string) => {
    if (!currentUser) { navigate('/login'); return; }
    if (!commentText.trim()) return;
    const newComment: Comment = { authorName: currentUser.name, authorPhoto: currentUser.photo, text: commentText, timestamp: new Date().toISOString() };
    const updated = posts.map(post => {
      if (post.id === postId) return { ...post, comments: [...(post.comments || []), newComment] };
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
    setCommentText(''); setActiveCommentId(null);
  };

  return (
    <Layout title={t('posts', language)} backTo="/" actions={currentUser && <button onClick={() => setView(view === 'feed' ? 'publish' : 'feed')} className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm">{view === 'feed' ? t('publish', language) : t('view', language)}</button>}>
      {fullScreenImage && (
        <div className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-4 animate-fadeIn" onClick={() => setFullScreenImage(null)}>
          <button className="absolute top-6 right-6 text-white text-2xl hover:scale-110 transition-transform"><i className="fas fa-times"></i></button>
          <img src={fullScreenImage} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoomIn" alt="" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      <div className="max-w-2xl mx-auto pb-10">
        {view === 'publish' ? (
          <div className="bg-white dark:bg-gray-800 p-10 rounded-5xl shadow-xl animate-fadeIn">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase mb-10">{t('publish', language)}</h2>
            <form onSubmit={handlePublish} className="space-y-6">
              <textarea className="w-full p-5 rounded-3xl bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none" rows={3} placeholder="Diga algo..." value={caption} onChange={(e) => setCaption(e.target.value)} />
              <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-5xl p-12 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                <input type="file" accept="image/*,video/*" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" onChange={(e) => {
                   const file = e.target.files?.[0];
                   if (file) {
                     const reader = new FileReader();
                     reader.onload = (ev) => { setMediaData(ev.target?.result as string); setMediaType(file.type); };
                     reader.readAsDataURL(file);
                   }
                }} />
                {mediaData ? <img src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-2xl" alt="" /> : <div className="text-gray-400"><i className="fas fa-photo-video text-3xl text-ev-blue mb-4"></i><p className="font-black uppercase tracking-widest text-xs">Selecione Mídia</p></div>}
              </div>
              <button type="submit" disabled={!mediaData || isUploading} className={`w-full py-5 rounded-3xl font-black shadow-xl uppercase transition-all ${!mediaData ? 'bg-gray-200 text-gray-400' : 'bg-ev-blue text-white hover:bg-blue-600'}`}>{isUploading ? 'A publicar...' : t('publish', language)}</button>
            </form>
          </div>
        ) : (
          <div className="space-y-12">
            {posts.map((post, idx) => (
              <div key={post.id} className="bg-white dark:bg-gray-800 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                <div className="p-6 flex items-center gap-4">
                  <img src={post.userPhoto} onClick={() => setFullScreenImage(post.userPhoto)} className="w-12 h-12 rounded-full object-cover border-2 border-ev-brown shadow-sm cursor-pointer hover:scale-105 transition-transform" alt="" />
                  <div><h4 className="font-black text-gray-800 dark:text-white uppercase tracking-tight leading-tight">{post.userName}</h4><p className="text-[10px] text-gray-400 font-bold uppercase">{new Date(post.timestamp).toLocaleDateString()}</p></div>
                </div>
                {post.caption && <div className="px-6 pb-4"><p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium">{post.caption}</p></div>}
                <div className="bg-black/5 aspect-video flex items-center justify-center relative">{post.isImage ? <img src={post.media} onClick={() => setFullScreenImage(post.media)} className="w-full h-full object-contain cursor-pointer" alt="" /> : <video controls src={post.media} className="w-full h-full" />}</div>
                <div className="p-6 space-y-4">
                  <div className="flex gap-8 border-b border-gray-50 dark:border-gray-700 pb-4">
                    <button onClick={() => handleLike(post.id)} className={`flex items-center gap-2 text-xs font-black uppercase ${currentUser && post.likedBy?.includes(currentUser.id) ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}><i className="fas fa-heart text-xl"></i> {post.likes} Adoros</button>
                    <button onClick={() => setActiveCommentId(activeCommentId === post.id ? null : post.id)} className="flex items-center gap-2 text-gray-400 text-xs font-black uppercase"><i className="far fa-comment text-xl"></i> {post.comments?.length || 0} Comentários</button>
                  </div>
                  {post.comments?.map((comment, cidx) => (
                    <div key={cidx} className="flex gap-3 animate-fadeIn"><img src={comment.authorPhoto} onClick={() => setFullScreenImage(comment.authorPhoto)} className="w-8 h-8 rounded-full object-cover border-2 border-ev-brown cursor-pointer" alt="" /><div className="bg-gray-50 dark:bg-gray-700 p-3 rounded-2xl flex-1"><p className="text-[9px] font-black text-ev-blue uppercase mb-1">{comment.authorName}</p><p className="text-xs text-gray-600 dark:text-gray-200">{comment.text}</p></div></div>
                  ))}
                  <div className="flex gap-3 pt-2"><input type="text" placeholder={currentUser ? "Comentar..." : "Faça login para comentar"} readOnly={!currentUser} onClick={() => !currentUser && navigate('/login')} className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-5 py-3 text-xs dark:text-white" value={activeCommentId === post.id ? commentText : ''} onChange={(e) => { if (currentUser) { setActiveCommentId(post.id); setCommentText(e.target.value); } }} onKeyDown={(e) => e.key === 'Enter' && handleAddComment(post.id)} /><button onClick={() => handleAddComment(post.id)} className="bg-ev-blue text-white w-10 h-10 rounded-full flex items-center justify-center shadow-md active:scale-90"><i className="fas fa-paper-plane text-xs"></i></button></div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default UserPosts;

import React, { useState, useEffect, useContext, useRef } from 'react';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Theme, Language } from '../types';
import { useNavigate } from 'react-router-dom';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

interface SettingsProps {
  onLogout: () => void;
  toggleTheme: () => void;
  isDark: boolean;
}

const Settings: React.FC<SettingsProps> = ({ onLogout, toggleTheme, isDark }) => {
  const [user, setUser] = useState<User | null>(null);
  const [activeSection, setActiveSection] = useState<string | null>('profile');
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({ name: '', photo: '' });
  const [successMsg, setSuccessMsg] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const navigate = useNavigate();
  const { language, setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    const currentUser = storage.getCurrentUser();
    if (currentUser) { setUser(currentUser); setFormData({ name: currentUser.name, photo: currentUser.photo }); }
  }, []);

  const handleSaveProfile = () => {
    if (!user) return;
    const users = storage.getUsers();
    const updatedUsers = users.map(u => u.id === user.id ? { ...u, name: formData.name, photo: formData.photo } : u);
    storage.setUsers(updatedUsers);
    setUser(updatedUsers.find(u => u.id === user.id) || null);
    setIsEditing(false); setSuccessMsg(t('success_update', language));
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => setFormData({ ...formData, photo: event.target?.result as string });
      reader.readAsDataURL(file);
    }
  };

  if (!user) return null;

  return (
    <Layout title={t('settings', language)} backTo="/">
      {fullScreenImage && (
        <div className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-4 animate-fadeIn" onClick={() => setFullScreenImage(null)}>
          <button className="absolute top-6 right-6 text-white text-2xl"><i className="fas fa-times"></i></button>
          <img src={fullScreenImage} className="max-w-full max-h-full object-contain rounded-lg animate-zoomIn" alt="" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      <div className="space-y-6">
        {successMsg && <div className="bg-green-100 text-green-700 p-4 rounded-3xl font-bold text-center animate-bounce shadow-sm">{successMsg}</div>}

        <div className="bg-white dark:bg-gray-800 p-6 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center gap-4 animate-fadeIn">
          <div className="relative group">
            <img 
              src={isEditing ? formData.photo : user.photo} 
              onClick={() => !isEditing && setFullScreenImage(user.photo)}
              className={`w-20 h-20 rounded-full object-cover border-4 border-ev-brown shadow-lg ${!isEditing ? 'cursor-pointer hover:scale-105 transition-transform' : ''}`} 
              alt="" 
            />
            {isEditing && (
              <button onClick={() => fileInputRef.current?.click()} className="absolute inset-0 bg-black/50 rounded-full flex flex-col items-center justify-center text-white transition-opacity">
                <i className="fas fa-camera text-xl"></i><span className="text-[8px] font-bold uppercase mt-1">Trocar</span>
              </button>
            )}
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoChange} />
          </div>
          <div><h2 className="text-xl font-black text-gray-800 dark:text-white leading-tight">{isEditing ? formData.name || '...' : user.name}</h2><p className="text-sm text-gray-500 font-medium">#{user.Number} • {user.anoFrequencia}º Ano</p></div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {[
            { id: 'profile', title: t('profile', language), icon: 'fa-user' },
            { id: 'security', title: t('security', language), icon: 'fa-lock' },
            { id: 'notifications', title: t('notifications', language), icon: 'fa-bell' },
            { id: 'prefs', title: t('preferences', language), icon: 'fa-cog' },
          ].map(s => (
            <button key={s.id} onClick={() => { setActiveSection(s.id); setIsEditing(false); }} className={`flex flex-col items-center justify-center p-4 rounded-3xl transition-all shadow-sm ${activeSection === s.id ? 'bg-ev-blue text-white scale-95 shadow-lg' : 'bg-white dark:bg-gray-800 text-gray-600 dark:text-gray-300'}`}>
              <i className={`fas ${s.icon} text-xl mb-1`}></i><span className="text-[10px] font-bold uppercase tracking-widest">{s.title}</span>
            </button>
          ))}
        </div>

        {activeSection === 'profile' && (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <div className="flex items-center justify-between mb-8"><h3 className="font-black text-ev-blue dark:text-white uppercase tracking-tighter">{t('profile', language)}</h3>{!isEditing && <button onClick={() => setIsEditing(true)} className="bg-ev-blue/10 text-ev-blue px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-ev-blue hover:text-white transition-all">{t('edit_profile', language)}</button>}</div>
            {isEditing ? (
              <div className="space-y-6">
                <div className="space-y-1"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">{t('full_name', language)}</label><input type="text" className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} /></div>
                <div className="flex gap-3 pt-4"><button onClick={handleSaveProfile} className="flex-1 bg-ev-blue text-white py-4 rounded-3xl font-black shadow-xl uppercase text-xs tracking-widest">{t('save', language)}</button><button onClick={() => setIsEditing(false)} className="px-6 bg-gray-100 dark:bg-gray-700 text-gray-500 rounded-3xl text-xs font-black uppercase">Voltar</button></div>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-3xl border border-gray-100"><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('full_name', language)}</span><span className="text-base font-bold text-gray-800 dark:text-white">{user.name}</span></div>
                <div className="grid grid-cols-2 gap-3"><div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-3xl border border-gray-100"><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('student_number', language)}</span><span className="text-base font-bold text-gray-800 dark:text-white">{user.Number}</span></div><div className="p-5 bg-gray-50 dark:bg-gray-700/50 rounded-3xl border border-gray-100"><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-1">{t('year', language)}</span><span className="text-base font-bold text-gray-800 dark:text-white">{user.anoFrequencia}º Ano</span></div></div>
                <div className="pt-6"><button onClick={() => { storage.logout(); navigate('/login'); }} className="w-full text-left p-6 rounded-3xl hover:bg-red-50 text-red-500 border border-red-100 flex items-center justify-between transition-all group"><div className="flex items-center gap-3"><i className="fas fa-sign-out-alt"></i><span className="text-sm font-black uppercase tracking-widest">{t('logout', language)}</span></div><i className="fas fa-chevron-right text-[10px] opacity-30"></i></button></div>
              </div>
            )}
          </div>
        )}

        {activeSection === 'prefs' && (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-md border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h3 className="font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8">{t('preferences', language)}</h3>
            <div className="space-y-6">
              <div className="flex flex-col gap-2 p-5 bg-gray-50 dark:bg-gray-700 rounded-3xl border border-gray-100"><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{t('language', language)}</span><select className="bg-transparent text-sm font-bold outline-none dark:text-white cursor-pointer" value={language} onChange={(e) => setLanguage(e.target.value as Language)}><option value={Language.PT}>Português</option><option value={Language.EN}>English</option><option value={Language.FR}>Français</option></select></div>
              <div className="flex items-center justify-between p-5 bg-gray-50 dark:bg-gray-700 rounded-3xl border border-gray-100"><div className="flex flex-col"><span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{t('theme', language)}</span><span className="text-sm font-bold dark:text-white">{isDark ? 'Modo Escuro' : 'Modo Claro'}</span></div><button onClick={toggleTheme} className={`w-14 h-8 flex items-center rounded-full p-1 shadow-inner transition-all ${isDark ? 'bg-ev-blue' : 'bg-gray-300'}`}><div className={`bg-white w-6 h-6 rounded-full transform transition-all ${isDark ? 'translate-x-6' : 'translate-x-0'}`}></div></button></div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default Settings;

import React, { useState, useEffect, useContext } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';
import { LibraryItem, Language } from '../types';
import { storage } from '../services/storage';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const githubRawData: LibraryItem[] = [
  { id: 'g1', title: 'Plano Analítico - Educação Visual 2025', author: 'Secretaria', category: 'planos', date: '2025-01-10', description: 'Plano curricular para o primeiro semestre de 2025.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/planos/plano_2025.pdf' },
  { id: 'g2', title: 'Horário Semestral - Todos os Anos', author: 'Registo Académico', category: 'horarios', date: '2025-01-15', description: 'Horário completo das aulas teóricas e práticas.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/horarios/horario_geral.pdf' },
  { id: 'g3', title: 'A Teoria das Cores - Johannes Itten', author: 'Johannes Itten', category: 'livros', date: '2024-05-20', description: 'Livro fundamental para o estudo da cor e composição.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/livros/teoria_das_cores.pdf' },
  { id: 'g4', title: 'História da Arte Moçambicana', author: 'Vasco de Castro', category: 'livros', date: '2023-11-12', description: 'Compilação histórica sobre a evolução das artes em Moçambique.', downloadUrl: 'https://raw.githubusercontent.com/coragemdiua/ev-ul-repo/main/livros/historia_arte_moz.pdf' },
];

const Library: React.FC = () => {
  const { category } = useParams<{ category: string }>();
  const { language } = useContext(LanguageContext);
  const navigate = useNavigate();
  const [items, setItems] = useState<LibraryItem[]>([]);
  const [view, setView] = useState<'list' | 'add'>('list');
  const [searchTerm, setSearchTerm] = useState('');
  const [form, setForm] = useState({ title: '', author: '', description: '', file: '' });
  const [isUploading, setIsUploading] = useState(false);

  const currentUser = storage.getCurrentUserId();
  const categoryAllowsAdd = category === 'trabalhos' || category === 'materiais' || category === 'mono';

  useEffect(() => {
    const stored = storage.getLibraryItems();
    const combined = [...githubRawData, ...stored];
    setItems(combined.filter(item => item.category === category));
  }, [category]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => setForm({ ...form, file: event.target?.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleToggleView = () => {
    if (view === 'list') {
      if (!currentUser) { navigate('/login'); return; }
      setView('add');
    } else setView('list');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.file) { alert(t('select_file', language)); return; }
    setIsUploading(true);
    const newItem: LibraryItem = { id: 'l_' + Date.now(), title: form.title, author: form.author, category: category as any, date: new Date().toISOString().split('T')[0], description: form.description, downloadUrl: form.file };
    const stored = storage.getLibraryItems();
    const updated = [newItem, ...stored];
    storage.setLibraryItems(updated);
    setTimeout(() => { setItems(updated.filter(item => item.category === category)); setForm({ title: '', author: '', description: '', file: '' }); setIsUploading(false); setView('list'); }, 1500);
  };

  const getTitle = () => {
    switch (category) {
      case 'trabalhos': return t('scientific_works', language);
      case 'mono': return t('monographs', language);
      case 'planos': return t('analytical_plans', language);
      case 'horarios': return t('schedules', language);
      case 'livros': return t('books', language);
      case 'materiais': return t('academic_materials', language);
      default: return t('library', language);
    }
  };

  const filteredItems = items.filter(item => item.title.toLowerCase().includes(searchTerm.toLowerCase()) || item.author.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
      <header className="bg-ev-blue text-white px-4 py-3 flex items-center justify-between shadow-md z-50">
        <div className="flex items-center gap-4"><Link to="/" className="hover:scale-110 transition-transform"><i className="fas fa-arrow-left text-xl"></i></Link><h1 className="text-xl font-bold tracking-tight">{getTitle()}</h1></div>
        {categoryAllowsAdd && currentUser && (
          <button onClick={handleToggleView} className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm hover:scale-105 transition-transform">{view === 'list' ? t('add_file', language) : t('cancel', language)}</button>
        )}
        {categoryAllowsAdd && !currentUser && view === 'list' && (
           <button onClick={() => navigate('/login')} className="bg-white/10 text-white px-4 py-1.5 rounded-full text-xs font-black uppercase border border-white/20 hover:bg-white/20 transition-all">{t('login', language)} para Publicar</button>
        )}
      </header>

      <main className="max-w-6xl mx-auto w-full p-6 flex-1">
        {view === 'add' ? (
          <div className="max-w-2xl mx-auto bg-white dark:bg-gray-800 p-10 rounded-5xl shadow-xl border border-gray-100 animate-fadeIn">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase mb-8">{t('add_file', language)}</h2>
            <form onSubmit={handleSubmit} className="space-y-6">
