};

export default Home;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { UserPost, User, Language, Comment } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const UserPosts: React.FC = () => {
  const navigate = useNavigate();
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [posts, setPosts] = useState<UserPost[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [caption, setCaption] = useState('');
  const [mediaData, setMediaData] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<string>('');
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState('');
  const [activeCommentId, setActiveCommentId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const { language } = useContext(LanguageContext);

  useEffect(() => {
    const storedPosts = storage.getPosts();
    setPosts(storedPosts);
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');
    if (file) {
      if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
          window.URL.revokeObjectURL(video.src);
          if (video.duration > 30) {
            setError(language === Language.PT ? 'O vídeo não pode ter mais de 30 segundos.' : 'Video cannot be longer than 30 seconds.');
            setMediaData(null);
            return;
          }
          readFile(file);
        };
        video.src = URL.createObjectURL(file);
      } else {
        readFile(file);
      }
    }
  };

  const readFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setMediaData(event.target?.result as string);
      setMediaType(file.type);
    };
    reader.readAsDataURL(file);
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) { navigate('/login'); return; }
    if (!mediaData) return;
    setIsUploading(true);
    const newPost: UserPost = {
      id: 'post_' + Date.now(),
      userId: currentUser.id,
      userName: currentUser.name,
      userPhoto: currentUser.photo,
      caption: caption,
      media: mediaData,
      mediaType: mediaType,
      isImage: mediaType.startsWith('image/'),
      timestamp: new Date().toISOString(),
      likes: 0,
      likedBy: [],
      comments: []
    };
    const updated = [newPost, ...posts];
    setPosts(updated);
    storage.setPosts(updated);
    setTimeout(() => { 
      setCaption(''); 
      setMediaData(null); 
      setIsUploading(false); 
      setView('feed'); 
    }, 1000);
  };

  const handleLike = (postId: string) => {
    if (!currentUser) { navigate('/login'); return; }
    const updated = posts.map(post => {
      if (post.id === postId) {
        const hasLiked = post.likedBy.includes(currentUser.id);
        const newLikedBy = hasLiked ? post.likedBy.filter(id => id !== currentUser.id) : [...post.likedBy, currentUser.id];
        return { ...post, likedBy: newLikedBy, likes: newLikedBy.length };
      }
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
  };

  const handleAddComment = (postId: string) => {
    if (!currentUser) { navigate('/login'); return; }
    if (!commentText.trim()) return;
    const newComment: Comment = { authorName: currentUser.name, authorPhoto: currentUser.photo, text: commentText, timestamp: new Date().toISOString() };
    const updated = posts.map(post => {
      if (post.id === postId) return { ...post, comments: [...(post.comments || []), newComment] };
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
    setCommentText(''); setActiveCommentId(null);
  };

  return (
    <Layout 
      title={t('posts', language)} 
      backTo="/" 
      actions={
        currentUser ? (
          <button 
            onClick={() => setView(view === 'feed' ? 'publish' : 'feed')} 
            className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm"
          >
            {view === 'feed' ? t('publish', language) : t('view', language)}
          </button>
        ) : (
          <button 
            onClick={() => navigate('/login')}
            className="bg-white/10 text-white px-4 py-1.5 rounded-full text-xs font-black uppercase border border-white/20"
          >
            {t('login', language)}
          </button>
        )
      }
    >
      {fullScreenImage && (
        <div className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 animate-fadeIn backdrop-blur-sm" onClick={() => setFullScreenImage(null)}>
          <button className="absolute top-6 right-6 text-white text-3xl hover:scale-125 transition-transform"><i className="fas fa-times"></i></button>
          <img src={fullScreenImage} className="max-w-full max-h-[90vh] object-contain rounded-xl shadow-2xl animate-zoomIn border-4 border-ev-brown" alt="" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      <div className="max-w-2xl mx-auto pb-10">
        {view === 'publish' && currentUser ? (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-xl animate-fadeIn border border-gray-100 dark:border-gray-700">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase mb-8 tracking-tighter">{t('publish', language)}</h2>
            <form onSubmit={handlePublish} className="space-y-6">
              {error && <p className="bg-red-50 text-red-500 p-4 rounded-3xl text-xs font-bold text-center border border-red-100">{error}</p>}
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Legenda</label>
                <textarea className="w-full p-5 rounded-3xl bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none border-none" rows={3} placeholder="O que está a acontecer?" value={caption} onChange={(e) => setCaption(e.target.value)} />
              </div>
              <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-5xl p-12 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                <input type="file" accept="image/*,video/*" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" onChange={handleFileChange} />
                {mediaData ? (
                  <div className="space-y-4">
                    {mediaType.startsWith('image/') ? <img src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-lg" alt="" /> : <video src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-lg" />}
                    <p className="text-[10px] font-black text-ev-blue uppercase tracking-widest">Clique para trocar</p>
                  </div>
                ) : (
                  <div className="text-gray-400">
                    <i className="fas fa-photo-video text-4xl text-ev-blue mb-4"></i>
                    <p className="font-black uppercase tracking-widest text-xs">Selecione Mídia</p>
                    <p className="text-[10px] mt-2 italic font-bold">Imagem ou Vídeo (máx. 30s)</p>
                  </div>
                )}
              </div>
              <button type="submit" disabled={!mediaData || isUploading} className={`w-full py-5 rounded-3xl font-black shadow-xl uppercase transition-all tracking-widest ${!mediaData || isUploading ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-ev-blue text-white hover:bg-blue-600'}`}>
                {isUploading ? 'A publicar...' : t('publish', language)}
              </button>
            </form>
          </div>
        ) : (
          <div className="space-y-12">
            {posts.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-20 rounded-5xl shadow-sm text-center border border-dashed border-gray-200 dark:border-gray-700 animate-fadeIn">
                <div className="w-24 h-24 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center mx-auto mb-6">
                  <i className="fas fa-images text-4xl text-gray-300"></i>
                </div>
                <h3 className="text-xl font-black text-gray-400 uppercase tracking-widest">Feed Vazio</h3>
                <p className="text-sm text-gray-400 mt-2 italic">Partilhe o seu primeiro momento acadêmico!</p>
                {currentUser && <button onClick={() => setView('publish')} className="mt-6 text-ev-blue font-bold underline uppercase text-xs tracking-widest">Publicar Agora</button>}
              </div>
            ) : (
              posts.map((post, idx) => (
                <div key={post.id} className="bg-white dark:bg-gray-800 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                  <div className="p-6 flex items-center gap-4">
                    <img src={post.userPhoto} onClick={() => setFullScreenImage(post.userPhoto)} className="w-12 h-12 rounded-full object-cover border-2 border-ev-brown shadow-sm cursor-pointer hover:scale-105 transition-transform" alt="" />
                    <div><h4 className="font-black text-gray-800 dark:text-white uppercase tracking-tight leading-tight">{post.userName}</h4><p className="text-[10px] text-gray-400 font-bold uppercase">{new Date(post.timestamp).toLocaleDateString()}</p></div>
                  </div>
                  {post.caption && <div className="px-6 pb-4"><p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium">{post.caption}</p></div>}
                  <div className="bg-black/5 aspect-video flex items-center justify-center relative">{post.isImage ? <img src={post.media} onClick={() => setFullScreenImage(post.media)} className="w-full h-full object-contain cursor-pointer" alt="" /> : <video controls src={post.media} className="w-full h-full" />}</div>
                  <div className="p-6 space-y-4">
                    <div className="flex gap-8 border-b border-gray-50 dark:border-gray-700 pb-4">
                      <button onClick={() => handleLike(post.id)} className={`flex items-center gap-2 text-xs font-black uppercase transition-colors ${currentUser && post.likedBy?.includes(currentUser.id) ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}><i className={`${currentUser && post.likedBy?.includes(currentUser.id) ? 'fas' : 'far'} fa-heart text-xl`}></i> {post.likes} Adoros</button>
                      <button onClick={() => setActiveCommentId(activeCommentId === post.id ? null : post.id)} className="flex items-center gap-2 text-gray-400 text-xs font-black uppercase hover:text-ev-blue transition-colors"><i className="far fa-comment text-xl"></i> {post.comments?.length || 0} Comentários</button>
                    </div>
                    {post.comments?.map((comment, cidx) => (
                      <div key={cidx} className="flex gap-3 animate-fadeIn"><img src={comment.authorPhoto} onClick={() => setFullScreenImage(comment.authorPhoto)} className="w-8 h-8 rounded-full object-cover border-2 border-ev-brown cursor-pointer" alt="" /><div className="bg-gray-50 dark:bg-gray-700 p-3 rounded-2xl flex-1 shadow-inner"><p className="text-[9px] font-black text-ev-blue uppercase mb-1">{comment.authorName}</p><p className="text-xs text-gray-600 dark:text-gray-200">{comment.text}</p></div></div>
                    ))}
                    <div className="flex gap-3 pt-2">
                      <input 
                        type="text" 
                        placeholder={currentUser ? "Escreva um comentário..." : "Faça login para interagir"} 
                        readOnly={!currentUser} 
                        onClick={() => !currentUser && navigate('/login')} 
                        className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-5 py-3 text-xs dark:text-white shadow-inner focus:ring-1 focus:ring-ev-blue" 
                        value={activeCommentId === post.id ? commentText : ''} 
                        onChange={(e) => { if (currentUser) { setActiveCommentId(post.id); setCommentText(e.target.value); } }} 
                        onKeyDown={(e) => e.key === 'Enter' && handleAddComment(post.id)} 
                      />
                      <button onClick={() => handleAddComment(post.id)} className="bg-ev-blue text-white w-10 h-10 rounded-full flex items-center justify-center shadow-md active:scale-90"><i className="fas fa-paper-plane text-xs"></i></button>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default UserPosts;

import React, { useState, useEffect, useContext } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';
import { storage } from '../services/storage';
import { Publication, Language } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const ACCESS_KEY = '000000';

const Communities: React.FC = () => {
  const { tab } = useParams<{ tab: string }>();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<string>(tab || 'geral');
  const [publications, setPublications] = useState<Publication[]>([]);
  const [isAuth, setIsAuth] = useState(false);
  const [accessKeyInput, setAccessKeyInput] = useState('');
  const [loginError, setLoginError] = useState('');
  const [form, setForm] = useState({ title: '', category: 'geral', content: '' });
  const [successMsg, setSuccessMsg] = useState('');
  const { language } = useContext(LanguageContext);

  useEffect(() => {
    setPublications(storage.getPublications());
  }, []);

  useEffect(() => {
    if (tab && tab !== activeTab) {
      setActiveTab(tab);
      setLoginError('');
      setAccessKeyInput('');
    }
  }, [tab, activeTab]);

  const handleTabChange = (tabId: string) => {
    setActiveTab(tabId);
    navigate(`/communities/${tabId}`, { replace: true });
  };

  const handleLogin = () => {
    if (accessKeyInput === ACCESS_KEY) {
      setIsAuth(true);
      setLoginError('');
    } else {
      setLoginError(language === Language.PT ? 'Chave de acesso incorreta!' : 'Access key incorrect!');
    }
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    const newPub: Publication = {
      id: Date.now(),
      title: form.title,
      category: form.category,
      content: form.content,
      date: new Date().toISOString()
    };

    const updated = [newPub, ...publications];
    setPublications(updated);
    storage.setPublications(updated);
    setForm({ title: '', category: 'geral', content: '' });
    setSuccessMsg(language === Language.PT ? 'Informação publicada com sucesso!' : 'Information published successfully!');
    setTimeout(() => {
      setSuccessMsg('');
      handleTabChange(form.category);
    }, 1500);
  };

  const tabs = [
    { id: 'geral', label: 'Geral', icon: 'fa-info-circle' },
    { id: 'ano1', label: '1º Ano', icon: 'fa-user-graduate' },
    { id: 'ano2', label: '2º Ano', icon: 'fa-user-graduate' },
    { id: 'ano3', label: '3º Ano', icon: 'fa-user-graduate' },
    { id: 'ano4', label: '4º Ano', icon: 'fa-user-graduate' },
    { id: 'publicar', label: t('publish', language), icon: 'fa-plus-circle' },
  ];

  const filtered = publications.filter(pub => {
    if (activeTab === 'geral') return pub.category === 'geral';
    if (activeTab === 'publicar') return false;
    return pub.category === activeTab || pub.category === 'geral';
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-ev-dark">
      <header className="bg-ev-blue text-white px-4 py-3 flex items-center justify-between shadow-md z-50">
        <div className="flex items-center gap-4">
          <Link to="/" className="hover:scale-110 transition-transform">
            <i className="fas fa-arrow-left text-xl"></i>
          </Link>
          <h1 className="text-xl font-bold tracking-tight uppercase tracking-tighter">{t('communities', language)}</h1>
        </div>
      </header>

      <div className="bg-ev-blue shadow-lg border-t border-white/10 z-40 sticky top-[52px]">
        <div className="max-w-6xl mx-auto flex overflow-x-auto no-scrollbar">
          {tabs.map(tabItem => (
            <button
              key={tabItem.id}
              onClick={() => handleTabChange(tabItem.id)}
              className={`flex-shrink-0 flex flex-col items-center justify-center py-4 px-8 transition-all min-w-[100px] border-b-4 ${
                activeTab === tabItem.id ? 'bg-ev-brown border-white text-white' : 'text-white/60 border-transparent hover:bg-white/10'
              }`}
            >
              <i className={`fas ${tabItem.icon} mb-1 text-sm`}></i>
              <span className="text-[10px] font-black uppercase tracking-widest">{tabItem.label}</span>
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-4xl mx-auto w-full p-6 flex-1 py-10">
        {activeTab === 'publicar' ? (
          <div className="bg-white dark:bg-gray-800 p-8 md:p-12 rounded-4xl shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h2 className="text-3xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8 text-center">{t('publish', language)}</h2>

            {!isAuth ? (
              <div className="max-w-sm mx-auto space-y-6 text-center py-6">
                <div className="w-20 h-20 bg-ev-blue/10 rounded-full flex items-center justify-center text-ev-blue mx-auto mb-4 border-2 border-ev-brown">
                  <i className="fas fa-lock text-3xl"></i>
                </div>
                <div className="space-y-2">
                  <p className="text-gray-800 dark:text-white font-bold uppercase text-xs tracking-widest">Acesso Restrito</p>
                  <p className="text-gray-500 text-xs leading-relaxed">Apenas delegados e docentes podem emitir comunicados oficiais.</p>
                </div>
                {loginError && <p className="text-red-500 text-[10px] font-black uppercase bg-red-50 p-3 rounded-2xl border border-red-100">{loginError}</p>}
                <input
                  type="password"
                  placeholder="DIGITE A CHAVE"
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-center text-lg font-black tracking-[0.4em] shadow-inner focus:ring-2 focus:ring-ev-blue"
                  value={accessKeyInput}
                  onChange={(e) => setAccessKeyInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
                />
                <button 
                  onClick={handleLogin}
                  className="w-full bg-ev-blue text-white py-4 rounded-3xl font-black shadow-lg hover:bg-blue-600 transition-all uppercase tracking-widest text-xs"
                >
                  Verificar Acesso
                </button>
              </div>
            ) : (
              <form onSubmit={handlePublish} className="space-y-6">
                {successMsg && <div className="bg-green-100 text-green-700 p-4 rounded-3xl font-black text-center animate-bounce uppercase text-xs tracking-widest shadow-sm">{successMsg}</div>}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Título do Comunicado</label>
                    <input
                      type="text"
                      required
                      placeholder="Ex: Entrega de Notas"
                      className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue font-bold"
                      value={form.title}
                      onChange={(e) => setForm({ ...form, title: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Canal de Destino</label>
                    <select
                      className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue appearance-none cursor-pointer font-bold uppercase text-xs tracking-widest"
                      value={form.category}
                      onChange={(e) => setForm({ ...form, category: e.target.value })}
                    >
                      <option value="geral">Todos os Anos (Geral)</option>
                      <option value="ano1">Estudantes do 1º Ano</option>
                      <option value="ano2">Estudantes do 2º Ano</option>
                      <option value="ano3">Estudantes do 3º Ano</option>
                      <option value="ano4">Estudantes do 4º Ano</option>
                    </select>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Conteúdo da Informação</label>
                  <textarea
                    required
                    rows={6}
                    placeholder="Escreva os detalhes aqui..."
                    className="w-full p-5 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none font-medium text-sm"
                    value={form.content}
                    onChange={(e) => setForm({ ...form, content: e.target.value })}
                  ></textarea>
                </div>
                <div className="flex flex-col md:flex-row gap-4 pt-4">
                  <button type="submit" className="flex-1 bg-ev-blue text-white py-5 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-[0.2em] text-xs">
                    <i className="fas fa-bullhorn mr-2"></i> Emitir Aviso
                  </button>
                  <button 
                    type="button"
                    onClick={() => setIsAuth(false)}
                    className="px-8 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 rounded-3xl font-black uppercase text-[10px] tracking-widest hover:text-red-500 transition-colors"
                  >
                    Encerrar Sessão
                  </button>
                </div>
              </form>
            )}
          </div>
        ) : (
          <div className="space-y-6">
            {filtered.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-20 rounded-5xl shadow-sm text-center text-gray-300 border border-dashed border-gray-200 dark:border-gray-700 animate-fadeIn">
                <i className="fas fa-bullhorn text-6xl mb-6 opacity-20"></i>
                <p className="text-lg font-black uppercase tracking-widest text-gray-400">Sem comunicados recentes</p>
                <p className="text-xs mt-2 italic">As informações oficiais para esta comunidade aparecerão aqui.</p>
              </div>
            ) : (
              filtered.map((pub, idx) => (
                <div key={pub.id} className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-sm border-l-[8px] border-ev-blue hover:shadow-lg transition-all border-gray-100 dark:border-gray-700 animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                  <div className="flex justify-between items-start mb-5">
                    <h3 className="text-xl font-black text-gray-800 dark:text-white leading-tight uppercase tracking-tight">{pub.title}</h3>
                    <span className="text-[9px] font-black text-gray-400 bg-gray-50 dark:bg-gray-700 px-4 py-2 rounded-full uppercase tracking-[0.2em] shadow-inner">
                      {new Date(pub.date).toLocaleDateString()}
                    </span>
                  </div>
                  <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-sm whitespace-pre-wrap font-medium">{pub.content}</p>
                  <div className="mt-8 flex items-center justify-between pt-4 border-t border-gray-50 dark:border-gray-700">
                    <div className="flex items-center gap-2">
                      <div className="w-7 h-7 bg-ev-blue/10 rounded-full flex items-center justify-center text-[10px] text-ev-blue border border-ev-blue/20">
                        <i className="fas fa-tag"></i>
                      </div>
                      <span className="text-[9px] font-black text-ev-blue dark:text-ev-text-light uppercase tracking-[0.2em]">
                        {pub.category === 'geral' ? 'Canal Geral' : `Canal: ${pub.category.replace('ano', '')}º Ano`}
                      </span>
                    </div>
                    <div className="text-[10px] font-black text-gray-300 uppercase tracking-widest italic">EV-UL Oficial</div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default Communities;

-- 1. EXTENÇÕES PARA UUID
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. TABELAS PRINCIPAIS

-- Perfis de Usuários (Vínculo com Auth.Users do Supabase)
CREATE TABLE profiles (
  id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  name TEXT NOT NULL,
  student_number TEXT UNIQUE NOT NULL,
  photo_url TEXT,
  academic_year INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Publicações Oficiais (Comunidades)
CREATE TABLE publications (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'geral', -- geral, ano1, ano2, ano3, ano4
  content TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Biblioteca Digital (Repositório)
CREATE TABLE library_items (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  category TEXT NOT NULL, -- trabalhos, mono, planos, horarios, livros, materiais
  description TEXT,
  download_url TEXT NOT NULL,
  user_id UUID REFERENCES profiles(id),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Posts de Usuários (Feed Social)
CREATE TABLE posts (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
  caption TEXT,
  media_url TEXT NOT NULL,
  media_type TEXT NOT NULL,
  is_image BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Comentários nos Posts
CREATE TABLE post_comments (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  post_id UUID REFERENCES posts(id) ON DELETE CASCADE,
  user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
  text TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Adoros (Likes)
CREATE TABLE post_likes (
  post_id UUID REFERENCES posts(id) ON DELETE CASCADE,
  user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, user_id)
);

-- Mensagens do Chat
CREATE TABLE messages (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  sender_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
  recipient_id UUID REFERENCES profiles(id) ON DELETE CASCADE, -- NULL para chat geral
  is_general_chat BOOLEAN DEFAULT FALSE,
  text TEXT,
  media_url TEXT,
  media_type TEXT,
  file_name TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. SEGURANÇA (RLS - Row Level Security)

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE publications ENABLE ROW LEVEL SECURITY;
ALTER TABLE library_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE post_comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE post_likes ENABLE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;

-- Políticas para Perfis
CREATE POLICY "Perfis visíveis para todos" ON profiles FOR SELECT USING (true);
CREATE POLICY "Usuários editam próprio perfil" ON profiles FOR UPDATE USING (auth.uid() = id);

-- Políticas para Publicações (Comunicados)
CREATE POLICY "Comunicados visíveis para todos" ON publications FOR SELECT USING (true);
CREATE POLICY "Apenas master key (via service role ou trigger) insere" ON publications FOR INSERT WITH CHECK (true);

-- Políticas para Biblioteca
CREATE POLICY "Biblioteca visível para todos" ON library_items FOR SELECT USING (true);
CREATE POLICY "Usuários logados podem subir materiais" ON library_items FOR INSERT WITH CHECK (auth.role() = 'authenticated');

-- Políticas para Posts e Social
CREATE POLICY "Posts visíveis para todos" ON posts FOR SELECT USING (true);
CREATE POLICY "Logados podem postar" ON posts FOR INSERT WITH CHECK (auth.role() = 'authenticated');
CREATE POLICY "Dono apaga próprio post" ON posts FOR DELETE USING (auth.uid() = user_id);

CREATE POLICY "Comentários visíveis para todos" ON post_comments FOR SELECT USING (true);
CREATE POLICY "Logados podem comentar" ON post_comments FOR INSERT WITH CHECK (auth.role() = 'authenticated');

-- Políticas para Chat
CREATE POLICY "Todos vêem chat geral" ON messages FOR SELECT USING (is_general_chat = true);
CREATE POLICY "Mensagens privadas apenas para envolvidos" ON messages FOR SELECT USING (auth.uid() = sender_id OR auth.uid() = recipient_id);
CREATE POLICY "Logados podem enviar mensagens" ON messages FOR INSERT WITH CHECK (auth.role() = 'authenticated');

-- 4. TRIGGER PARA NOVO USUÁRIO
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger AS $$
BEGIN
  INSERT INTO public.profiles (id, name, student_number, academic_year)
  VALUES (new.id, new.raw_user_meta_data->>'name', new.raw_user_meta_data->>'student_number', (new.raw_user_meta_data->>'academic_year')::integer);
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

import React, { useState, useEffect, useContext, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { UserPost, User, Language, Comment } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const UserPosts: React.FC = () => {
  const navigate = useNavigate();
  const [view, setView] = useState<'feed' | 'publish'>('feed');
  const [posts, setPosts] = useState<UserPost[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [caption, setCaption] = useState('');
  const [mediaData, setMediaData] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<string>('');
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState('');
  const [activeCommentId, setActiveCommentId] = useState<string | null>(null);
  const [commentText, setCommentText] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const { language } = useContext(LanguageContext);

  useEffect(() => {
    // Carregar posts e garantir que seja sempre um array
    const storedPosts = storage.getPosts() || [];
    setPosts(storedPosts);
    setCurrentUser(storage.getCurrentUser());
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError('');
    if (file) {
      if (file.type.startsWith('video/')) {
        const video = document.createElement('video');
        video.preload = 'metadata';
        video.onloadedmetadata = () => {
          window.URL.revokeObjectURL(video.src);
          if (video.duration > 30) {
            setError(language === Language.PT ? 'O vídeo não pode ter mais de 30 segundos.' : 'Video cannot be longer than 30 seconds.');
            setMediaData(null);
            return;
          }
          readFile(file);
        };
        video.src = URL.createObjectURL(file);
      } else {
        readFile(file);
      }
    }
  };

  const readFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      setMediaData(event.target?.result as string);
      setMediaType(file.type);
    };
    reader.readAsDataURL(file);
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) { navigate('/login'); return; }
    if (!mediaData) {
      setError(language === Language.PT ? 'Por favor, selecione uma imagem ou vídeo.' : 'Please select an image or video.');
      return;
    }

    setIsUploading(true);
    const newPost: UserPost = {
      id: 'post_' + Date.now(),
      userId: currentUser.id,
      userName: currentUser.name,
      userPhoto: currentUser.photo,
      caption: caption,
      media: mediaData,
      mediaType: mediaType,
      isImage: mediaType.startsWith('image/'),
      timestamp: new Date().toISOString(),
      likes: 0,
      likedBy: [],
      comments: []
    };

    const updated = [newPost, ...posts];
    setPosts(updated);
    storage.setPosts(updated);

    setTimeout(() => { 
      setCaption(''); 
      setMediaData(null); 
      setIsUploading(false); 
      setView('feed'); 
    }, 1000);
  };

  const handleLike = (postId: string) => {
    if (!currentUser) { navigate('/login'); return; }
    const updated = posts.map(post => {
      if (post.id === postId) {
        const hasLiked = post.likedBy?.includes(currentUser.id) || false;
        const newLikedBy = hasLiked 
          ? post.likedBy.filter(id => id !== currentUser.id) 
          : [...(post.likedBy || []), currentUser.id];
        return { ...post, likedBy: newLikedBy, likes: newLikedBy.length };
      }
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
  };

  const handleAddComment = (postId: string) => {
    if (!currentUser) { navigate('/login'); return; }
    if (!commentText.trim()) return;
    const newComment: Comment = { 
      authorName: currentUser.name, 
      authorPhoto: currentUser.photo, 
      text: commentText, 
      timestamp: new Date().toISOString() 
    };
    const updated = posts.map(post => {
      if (post.id === postId) return { ...post, comments: [...(post.comments || []), newComment] };
      return post;
    });
    setPosts(updated);
    storage.setPosts(updated);
    setCommentText(''); setActiveCommentId(null);
  };

  return (
    <Layout 
      title={t('posts', language)} 
      backTo="/" 
      actions={
        currentUser ? (
          <button 
            onClick={() => {
              setError('');
              setView(view === 'feed' ? 'publish' : 'feed');
            }} 
            className="bg-white text-ev-blue px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-sm hover:scale-105 transition-transform"
          >
            {view === 'feed' ? t('publish', language) : t('view', language)}
          </button>
        ) : (
          <button 
            onClick={() => navigate('/login')}
            className="bg-white/10 text-white px-4 py-1.5 rounded-full text-xs font-black uppercase border border-white/20 hover:bg-white/20 transition-all"
          >
            {t('login', language)} para Publicar
          </button>
        )
      }
    >
      {fullScreenImage && (
        <div className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 animate-fadeIn backdrop-blur-sm" onClick={() => setFullScreenImage(null)}>
          <button className="absolute top-6 right-6 text-white text-3xl hover:scale-125 transition-transform"><i className="fas fa-times"></i></button>
          <img src={fullScreenImage} className="max-w-full max-h-[90vh] object-contain rounded-xl shadow-2xl animate-zoomIn border-4 border-ev-brown" alt="" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      <div className="max-w-2xl mx-auto pb-10">
        {view === 'publish' && currentUser ? (
          <div className="bg-white dark:bg-gray-800 p-8 rounded-4xl shadow-xl animate-fadeIn border border-gray-100 dark:border-gray-700">
            <h2 className="text-2xl font-black text-ev-blue dark:text-white uppercase mb-8 tracking-tighter">{t('publish', language)}</h2>
            <form onSubmit={handlePublish} className="space-y-6">
              {error && <p className="bg-red-50 text-red-500 p-4 rounded-3xl text-xs font-bold text-center border border-red-100 animate-bounce">{error}</p>}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Legenda da Publicação</label>
                <textarea className="w-full p-5 rounded-3xl bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue resize-none border-none outline-none font-medium" rows={3} placeholder="O que está a acontecer no curso?" value={caption} onChange={(e) => setCaption(e.target.value)} />
              </div>

              <div className="relative border-2 border-dashed border-gray-200 dark:border-gray-600 rounded-5xl p-12 text-center hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors group">
                <input type="file" accept="image/*,video/*" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" onChange={handleFileChange} />
                {mediaData ? (
                  <div className="space-y-4">
                    {mediaType.startsWith('image/') ? <img src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-lg border-2 border-ev-brown" alt="" /> : <video src={mediaData} className="max-h-80 mx-auto rounded-3xl shadow-lg border-2 border-ev-brown" />}
                    <p className="text-[10px] font-black text-ev-blue uppercase tracking-widest">Toque para alterar o ficheiro</p>
                  </div>
                ) : (
                  <div className="text-gray-400">
                    <div className="w-20 h-20 bg-blue-50 dark:bg-blue-900/20 rounded-3xl flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                      <i className="fas fa-camera-retro text-4xl text-ev-blue"></i>
                    </div>
                    <p className="font-black uppercase tracking-widest text-xs">Adicionar Mídia</p>
                    <p className="text-[10px] mt-2 italic font-bold">Foto ou Vídeo de até 30s</p>
                  </div>
                )}
              </div>

              <button type="submit" disabled={!mediaData || isUploading} className={`w-full py-5 rounded-3xl font-black shadow-xl uppercase transition-all tracking-widest text-sm flex items-center justify-center gap-3 ${!mediaData || isUploading ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-ev-blue text-white hover:bg-blue-600 active:scale-95'}`}>
                {isUploading ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                  <><i className="fas fa-paper-plane"></i> {t('publish', language)}</>
                )}
              </button>
            </form>
          </div>
        ) : (
          <div className="space-y-12">
            {posts.length === 0 ? (
              <div className="bg-white dark:bg-gray-800 p-20 rounded-5xl shadow-sm text-center border border-dashed border-gray-200 dark:border-gray-700 animate-fadeIn">
                <div className="w-24 h-24 bg-gray-50 dark:bg-gray-700 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-200">
                  <i className="fas fa-images text-5xl"></i>
                </div>
                <h3 className="text-xl font-black text-gray-400 uppercase tracking-widest">Feed de Notícias Vazio</h3>
                <p className="text-sm text-gray-400 mt-2 italic">Ainda não existem publicações. Seja o primeiro!</p>
                {currentUser ? (
                  <button onClick={() => setView('publish')} className="mt-8 bg-ev-blue text-white px-8 py-3 rounded-full font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-blue-600 transition-all active:scale-95">Publicar Agora</button>
                ) : (
                  <button onClick={() => navigate('/login')} className="mt-8 bg-ev-brown text-white px-8 py-3 rounded-full font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-[#5a331a] transition-all active:scale-95">Fazer Login</button>
                )}
              </div>
            ) : (
              posts.map((post, idx) => (
                <div key={post.id} className="bg-white dark:bg-gray-800 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden animate-fadeIn" style={{ animationDelay: `${idx * 0.1}s` }}>
                  <div className="p-6 flex items-center gap-4">
                    <img src={post.userPhoto} onClick={() => setFullScreenImage(post.userPhoto)} className="w-12 h-12 rounded-full object-cover border-2 border-ev-brown shadow-sm cursor-pointer hover:scale-105 transition-transform" alt="" />
                    <div><h4 className="font-black text-gray-800 dark:text-white uppercase tracking-tight leading-tight">{post.userName}</h4><p className="text-[10px] text-gray-400 font-bold uppercase">{new Date(post.timestamp).toLocaleDateString()}</p></div>
                  </div>
                  {post.caption && <div className="px-6 pb-4"><p className="text-sm text-gray-600 dark:text-gray-300 leading-relaxed font-medium">{post.caption}</p></div>}
                  <div className="bg-black aspect-video flex items-center justify-center relative">
                    {post.isImage ? <img src={post.media} onClick={() => setFullScreenImage(post.media)} className="w-full h-full object-contain cursor-pointer hover:opacity-90 transition-opacity" alt="" /> : <video controls src={post.media} className="w-full h-full" />}
                  </div>
                  <div className="p-6 space-y-4">
                    <div className="flex gap-8 border-b border-gray-50 dark:border-gray-700 pb-4">
                      <button onClick={() => handleLike(post.id)} className={`flex items-center gap-2 text-xs font-black uppercase transition-colors ${currentUser && post.likedBy?.includes(currentUser.id) ? 'text-red-500' : 'text-gray-400 hover:text-red-500'}`}><i className={`${currentUser && post.likedBy?.includes(currentUser.id) ? 'fas' : 'far'} fa-heart text-xl`}></i> {(post.likes || 0)} Adoros</button>
                      <button onClick={() => setActiveCommentId(activeCommentId === post.id ? null : post.id)} className="flex items-center gap-2 text-gray-400 text-xs font-black uppercase hover:text-ev-blue transition-colors"><i className="far fa-comment text-xl"></i> {(post.comments?.length || 0)} Comentários</button>
                    </div>
                    {post.comments && post.comments.length > 0 && (
                      <div className="space-y-4 max-h-60 overflow-y-auto no-scrollbar pr-2">
                        {post.comments.map((comment, cidx) => (
                          <div key={cidx} className="flex gap-3 animate-fadeIn">
                            <img src={comment.authorPhoto} onClick={() => setFullScreenImage(comment.authorPhoto)} className="w-9 h-9 rounded-full object-cover border-2 border-ev-brown flex-shrink-0 cursor-pointer" alt="" />
                            <div className="bg-gray-50 dark:bg-gray-700 p-4 rounded-3xl flex-1 shadow-inner">
                              <p className="text-[9px] font-black text-ev-blue uppercase mb-1 tracking-tighter">{comment.authorName}</p>
                              <p className="text-xs text-gray-600 dark:text-gray-200 leading-relaxed">{comment.text}</p>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                    <div className="flex gap-3 pt-2">
                      <input 
                        type="text" 
                        placeholder={currentUser ? "Dê a sua opinião..." : "Faça login para interagir"} 
                        readOnly={!currentUser} 
                        onClick={() => !currentUser && navigate('/login')} 
                        className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-6 py-4 text-xs dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue" 
                        value={activeCommentId === post.id ? commentText : ''} 
                        onChange={(e) => { if (currentUser) { setActiveCommentId(post.id); setCommentText(e.target.value); } }} 
                        onKeyDown={(e) => e.key === 'Enter' && handleAddComment(post.id)} 
                      />
                      <button onClick={() => handleAddComment(post.id)} disabled={!commentText.trim()} className={`bg-ev-blue text-white w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all active:scale-90 ${!commentText.trim() ? 'opacity-50' : 'hover:bg-blue-600'}`}>
                        <i className="fas fa-paper-plane text-xs"></i>
                      </button>
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </Layout>
  );
};

export default UserPosts;

import { User, Message, Publication, Artwork, Theme, Language, LibraryItem, UserPost } from '../types';

const USERS_KEY = 'ev_ul_users';
const CURRENT_USER_ID_KEY = 'ev_ul_current_id';
const MESSAGES_KEY = 'ev_ul_messages';
const PUBLICATIONS_KEY = 'ev_ul_publications';
const ARTWORKS_KEY = 'ev_ul_artworks';
const POSTS_KEY = 'ev_ul_user_posts';
const LIBRARY_ITEMS_KEY = 'ev_ul_library_items';
const THEME_KEY = 'ev_ul_theme';
const LANG_KEY = 'ev_ul_lang';
const LAST_VIEWED_CHAT = 'ev_ul_last_chat_view';
const LAST_VIEWED_PUBS = 'ev_ul_last_pubs_view';

export const storage = {
  getUsers: (): User[] => JSON.parse(localStorage.getItem(USERS_KEY) || '[]'),
  setUsers: (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users)),

  getCurrentUserId: (): string | null => localStorage.getItem(CURRENT_USER_ID_KEY),
  setCurrentUserId: (id: string | null) => {
    if (id) localStorage.setItem(CURRENT_USER_ID_KEY, id);
    else localStorage.removeItem(CURRENT_USER_ID_KEY);
  },

  getMessages: (): Message[] => JSON.parse(localStorage.getItem(MESSAGES_KEY) || '[]'),
  setMessages: (messages: Message[]) => localStorage.setItem(MESSAGES_KEY, JSON.stringify(messages)),

  getPublications: (): Publication[] => JSON.parse(localStorage.getItem(PUBLICATIONS_KEY) || '[]'),
  setPublications: (pubs: Publication[]) => localStorage.setItem(PUBLICATIONS_KEY, JSON.stringify(pubs)),

  getArtworks: (): Artwork[] => JSON.parse(localStorage.getItem(ARTWORKS_KEY) || '[]'),
  setArtworks: (art: Artwork[]) => localStorage.setItem(ARTWORKS_KEY, JSON.stringify(art)),

  getPosts: (): UserPost[] => JSON.parse(localStorage.getItem(POSTS_KEY) || '[]'),
  setPosts: (posts: UserPost[]) => localStorage.setItem(POSTS_KEY, JSON.stringify(posts)),

  getLibraryItems: (): LibraryItem[] => JSON.parse(localStorage.getItem(LIBRARY_ITEMS_KEY) || '[]'),
  setLibraryItems: (items: LibraryItem[]) => localStorage.setItem(LIBRARY_ITEMS_KEY, JSON.stringify(items)),

  getTheme: (): Theme => (localStorage.getItem(THEME_KEY) as Theme) || Theme.LIGHT,
  setTheme: (theme: Theme) => localStorage.setItem(THEME_KEY, theme),

  getLanguage: (): Language => (localStorage.getItem(LANG_KEY) as Language) || Language.PT,
  setLanguage: (lang: Language) => localStorage.setItem(LANG_KEY, lang),

  getLastViewedChat: (): number => parseInt(localStorage.getItem(LAST_VIEWED_CHAT) || '0'),
  setLastViewedChat: () => localStorage.setItem(LAST_VIEWED_CHAT, Date.now().toString()),

  getLastViewedPubs: (): number => parseInt(localStorage.getItem(LAST_VIEWED_PUBS) || '0'),
  setLastViewedPubs: () => localStorage.setItem(LAST_VIEWED_PUBS, Date.now().toString()),

  getCurrentUser: (): User | null => {
    const id = storage.getCurrentUserId();
    if (!id) return null;
    return storage.getUsers().find(u => u.id === id) || null;
  },

  logout: () => {
    storage.setCurrentUserId(null);
  }
};

