import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  const usersWithStatus = useMemo(() => {
    return storage.getUsers().map(u => ({
      ...u,
      isOnline: u.id === currentUser?.id ? true : Math.random() > 0.4,
      lastSeen: u.id === currentUser?.id ? 'Agora' : 'Há ' + Math.floor(Math.random() * 59) + ' min'
    }));
  }, [currentUser?.id]);

  useEffect(() => {
    setMessages(storage.getMessages());
    storage.setLastViewedChat(); // Marcar mensagens como vistas
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  useEffect(() => {
    const handlePopState = () => {
      if (selectedUser) {
        setSelectedUser(null);
        window.history.pushState(null, '', window.location.href);
      }
    };
    if (selectedUser) {
      window.history.pushState(null, '', window.location.href);
      window.addEventListener('popstate', handlePopState);
    }
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;
    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };
    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
    storage.setLastViewedChat(); // Atualizar visto ao enviar
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else processFile(file);
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({ media: event.target?.result as string, mediaType: file.type, fileName: file.name });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => saveMessage({ media: e.target?.result as string, mediaType: 'audio/webm', fileName: `record_${Date.now()}.webm` });
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };
      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch { alert('Não foi possível acessar o microfone.'); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media; link.download = fileName;
    document.body.appendChild(link); link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) || (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => authorId === currentUser?.id ? 'Você' : usersWithStatus.find(u => u.id === authorId)?.name || 'Usuário';
  const getAuthorPhoto = (authorId: string) => usersWithStatus.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';

  return (
    <Layout title={selectedUser ? (selectedUser === 'general' ? 'Chat Geral' : selectedUser.name) : "Mensagens"} backTo="/" showBackButton={true} onBack={() => selectedUser ? setSelectedUser(null) : navigate('/')}>
      {fullScreenImage && (
        <div className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-4 animate-fadeIn" onClick={() => setFullScreenImage(null)}>
          <button className="absolute top-6 right-6 text-white text-2xl hover:scale-110 transition-transform"><i className="fas fa-times"></i></button>
          <img src={fullScreenImage} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoomIn" alt="Full screen" onClick={(e) => e.stopPropagation()} />
        </div>
      )}

      {selectedUser ? (
        <div className="flex flex-col h-[calc(100vh-140px)] bg-white dark:bg-gray-900 rounded-4xl overflow-hidden shadow-xl border border-gray-100 dark:border-gray-800 relative">
          <div className="bg-gray-50 dark:bg-gray-800/50 p-4 border-b border-gray-100 dark:border-gray-800 flex items-center gap-3">
            <div className="relative">
              <img 
                src={selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo} 
                onClick={() => setFullScreenImage(selectedUser === 'general' ? 'https://picsum.photos/seed/general/200' : selectedUser.photo)}
                className="w-10 h-10 rounded-full object-cover shadow-sm border-2 border-ev-brown cursor-pointer hover:scale-105 transition-transform" 
                alt="" 
              />
              {(selectedUser === 'general' || selectedUser.isOnline) && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full shadow-sm"></div>}
            </div>
            <div>
              <h3 className="font-black text-gray-800 dark:text-gray-100 leading-tight tracking-tight">{selectedUser === 'general' ? 'Chat Geral' : selectedUser.name}</h3>
              <p className={`text-[10px] font-black uppercase tracking-widest ${selectedUser === 'general' || selectedUser.isOnline ? 'text-green-500' : 'text-gray-400'}`}>
                {selectedUser === 'general' ? 'Online' : (selectedUser.isOnline ? 'Online' : 'Visto ' + selectedUser.lastSeen)}
              </p>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar bg-gray-50/30 dark:bg-gray-900/30">
            {filteredMessages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40"><i className="fas fa-comments text-6xl mb-4 text-gray-200"></i><p className="font-black uppercase tracking-widest text-[10px]">Inicie uma conversa</p></div>
            ) : (
              filteredMessages.map((msg, idx) => {
                const isMine = msg.authorId === currentUser?.id;
                return (
                  <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                    <div className={`flex gap-2 max-w-[85%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                      {!isMine && <img src={getAuthorPhoto(msg.authorId)} onClick={() => setFullScreenImage(getAuthorPhoto(msg.authorId))} className="w-8 h-8 rounded-full flex-shrink-0 mt-1 shadow-sm cursor-pointer hover:scale-110 transition-transform border-2 border-ev-brown" alt="" />}
                      <div className="flex flex-col">
                        {selectedUser === 'general' && !isMine && <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>}
                        <div className={`p-3.5 rounded-3xl text-sm shadow-sm relative group ${isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-100 dark:border-gray-700'}`}>
                          {msg.text && <p className="leading-relaxed font-medium">{msg.text}</p>}
                          {msg.media && (
                            <div className="mt-2 space-y-2">
                              {msg.mediaType?.startsWith('image/') ? <img src={msg.media} onClick={() => setFullScreenImage(msg.media!)} className="max-w-full rounded-2xl shadow-md cursor-pointer hover:opacity-90" alt="" /> : msg.mediaType?.startsWith('video/') ? <video src={msg.media} controls className="max-w-full rounded-2xl shadow-md" /> : msg.mediaType?.startsWith('audio/') ? <audio src={msg.media} controls className="max-w-full h-10" /> : null}
                              <button onClick={() => downloadMedia(msg.media!, msg.fileName || 'anexo')} className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-all ${isMine ? 'bg-white/20 hover:bg-white/40 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'}`}><i className="fas fa-download"></i> Baixar Mídia</button>
                            </div>
                          )}
                          <p className="text-[9px] mt-1.5 text-right font-black uppercase tracking-widest opacity-60">{new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={messagesEndRef} />
          </div>

          {showMediaMenu && (
            <div className="absolute bottom-20 left-4 right-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-2xl border border-gray-100 dark:border-gray-700 grid grid-cols-2 gap-4 animate-slideUp z-50">
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm"><i className="fas fa-image text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Galeria</span><input type="file" accept="image/*" className="hidden" onChange={(e) => handleFileUpload(e, 'image')} /></label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm"><i className="fas fa-video text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Vídeo 30s</span><input type="file" accept="video/*" className="hidden" onChange={(e) => handleFileUpload(e, 'video')} /></label>
              <label className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl cursor-pointer hover:bg-ev-blue hover:text-white transition-all shadow-sm"><i className="fas fa-file-audio text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Arquivo Áudio</span><input type="file" accept="audio/*" className="hidden" onChange={(e) => handleFileUpload(e, 'audio')} /></label>
              <button onClick={startRecording} className="flex flex-col items-center gap-2 p-4 bg-gray-50 dark:bg-gray-700 rounded-3xl hover:bg-red-500 hover:text-white transition-all shadow-sm"><i className="fas fa-microphone text-2xl"></i><span className="text-[10px] font-black uppercase tracking-widest">Gravar Voz</span></button>
            </div>
          )}

          <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-800">
            {isRecording ? (
              <div className="flex items-center justify-between gap-4 bg-red-50 dark:bg-red-900/20 p-3.5 rounded-3xl border border-red-100"><div className="flex items-center gap-3"><div className="w-3.5 h-3.5 bg-red-500 rounded-full animate-ping"></div><span className="text-xs font-black text-red-600 uppercase tracking-widest">Gravando: {Math.floor(recordingTime / 60)}:{(recordingTime % 60).toString().padStart(2, '0')}</span></div><button onClick={stopRecording} className="bg-red-500 text-white px-6 py-2.5 rounded-full font-black uppercase text-[10px] tracking-[0.2em] shadow-lg">Finalizar</button></div>
            ) : (
              <div className="flex gap-3"><button onClick={() => setShowMediaMenu(!showMediaMenu)} className={`w-12 h-12 flex items-center justify-center rounded-full transition-all shadow-md ${showMediaMenu ? 'bg-ev-brown text-white rotate-45' : 'bg-gray-100 text-gray-500 dark:bg-gray-700'}`}><i className="fas fa-plus"></i></button><input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Escreva sua mensagem..." className="flex-1 bg-gray-50 dark:bg-gray-700 border-none rounded-full px-6 py-3 text-sm focus:ring-2 focus:ring-ev-blue shadow-inner dark:text-white font-medium"/><button onClick={handleSend} disabled={!inputText.trim()} className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-all ${!inputText.trim() ? 'bg-gray-200 text-gray-400 cursor-not-allowed dark:bg-gray-800' : 'bg-ev-blue text-white hover:bg-blue-600'}`}><i className="fas fa-paper-plane"></i></button></div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div onClick={() => setSelectedUser('general')} className="flex items-center gap-4 bg-white dark:bg-gray-800 p-5 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all hover:scale-[1.02] animate-fadeIn">
            <div className="relative"><div className="w-14 h-14 bg-ev-blue rounded-full flex items-center justify-center text-white shadow-inner cursor-pointer border-2 border-ev-brown" onClick={(e) => { e.stopPropagation(); setFullScreenImage('https://picsum.photos/seed/general/200'); }}><i className="fas fa-users text-2xl"></i></div><div className="absolute bottom-0.5 right-0.5 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full shadow-sm animate-pulse"></div></div>
            <div className="flex-1"><h3 className="font-black dark:text-white uppercase tracking-tight">Chat Geral</h3><p className="text-[10px] text-green-500 font-black uppercase tracking-[0.2em] mt-0.5">Disponível Agora</p></div>
          </div>
          <div className="mt-10 mb-4 ml-4"><h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Meus Contatos</h4></div>
          <div className="space-y-3">
            {usersWithStatus.filter(u => u.id !== currentUser?.id).map((user, idx) => (
              <div key={user.id} onClick={() => setSelectedUser(user)} className="flex items-center gap-4 bg-white dark:bg-gray-800 p-4 rounded-4xl shadow-sm border border-gray-100 dark:border-gray-700 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-all hover:scale-[1.01] animate-fadeIn" style={{ animationDelay: `${idx * 0.05}s` }}>
                <div className="relative"><img src={user.photo} onClick={(e) => { e.stopPropagation(); setFullScreenImage(user.photo); }} className="w-14 h-14 rounded-full object-cover border-2 border-ev-brown shadow-sm cursor-pointer hover:scale-105 transition-transform" alt="" />{user.isOnline && <div className="absolute bottom-0.5 right-0.5 w-4 h-4 bg-green-500 border-2 border-white dark:border-gray-800 rounded-full shadow-sm"></div>}</div>
                <div className="flex-1"><h3 className="font-black dark:text-white uppercase tracking-tight leading-tight">{user.name}</h3><p className={`text-[10px] font-black uppercase tracking-widest mt-0.5 ${user.isOnline ? 'text-green-500' : 'text-gray-400'}`}>{user.isOnline ? 'Online agora' : 'Visto ' + user.lastSeen}</p></div>
                <div className="w-8 h-8 rounded-full bg-gray-50 dark:bg-gray-700 flex items-center justify-center text-gray-300"><i className="fas fa-chevron-right text-xs"></i></div>
              </div>
            ))}
          </div>
        </div>
      )}
    </Layout>
  );
};

export default Chat;

import React, { useState, useEffect, useContext } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import Footer from '../components/Footer';
import { storage } from '../services/storage';
import { Publication, Language } from '../types';
import { LanguageContext } from '../App';
import { t } from '../services/i18n';

const ACCESS_KEY = '000000';

const Communities: React.FC = () => {
  const { tab } = useParams<{ tab: string }>();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<string>(tab || 'geral');
  const [publications, setPublications] = useState<Publication[]>([]);
  const [isAuth, setIsAuth] = useState(false);
  const [accessKeyInput, setAccessKeyInput] = useState('');
  const [loginError, setLoginError] = useState('');
  const [form, setForm] = useState({ title: '', category: 'geral', content: '' });
  const [successMsg, setSuccessMsg] = useState('');
  const { language } = useContext(LanguageContext);

  useEffect(() => {
    setPublications(storage.getPublications());
    storage.setLastViewedPubs(); // Marcar comunicados como vistos
  }, []);

  useEffect(() => {
    if (tab && tab !== activeTab) {
      setActiveTab(tab);
      setLoginError('');
      setAccessKeyInput('');
      storage.setLastViewedPubs(); // Atualizar visto ao navegar entre abas
    }
  }, [tab, activeTab]);

  const handleTabChange = (tabId: string) => {
    setActiveTab(tabId);
    navigate(`/communities/${tabId}`, { replace: true });
  };

  const handleLogin = () => {
    if (accessKeyInput === ACCESS_KEY) {
      setIsAuth(true);
      setLoginError('');
    } else {
      setLoginError(language === Language.PT ? 'Chave de acesso incorreta!' : 'Access key incorrect!');
    }
  };

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    const newPub: Publication = {
      id: Date.now(),
      title: form.title,
      category: form.category,
      content: form.content,
      date: new Date().toISOString()
    };

    const updated = [newPub, ...publications];
    setPublications(updated);
    storage.setPublications(updated);
    storage.setLastViewedPubs(); // Atualizar após publicar
    setForm({ title: '', category: 'geral', content: '' });
    setSuccessMsg(language === Language.PT ? 'Informação publicada com sucesso!' : 'Information published successfully!');
    setTimeout(() => {
      setSuccessMsg('');
      handleTabChange(form.category);
    }, 1500);
  };

  const tabs = [
    { id: 'geral', label: 'Geral', icon: 'fa-info-circle' },
    { id: 'ano1', label: '1º Ano', icon: 'fa-user-graduate' },
    { id: 'ano2', label: '2º Ano', icon: 'fa-user-graduate' },
    { id: 'ano3', label: '3º Ano', icon: 'fa-user-graduate' },
    { id: 'ano4', label: '4º Ano', icon: 'fa-user-graduate' },
    { id: 'publicar', label: t('publish', language), icon: 'fa-plus-circle' },
  ];

  const filtered = publications.filter(pub => {
    if (activeTab === 'geral') return pub.category === 'geral';
    if (activeTab === 'publicar') return false;
    return pub.category === activeTab || pub.category === 'geral';
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-ev-dark">
      <header className="bg-ev-blue text-white px-4 py-3 flex items-center justify-between shadow-md z-50">
        <div className="flex items-center gap-4">
          <Link to="/" className="hover:scale-110 transition-transform">
            <i className="fas fa-arrow-left text-xl"></i>
          </Link>
          <h1 className="text-xl font-bold tracking-tight uppercase tracking-tighter">{t('communities', language)}</h1>
        </div>
      </header>

      <div className="bg-ev-blue shadow-lg border-t border-white/10 z-40 sticky top-[52px]">
        <div className="max-w-6xl mx-auto flex overflow-x-auto no-scrollbar">
          {tabs.map(tabItem => (
            <button
              key={tabItem.id}
              onClick={() => handleTabChange(tabItem.id)}
              className={`flex-shrink-0 flex flex-col items-center justify-center py-4 px-8 transition-all min-w-[100px] border-b-4 ${
                activeTab === tabItem.id ? 'bg-ev-brown border-white text-white' : 'text-white/60 border-transparent hover:bg-white/10'
              }`}
            >
              <i className={`fas ${tabItem.icon} mb-1 text-sm`}></i>
              <span className="text-[10px] font-black uppercase tracking-widest">{tabItem.label}</span>
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-4xl mx-auto w-full p-6 flex-1 py-10">
        {activeTab === 'publicar' ? (
          <div className="bg-white dark:bg-gray-800 p-8 md:p-12 rounded-4xl shadow-xl border border-gray-100 dark:border-gray-700 animate-fadeIn">
            <h2 className="text-3xl font-black text-ev-blue dark:text-white uppercase tracking-tighter mb-8 text-center">{t('publish', language)}</h2>

            {!isAuth ? (
              <div className="max-w-sm mx-auto space-y-6 text-center py-6">
                <div className="w-20 h-20 bg-ev-blue/10 rounded-full flex items-center justify-center text-ev-blue mx-auto mb-4 border-2 border-ev-brown">
                  <i className="fas fa-lock text-3xl"></i>
                </div>
                <div className="space-y-2">
                  <p className="text-gray-800 dark:text-white font-bold uppercase text-xs tracking-widest">Acesso Restrito</p>
                  <p className="text-gray-500 text-xs leading-relaxed">Apenas delegados e docentes podem emitir comunicados oficiais.</p>
                </div>
                {loginError && <p className="text-red-500 text-[10px] font-black uppercase bg-red-50 p-3 rounded-2xl border border-red-100">{loginError}</p>}
                <input
                  type="password"
                  placeholder="DIGITE A CHAVE"
                  className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-center text-lg font-black tracking-[0.4em] shadow-inner focus:ring-2 focus:ring-ev-blue"
                  value={accessKeyInput}
                  onChange={(e) => setAccessKeyInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
                />
                <button 
                  onClick={handleLogin}
                  className="w-full bg-ev-blue text-white py-4 rounded-3xl font-black shadow-lg hover:bg-blue-600 transition-all uppercase tracking-widest text-xs"
                >
                  Verificar Acesso
                </button>
              </div>
            ) : (
              <form onSubmit={handlePublish} className="space-y-6">
                {successMsg && <div className="bg-green-100 text-green-700 p-4 rounded-3xl font-black text-center animate-bounce uppercase text-xs tracking-widest shadow-sm">{successMsg}</div>}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Título do Comunicado</label>
                    <input
                      type="text"
                      required
                      placeholder="Ex: Entrega de Notas"
                      className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white shadow-inner focus:ring-2 focus:ring-ev-blue font-bold"
                      value={form.title}
                      onChange={(e) => setForm({ ...form, title: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Canal de Destino</label>
                    <select
