              <div className="relative"><input type="text" placeholder={t('search', language)} className="w-full md:w-80 bg-white dark:bg-gray-800 border-none rounded-full px-6 py-4 text-sm focus:ring-2 focus:ring-ev-blue shadow-sm dark:text-white" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} /><i className="fas fa-search absolute right-6 top-1/2 -translate-y-1/2 text-gray-300"></i></div>
