                      <h3 className="text-xl font-black text-gray-800 dark:text-white mb-2 leading-tight uppercase tracking-tight">{item.title}</h3>
                      <p className="text-[10px] text-ev-brown font-black mb-4 uppercase italic">Autor: {item.author}</p>
                      <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 line-clamp-3 leading-relaxed">{item.description}</p>
                      <div className="flex items-center justify-between pt-6 border-t border-gray-50 dark:border-gray-700"><a href={item.downloadUrl} target="_blank" rel="noopener noreferrer" className="text-ev-blue font-black text-[10px] uppercase tracking-widest hover:underline"><i className="fas fa-eye mr-1"></i> {t('view', language)}</a><a href={item.downloadUrl} download={`${item.title}.pdf`} className="bg-ev-blue text-white px-5 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-blue-600 transition-colors"><i className="fas fa-download mr-1"></i> {t('download', language)}</a></div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}
      </main>
      <Footer />
    </div>
  );
};

