import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { storage } from '../services/storage';
import { User } from '../types';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [formData, setFormData] = useState({ name: '', number: '', password: '', confirmPassword: '', photo: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const formatStudentNumber = (value: string) => {
    const digits = value.replace(/\D/g, '');
    let formatted = digits;
    if (digits.length > 2) formatted = `${digits.substring(0, 2)}.${digits.substring(2)}`;
    if (digits.length > 6) formatted = `${digits.substring(0, 2)}.${digits.substring(2, 6)}.${digits.substring(6, 10)}`;
    return formatted.substring(0, 12);
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, number: formatStudentNumber(e.target.value) });
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => setFormData({ ...formData, photo: event.target?.result as string });
      reader.readAsDataURL(file);
    }
  };

  const calculateYearFromNumber = (number: string): number => {
    const parts = number.split('.');
    if (parts.length < 3) return 1;
    const yearSuffix = parseInt(parts[2]);
    return isNaN(yearSuffix) ? 1 : Math.max(1, 2027 - yearSuffix);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const users = storage.getUsers();

    if (isRegister) {
      if (formData.password !== formData.confirmPassword) { setError('Senhas não coincidem'); setLoading(false); return; }
      if (users.some(u => u.Number === formData.number)) { setError('Este número já está registrado'); setLoading(false); return; }

      const newUser: User = {
        id: 'u_' + Math.random().toString(36).substr(2, 9),
        name: formData.name,
        Number: formData.number,
        password: formData.password,
        photo: formData.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=',
        anoFrequencia: calculateYearFromNumber(formData.number)
      };
      storage.setUsers([...users, newUser]);
      storage.setCurrentUserId(newUser.id);
    } else {
      const user = users.find(u => u.Number === formData.number && u.password === formData.password);
      if (!user) { setError('Credenciais incorretas'); setLoading(false); return; }
      storage.setCurrentUserId(user.id);
    }

    setTimeout(() => { onLogin(); navigate('/'); }, 800);
  };

  return (
    <div className="min-h-screen bg-ev-blue flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-5xl shadow-2xl overflow-hidden animate-fadeIn">
        <div className="p-10 text-center bg-gray-50 dark:bg-gray-900/50 border-b border-gray-100">
          <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl border-4 border-ev-brown overflow-hidden">
            <i className="fas fa-graduation-cap text-ev-blue text-4xl"></i>
          </div>
          <h1 className="text-2xl font-black text-ev-blue uppercase tracking-widest">{isRegister ? 'Cadastro' : 'Entrar'}</h1>
          <p className="text-gray-400 text-[10px] mt-1 font-black uppercase tracking-[0.3em]">Plataforma EV-UL</p>
        </div>

        <div className="p-10">
          <form onSubmit={handleSubmit} className="space-y-5">
            {error && <div className="bg-red-50 text-red-500 p-4 rounded-3xl text-xs font-bold text-center border border-red-100 animate-bounce">{error}</div>}

            {isRegister && (
              <div className="flex flex-col items-center gap-3 mb-6">
                <div className="relative w-24 h-24 rounded-full overflow-hidden border-4 border-ev-blue shadow-inner bg-gray-50 flex items-center justify-center">
                  {formData.photo ? <img src={formData.photo} className="w-full h-full object-cover" alt="" /> : <i className="fas fa-user text-gray-300 text-3xl"></i>}
                  <input type="file" accept="image/*" onChange={handlePhotoChange} className="absolute inset-0 opacity-0 cursor-pointer" />
                </div>
                <span className="text-[10px] text-gray-400 font-black uppercase tracking-widest">Foto de Perfil</span>
              </div>
            )}

            {isRegister && (
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Nome Completo</label>
                <input type="text" required className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
              </div>
            )}

            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Número de Estudante</label>
              <input type="text" required placeholder="00.0000.0000" className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner" value={formData.number} onChange={handleNumberChange} />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Senha</label>
              <input type="password" required className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner" value={formData.password} onChange={(e) => setFormData({ ...formData, password: e.target.value })} />
            </div>

            {isRegister && (
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Confirmar Senha</label>
                <input type="password" required className="w-full p-4 rounded-3xl border-none bg-gray-50 dark:bg-gray-700 dark:text-white text-sm focus:ring-2 focus:ring-ev-blue shadow-inner" value={formData.confirmPassword} onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })} />
              </div>
            )}

            <button type="submit" disabled={loading} className="w-full bg-ev-blue text-white py-5 rounded-3xl font-black shadow-xl hover:bg-blue-600 transition-all uppercase tracking-widest flex items-center justify-center gap-3 mt-4 active:scale-95">
              {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <>{isRegister ? 'Criar Conta' : 'Entrar na Plataforma'}</>}
            </button>
          </form>

          <div className="mt-8 flex flex-col gap-4 text-center">
            <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="text-ev-blue text-xs font-black uppercase tracking-widest hover:underline">{isRegister ? 'Já tem uma conta? Entre aqui' : 'Novo no curso? Cadastre-se'}</button>
            <Link to="/" className="text-gray-400 hover:text-ev-blue transition-colors text-[10px] font-black uppercase tracking-widest"><i className="fas fa-eye mr-2"></i> Entrar como Visitante</Link>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { storage } from '../services/storage';
import { User, Message } from '../types';

const Chat: React.FC = () => {
  const navigate = useNavigate();
  const [selectedUser, setSelectedUser] = useState<User | 'general' | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [showMediaMenu, setShowMediaMenu] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [fullScreenImage, setFullScreenImage] = useState<string | null>(null);

  const currentUser = storage.getCurrentUser();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  const usersWithStatus = useMemo(() => {
    return storage.getUsers().map(u => ({
      ...u,
      isOnline: u.id === currentUser?.id ? true : Math.random() > 0.4,
      lastSeen: u.id === currentUser?.id ? 'Agora' : 'Há ' + Math.floor(Math.random() * 59) + ' min'
    }));
  }, [currentUser?.id]);

  useEffect(() => {
    setMessages(storage.getMessages());
    storage.setLastViewedChat(); // Marcar mensagens como vistas
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, selectedUser]);

  useEffect(() => {
    const handlePopState = () => {
      if (selectedUser) {
        setSelectedUser(null);
        window.history.pushState(null, '', window.location.href);
      }
    };
    if (selectedUser) {
      window.history.pushState(null, '', window.location.href);
      window.addEventListener('popstate', handlePopState);
    }
    return () => window.removeEventListener('popstate', handlePopState);
  }, [selectedUser]);

  const saveMessage = (msg: Partial<Message>) => {
    if (!selectedUser || !currentUser) return;
    const newMessage: Message = {
      authorId: currentUser.id,
      text: msg.text || '',
      time: Date.now(),
      to: typeof selectedUser === 'string' ? 'general' : selectedUser.id,
      media: msg.media,
      mediaType: msg.mediaType,
      fileName: msg.fileName
    };
    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);
    storage.setMessages(updatedMessages);
    storage.setLastViewedChat(); // Atualizar visto ao enviar
  };

  const handleSend = () => {
    if (!inputText.trim()) return;
    saveMessage({ text: inputText });
    setInputText('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'image' | 'video' | 'audio') => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (type === 'video') {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 30) {
          alert('O vídeo não pode ter mais de 30 segundos.');
          return;
        }
        processFile(file);
      };
      video.src = URL.createObjectURL(file);
    } else processFile(file);
    setShowMediaMenu(false);
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      saveMessage({ media: event.target?.result as string, mediaType: file.type, fileName: file.name });
    };
    reader.readAsDataURL(file);
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      mediaRecorderRef.current = recorder;
      audioChunksRef.current = [];
      recorder.ondataavailable = (e) => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      recorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.onload = (e) => saveMessage({ media: e.target?.result as string, mediaType: 'audio/webm', fileName: `record_${Date.now()}.webm` });
        reader.readAsDataURL(audioBlob);
        stream.getTracks().forEach(track => track.stop());
      };
      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch { alert('Não foi possível acessar o microfone.'); }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const downloadMedia = (media: string, fileName: string) => {
    const link = document.createElement('a');
    link.href = media; link.download = fileName;
    document.body.appendChild(link); link.click();
    document.body.removeChild(link);
  };

  const filteredMessages = messages.filter(m => {
    if (!selectedUser || !currentUser) return false;
    if (selectedUser === 'general') return m.to === 'general';
    return (m.authorId === currentUser.id && m.to === selectedUser.id) || (m.authorId === selectedUser.id && m.to === currentUser.id);
  }).sort((a, b) => a.time - b.time);

  const getAuthorName = (authorId: string) => authorId === currentUser?.id ? 'Você' : usersWithStatus.find(u => u.id === authorId)?.name || 'Usuário';
  const getAuthorPhoto = (authorId: string) => usersWithStatus.find(u => u.id === authorId)?.photo || 'data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cmVjdCB3aWR0aD0iMTIwIiBoZWlnaHQ9IjEyMCIgZmlsbD0iI2NjYyIvPjx0ZXh0IHg9IjUwJSIgeT0iNTAlIiBmb250LXNpemU9IjQwIiBmaWxsPSIjZmZmIiB0ZXh0LWFuY2hvcj0ibWlkZGxlIiBkeT0iLjNlbSI+8J+RpDwvdGV4dD48L3N2Zz4=';

  // Renderização da Tela de Chat (Full Screen)
  if (selectedUser) {
    const user = selectedUser === 'general' ? {
      name: 'Chat Geral',
      photo: 'https://picsum.photos/seed/general/200',
      isOnline: true,
      lastSeen: ''
    } : selectedUser;

    return (
      <div className="flex flex-col h-screen bg-gray-100 dark:bg-gray-900 animate-fadeIn relative overflow-hidden">
        {fullScreenImage && (
          <div className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 animate-fadeIn backdrop-blur-sm" onClick={() => setFullScreenImage(null)}>
            <button className="absolute top-6 right-6 text-white text-3xl hover:scale-125 transition-transform"><i className="fas fa-times"></i></button>
            <img src={fullScreenImage} className="max-w-full max-h-full object-contain rounded-lg shadow-2xl animate-zoomIn" alt="Full screen" onClick={(e) => e.stopPropagation()} />
          </div>
        )}

        {/* Cabeçalho Fixo Full Screen */}
        <header className="bg-ev-blue text-white px-3 py-3 flex items-center gap-3 shadow-md z-20 shrink-0">
          <button 
            onClick={() => setSelectedUser(null)} 
            className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-white/10 transition-colors"
          >
            <i className="fas fa-arrow-left text-lg"></i>
          </button>

          <div className="flex items-center gap-3 flex-1 overflow-hidden cursor-pointer" onClick={() => setFullScreenImage(user.photo)}>
            <div className="relative shrink-0">
              <img 
                src={user.photo} 
                className="w-10 h-10 rounded-full object-cover border-2 border-white/20" 
                alt="" 
              />
              {(selectedUser === 'general' || user.isOnline) && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-400 border-2 border-ev-blue rounded-full"></div>}
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-bold text-base leading-tight truncate">{user.name}</h3>
              <p className="text-[10px] text-ev-text-light font-medium uppercase tracking-widest truncate">
                {selectedUser === 'general' ? 'Online' : (user.isOnline ? 'Online' : `Visto ${user.lastSeen}`)}
              </p>
            </div>
          </div>
        </header>

        {/* Área de Mensagens Expandida */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-gray-50/50 dark:bg-black/20" style={{backgroundImage: "url('https://www.transparenttextures.com/patterns/subtle-white-feathers.png')", backgroundBlendMode: 'multiply'}}>
          {filteredMessages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-40">
              <i className="fas fa-comments text-7xl mb-4 text-gray-300 dark:text-gray-600"></i>
              <p className="font-black uppercase tracking-widest text-xs text-gray-400">Inicie uma conversa</p>
            </div>
          ) : (
            filteredMessages.map((msg, idx) => {
              const isMine = msg.authorId === currentUser?.id;
              return (
                <div key={idx} className={`flex ${isMine ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                  <div className={`flex gap-2 max-w-[85%] sm:max-w-[70%] ${isMine ? 'flex-row-reverse' : 'flex-row'}`}>
                    {!isMine && <img src={getAuthorPhoto(msg.authorId)} onClick={() => setFullScreenImage(getAuthorPhoto(msg.authorId))} className="w-8 h-8 rounded-full flex-shrink-0 mt-1 shadow-sm cursor-pointer hover:scale-110 transition-transform border border-gray-200 dark:border-gray-700" alt="" />}
                    <div className="flex flex-col">
                      {selectedUser === 'general' && !isMine && <p className="text-[10px] font-black text-ev-blue ml-2 mb-0.5 uppercase tracking-tighter">{getAuthorName(msg.authorId)}</p>}
                      <div className={`p-3 rounded-2xl text-sm shadow-sm relative group ${isMine ? 'bg-ev-blue text-white rounded-tr-none' : 'bg-white dark:bg-gray-800 dark:text-gray-200 rounded-tl-none border border-gray-100 dark:border-gray-700'}`}>
                        {msg.text && <p className="leading-relaxed whitespace-pre-wrap">{msg.text}</p>}
                        {msg.media && (
                          <div className="mt-2 space-y-2">
                            {msg.mediaType?.startsWith('image/') ? <img src={msg.media} onClick={() => setFullScreenImage(msg.media!)} className="max-w-full rounded-lg shadow-md cursor-pointer hover:opacity-95" alt="" /> : msg.mediaType?.startsWith('video/') ? <video src={msg.media} controls className="max-w-full rounded-lg shadow-md" /> : msg.mediaType?.startsWith('audio/') ? <audio src={msg.media} controls className="max-w-full h-10" /> : null}
                            <button onClick={() => downloadMedia(msg.media!, msg.fileName || 'anexo')} className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest py-1.5 px-4 rounded-full transition-all mt-1 ${isMine ? 'bg-white/20 hover:bg-white/30 text-white' : 'bg-ev-blue/10 hover:bg-ev-blue text-ev-blue hover:text-white'}`}><i className="fas fa-download"></i> Baixar</button>
