                        <p className={`text-[9px] mt-1 text-right font-black uppercase tracking-widest ${isMine ? 'text-white/70' : 'text-gray-400'}`}>{new Date(msg.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
