import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { storage } from '../services/storage';
import { User, UserRole } from '../types';

interface LoginProps {
  onLogin: () => void;
}

const ADMIN_CODE = "aDmiN26";

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [userType, setUserType] = useState<UserRole>('student');
  const [isRegister, setIsRegister] = useState(false); // Apenas para estudantes

  // Form States
  const [formData, setFormData] = useState({ 
    name: '', 
    number: '', 
    password: '', 
    confirmPassword: '', 
    photo: '',
    accessCode: '',
    selectedYear: '1'
  });

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const formatStudentNumber = (value: string) => {
    const digits = value.replace(/\D/g, '');
    let formatted = digits;
    if (digits.length > 2) formatted = `${digits.substring(0, 2)}.${digits.substring(2)}`;
    if (digits.length > 6) formatted = `${digits.substring(0, 2)}.${digits.substring(2, 6)}.${digits.substring(6, 10)}`;
    return formatted.substring(0, 12);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => setFormData({ ...formData, photo: event.target?.result as string });
      reader.readAsDataURL(file);
    }
  };

  const calculateYearFromNumber = (number: string): number => {
    const parts = number.split('.');
    if (parts.length < 3) return 1;
    const yearSuffix = parseInt(parts[2]);
    return isNaN(yearSuffix) ? 1 : Math.max(1, 2027 - yearSuffix);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const users = storage.getUsers();

    // LOGICA PARA ESTUDANTES (PADRÃO)
    if (userType === 'student') {
      if (isRegister) {
        if (formData.password !== formData.confirmPassword) { setError('Senhas não coincidem'); setLoading(false); return; }
        if (users.some(u => u.Number === formData.number)) { setError('Este número já está registrado'); setLoading(false); return; }

        const newUser: User = {
          id: 'u_' + Math.random().toString(36).substr(2, 9),
          name: formData.name,
          Number: formData.number,
          password: formData.password,
          photo: formData.photo || 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png',
          anoFrequencia: calculateYearFromNumber(formData.number),
          role: 'student'
        };
        storage.setUsers([...users, newUser]);
        storage.setCurrentUserId(newUser.id);
      } else {
        const user = users.find(u => u.Number === formData.number && u.password === formData.password && u.role === 'student');
        if (!user) { setError('Credenciais incorretas'); setLoading(false); return; }
        storage.setCurrentUserId(user.id);
      }
    } 
    // LOGICA PARA CHEFES E DOCENTES
    else {
      if (formData.accessCode !== ADMIN_CODE) {
        setError('Código de acesso inválido.');
        setLoading(false);
        return;
      }

      // Verifica se já existe um usuário com esse nome/role para "logar" ou cria um novo
      // Nota: Como não tem senha, baseamos no Nome + Role para persistência simples neste demo
      let user = users.find(u => u.name === formData.name && u.role === userType);

      if (!user) {
        // Criar novo usuário especial
        user = {
          id: 's_' + Math.random().toString(36).substr(2, 9),
          name: formData.name,
          photo: formData.photo || (userType === 'docente' ? 'https://cdn-icons-png.flaticon.com/512/3135/3135768.png' : 'https://cdn-icons-png.flaticon.com/512/3135/3135823.png'),
          anoFrequencia: userType === 'chefe' ? parseInt(formData.selectedYear) : 0,
          role: userType,
          // Docentes e chefes não precisam de Number/Password neste fluxo, validado pelo código
        };
        storage.setUsers([...users, user]);
      }

      storage.setCurrentUserId(user.id);
    }

    setTimeout(() => { onLogin(); navigate('/'); }, 800);
  };

  const getRoleIcon = (role: UserRole) => {
    switch(role) {
      case 'docente': return 'fa-chalkboard-teacher';
      case 'chefe': return 'fa-user-tie';
      default: return 'fa-user-graduate';
    }
  };

  const getRoleLabel = (role: UserRole) => {
    switch(role) {
      case 'docente': return 'Docente';
      case 'chefe': return 'Chefe de Turma';
      default: return 'Estudante';
    }
  };

  return (
    <div className="min-h-screen bg-ev-blue flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white dark:bg-gray-800 rounded-5xl shadow-2xl overflow-hidden animate-fadeIn">
        <div className="p-8 text-center bg-gray-50 dark:bg-gray-900/50 border-b border-gray-100">
          <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-xl border-4 border-ev-brown overflow-hidden">
