import React, { useState, useEffect, useCallback, createContext } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Home from './views/Home';
import About from './views/About';
import Chat from './views/Chat';
import Communities from './views/Communities';
import ArtGallery from './views/ArtGallery';
import UserPosts from './views/UserPosts';
import Settings from './views/Settings';
import Login from './views/Login';
import Library from './views/Library';
import { storage } from './services/storage';
import { notificationService } from './services/notifications';
import { Theme, Language } from './types';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
}

export const LanguageContext = createContext<LanguageContextType>({
  language: Language.PT,
  setLanguage: () => {},
});

const AppContent: React.FC = () => {
  const [theme, setTheme] = useState<Theme>(storage.getTheme());
  const [language, setLanguageState] = useState<Language>(storage.getLanguage());
  const [isAuth, setIsAuth] = useState<boolean>(!!storage.getCurrentUserId());

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    storage.setLanguage(lang);
  };

  useEffect(() => {
    // Solicitar permissão de notificação ao iniciar
    notificationService.requestPermission();

    if (theme === Theme.DARK) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    storage.setTheme(theme);
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme(prev => (prev === Theme.LIGHT ? Theme.DARK : Theme.LIGHT));
  }, []);

  const handleLoginStatus = useCallback(() => {
    setIsAuth(!!storage.getCurrentUserId());
  }, []);

  const handleLogout = useCallback(() => {
    storage.logout();
    setIsAuth(false);
  }, []);

  const requiresAuth = (component: React.ReactNode) => {
    return isAuth ? component : <Navigate to="/login" replace />;
  };

  const requiresNonDocente = (component: React.ReactNode) => {
    const user = storage.getCurrentUser();
    if (!isAuth) return <Navigate to="/login" replace />;
    if (user?.role === 'docente') return <Navigate to="/" replace />;
    return component;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      <div className="min-h-screen bg-gray-50 dark:bg-ev-dark transition-colors duration-200">
        <Routes>
          <Route path="/" element={<Home toggleTheme={toggleTheme} isDark={theme === Theme.DARK} onLogout={handleLogout} />} />
          <Route path="/about" element={<About />} />
          {/* Chat restrito para docentes */}
          <Route path="/chat" element={requiresNonDocente(<Chat />)} />
          <Route path="/communities" element={requiresAuth(<Communities />)} />
          <Route path="/communities/:tab" element={requiresAuth(<Communities />)} />
          <Route path="/gallery" element={<ArtGallery />} />
          <Route path="/posts" element={<UserPosts />} />
          <Route path="/library/:category" element={<Library />} />
          <Route path="/settings" element={requiresAuth(<Settings onLogout={handleLogout} toggleTheme={toggleTheme} isDark={theme === Theme.DARK} />)} />
          <Route path="/login" element={<Login onLogin={handleLoginStatus} />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </LanguageContext.Provider>
  );
};

const App: React.FC = () => {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
};

export default App;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { storage } from '../services/storage';
import { User, UserRole } from '../types';

interface LoginProps {
  onLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [userType, setUserType] = useState<UserRole>('student');
  const [isRegister, setIsRegister] = useState(false);

  // Form States
  const [formData, setFormData] = useState({ 
    name: '', 
    number: '', 
    password: '', 
    confirmPassword: '', 
    photo: '',
    accessCode: '',
    selectedYear: '1'
  });

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const formatStudentNumber = (value: string) => {
    const digits = value.replace(/\D/g, '');
    let formatted = digits;
    if (digits.length > 2) formatted = `${digits.substring(0, 2)}.${digits.substring(2)}`;
    if (digits.length > 6) formatted = `${digits.substring(0, 2)}.${digits.substring(2, 6)}.${digits.substring(6, 10)}`;
    return formatted.substring(0, 12);
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => setFormData({ ...formData, photo: event.target?.result as string });
      reader.readAsDataURL(file);
    }
  };

  const calculateYearFromNumber = (number: string): number => {
    const parts = number.split('.');
    if (parts.length < 3) return 1;
    const yearSuffix = parseInt(parts[2]);
    return isNaN(yearSuffix) ? 1 : Math.max(1, 2027 - yearSuffix);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    const users = storage.getUsers();

    // ==========================================
    // LÓGICA DE ESTUDANTE
    // ==========================================
    if (userType === 'student') {
      if (isRegister) {
        if (formData.password !== formData.confirmPassword) { setError('Senhas não coincidem'); setLoading(false); return; }
        if (users.some(u => u.Number === formData.number)) { setError('Este número já está registrado'); setLoading(false); return; }

        const newUser: User = {
          id: 'u_' + Math.random().toString(36).substr(2, 9),
          name: formData.name,
          Number: formData.number,
          password: formData.password,
          photo: formData.photo || 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png',
          anoFrequencia: calculateYearFromNumber(formData.number),
          role: 'student'
        };
        storage.setUsers([...users, newUser]);
        storage.setCurrentUserId(newUser.id);
      } else {
        const user = users.find(u => u.Number === formData.number && u.password === formData.password && u.role === 'student');
        if (!user) { setError('Credenciais incorretas'); setLoading(false); return; }
        storage.setCurrentUserId(user.id);
      }
    } 
    // ==========================================
    // LÓGICA DE CHEFE E DOCENTE
    // ==========================================
    else {
      // --- CADASTRO ---
      if (isRegister) {
        if (!formData.name.trim()) { setError('Nome é obrigatório'); setLoading(false); return; }

        // Validação Código Chefe: Chefe1, Chefe2, Chefe3, Chefe4
        if (userType === 'chefe') {
            const expectedCode = `Chefe${formData.selectedYear}`;
            if (formData.accessCode !== expectedCode) {
                setError(`Código inválido para o ${formData.selectedYear}º Ano. Use: ${expectedCode}`);
                setLoading(false); 
                return;
            }
            // Verificar se já existe chefe para este ano (opcional, mas recomendado)
            const existingChefe = users.find(u => u.role === 'chefe' && u.anoFrequencia === parseInt(formData.selectedYear));
            if (existingChefe) {
                setError(`Já existe um Chefe registado para o ${formData.selectedYear}º Ano.`);
                setLoading(false);
                return;
            }
        }

        // Validação Código Docente: @PrimeiroNome
        if (userType === 'docente') {
            const firstName = formData.name.trim().split(' ')[0];
            const expectedCode = `@${firstName}`;
            if (formData.accessCode !== expectedCode) {
                setError(`Código inválido. Para o nome "${firstName}", use: ${expectedCode}`);
                setLoading(false);
                return;
            }
        }

        const newUser: User = {
          id: 's_' + Math.random().toString(36).substr(2, 9),
          name: formData.name,
          photo: formData.photo || (userType === 'docente' ? 'https://cdn-icons-png.flaticon.com/512/3135/3135768.png' : 'https://cdn-icons-png.flaticon.com/512/3135/3135823.png'),
          anoFrequencia: userType === 'chefe' ? parseInt(formData.selectedYear) : 0,
          role: userType
        };
        storage.setUsers([...users, newUser]);
        storage.setCurrentUserId(newUser.id);

      } 
      // --- LOGIN (APENAS CÓDIGO) ---
      else {
        const code = formData.accessCode.trim();
        let user: User | undefined;

        if (userType === 'chefe') {
            // Código esperado: Chefe1, Chefe2...
            if (!code.startsWith('Chefe')) { setError('Formato de código inválido.'); setLoading(false); return; }
            const yearStr = code.replace('Chefe', '');
            const year = parseInt(yearStr);

            if (isNaN(year)) { setError('Código inválido.'); setLoading(false); return; }

            user = users.find(u => u.role === 'chefe' && u.anoFrequencia === year);
        } 
        else if (userType === 'docente') {
            // Código esperado: @Nome
            if (!code.startsWith('@')) { setError('Formato de código inválido.'); setLoading(false); return; }
            const namePart = code.substring(1); // Remove o @

            // Procura um docente cujo primeiro nome corresponda
            user = users.find(u => u.role === 'docente' && u.name.split(' ')[0] === namePart);
        }

        if (!user) {
            setError('Usuário não encontrado ou código incorreto. Cadastre-se primeiro.');
            setLoading(false);
            return;
        }

        storage.setCurrentUserId(user.id);
      }
    }

    setTimeout(() => { onLogin(); navigate('/'); }, 800);
  };

  const getRoleIcon = (role: UserRole) => {
    switch(role) {
      case 'docente': return 'fa-chalkboard-teacher';
      case 'chefe': return 'fa-user-tie';
      default: return 'fa-user-graduate';
    }
  };

  const getRoleLabel = (role: UserRole) => {
    switch(role) {
      case 'docente': return 'Docente';
      case 'chefe': return 'Chefe de Turma';
      default: return 'Estudante';
    }
  };

  return (
    <div className="min-h-screen bg-ev-blue flex items-center justify-center p-6">
