            <button
              key={role}
              onClick={() => { setUserType(role); setError(''); setIsRegister(false); setFormData({...formData, name: '', accessCode: '', number: '', password: ''}); }}
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${
                userType === role 
