    { url: "https://picsum.photos/seed/painting/800/600", caption: "Criatividade e Arte" },
    { url: "https://picsum.photos/seed/students/800/600", caption: "Excelência Académica" },
    { url: "https://picsum.photos/seed/campus/800/600", caption: "Campus Coalane - Quelimane" },
    { url: "https://picsum.photos/seed/future/800/600", caption: "Futuro da Educação" },
    { url: "https://picsum.photos/seed/library/800/600", caption: "Campus Universitário" },
    { url: "https://picsum.photos/seed/community/800/600", caption: "Comunidade EV-UL" }
  ];

  const stats = [
    { label: `${t('students', language)} 1º Ano`, value: 38 },
    { label: `${t('students', language)} 2º Ano`, value: 26 },
    { label: `${t('students', language)} 3º Ano`, value: 22 },
    { label: `${t('students', language)} 4º Ano`, value: 20 },
    { label: t('professors', language), value: 7 }
  ];

  const staff = [
    { name: "Dr. Samuel Bernardo Phuelle", role: "Director do Curso", email: "samuelphuelle@unilicungo.ac.mz" },
    { name: "Enoque", role: "Chefe de Turma - 1º Ano", email: "enoque@unilicungo.ac.mz" },
    { name: "Lapson Esmael", role: "Chefe de Turma - 2º Ano", email: "lapson@unilicungo.ac.mz" },
    { name: "Gavini Fernando", role: "Chefe de Turma - 3º Ano", email: "gavini@unilicungo.ac.mz" },
    { name: "Paulo Cumbane", role: "Chefe de Turma - 4º Ano", email: "paulo@unilicungo.ac.mz" }
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 5000);

    const lastChatView = storage.getLastViewedChat();
    const lastPubsView = storage.getLastViewedPubs();
    const messages = storage.getMessages();
    const publications = storage.getPublications();

    setHasNewMessages(messages.some(m => m.time > lastChatView));
    setHasNewPubs(publications.some(p => new Date(p.date).getTime() > lastPubsView));

    return () => clearInterval(timer);
  }, [slides.length]);

  const toggleDropdown = (id: string) => {
    setOpenDropdown(openDropdown === id ? null : id);
  };

  const currentUser = storage.getCurrentUser();

  const handleLogoutClick = () => {
    onLogout();
    navigate('/login');
  };

  const cycleLanguage = () => {
    if (language === Language.PT) setLanguage(Language.EN);
    else if (language === Language.EN) setLanguage(Language.FR);
    else setLanguage(Language.PT);
  };

  const RedDot = () => (
    <span className="absolute top-3 right-1/2 translate-x-4 flex h-2.5 w-2.5">
      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
      <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-red-500"></span>
